window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["26969935"]={"book":{"id":26969935,"title":"故事思维","author":"[美] 安妮特·西蒙斯（Annette Simmons）","translator":"俞沈彧","publisher":"后浪丨江西人民出版社","pubdate":"2017-3","isbn":"9787210075172","tags":["思维","故事","沟通","如何说好一个故事","表达","写作","自我管理","心理学"],"memCount":12},"np":1,"pb":[20],"idx":[{"i":18366,"t":" 怎样讲好“我是谁”的故事","l":"TF1-2","c":"绘宇","g":1,"p":1},{"i":18365,"t":"三倍提升你的可信任度","l":"TF1-1","c":"绘宇","g":1,"p":1},{"i":10196,"t":"三倍提升你的可信任度","l":"TF2-3","c":"易伯伯","g":1,"p":1},{"i":9717,"t":"如何讲好一个故事","l":"TF2-1","c":"会跳舞的瑜小姐","g":1,"p":1},{"i":9314,"t":"如何运用故事思维","l":"TF1-1","c":"明哲","g":1,"p":1},{"i":9311,"t":"如何讲故事&讲好故事","l":"TF3-3","c":"陈蕙茗","g":1,"p":1},{"i":8419,"t":"讲有“人情味”的故事","l":"TF2-3","c":"郑春红","g":1,"p":1},{"i":7930,"t":"打造故事思维","l":"TF3-3","c":"转圈圈","g":1,"p":1},{"i":7482,"t":"@讲好“我是谁”的故事@","l":"TF3-1","c":"翔翊","g":1,"p":1},{"i":7092,"t":"讲好我是谁，赢得好人生！","l":"TF2-3","c":"郑远霞","g":1,"p":1},{"i":6781,"t":"采用讲“我是谁”的故事进行自我介绍","l":"TF2-2","c":"翔翊","g":1,"p":1},{"i":6701,"t":"讲讲好故事，好好讲故事——如何用故事收服人心","l":"TF3-3","c":"吴佳音","g":1,"p":1},{"i":6680,"t":"描述细节，述说动人故事","l":"TF1-1","c":"雷蕾","g":1,"p":1},{"i":6198,"t":"什么是故事","l":"TF3-1","c":"罗靖臣","g":1,"p":1},{"i":5533,"t":"成为一个有故事的人","l":"TF2-4","c":"妙善","g":0,"p":1},{"i":5382,"t":"换位思考","l":"TF2-3","c":"魏敏","g":1,"p":1},{"i":5293,"t":"告别无趣，让自己成为一个有故事的人","l":"TF2-4","c":"妙善","g":1,"p":1},{"i":3950,"t":"故事思维","l":"TF3-3","c":"norman","g":1,"p":1},{"i":3576,"t":"讲好“我是谁”的故事 ","l":"TF1-1","c":"quest396","g":1,"p":1},{"i":3277,"t":"教学故事，让大家学习到：如何教授别人","l":"TF2-3","c":"俊领","g":1,"p":1}],"ms":[{"id":18366,"topic":" 怎样讲好“我是谁”的故事","learn_goal":"","remark":" 片段来源于《故事思维》P.15-16，在跟随我完成这次RIA现场学习后，学习者能够讲一个“我是谁”的故事进行自我介绍，取得别人的信任。 ","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"绘宇","city":"南昌"},"club":{"name":"南昌火炬分舵","city":"南昌"},"prologue":"\u003cp>大家好欢迎来到南昌火炬分舵拆书练级1-2的活动现场。首先我给大家做个自我介绍，我叫陈绘宇。\u003cbr>我的三个标签是:\u003cbr>【分组】为了方便后续大家的交流讨论，我给大家简单分下组，左手边一组，右手边一组，谢谢大家的配合！ \u003c/p>\u003cp>\u003cstrong>【学习目标0.5分钟】\u003c/strong>\u003cbr>下面分享我今天的拆书内容，片段来源于《故事思维》P.15-16，在跟随我完成这次RIA现场学习后，学习者能够讲一个“我是谁”的故事进行自我介绍，取得别人的信任。 \u003cbr>给大家两分钟的时间先阅读原文片段，阅读完后请抬头示意我一下。\u003c/p>","ratings_count":0,"texts":[{"id":22655,"quote":"\u003cp>\u003cstrong>【原文片段 2分钟】 \u003c/strong>\u003cbr>一项由《纽约时报》和哥伦比亚广播公司新闻部在1999年进行的民意调查发现，63%的受访者相信与“大多数人”相处，你“一定要小心再小心”；37%相信“大多数人一有机会就想利用你”。如果你认为这代表了你想影响的对象，那么你首先要做的就是，证明你可以被信任。\u003cbr>如何做到呢？刚才的那个研究给了我们一个提示：应答者也表示在他们“有交情的人”当中，85%能够“尽力做到公正”。嗯……会是一件很简单的事情吗？让人们了解你是谁，促使他们认为自己与你有“私交”，那么你的信任度必然会提高三倍吗？想象一下我们的口头语：“他人不错，我了解他”或“不是因为我不信任她，我只是不了解她”。\u003cbr>我们不让人们了解我们是谁，他们怎么会信任我们，并且受到我们的影响呢？要是我们不能把说服他人的企图，与回答我们是谁很好地结合，那就无异于与人们心中的评判标准擦肩而过。我们对理性的大脑花费了太多的时间而忽略了感性的大脑。感性的大脑对于被忽视非常敏感。感性的大脑更要重视、防患于未然，虽然毫无根据，但是它更能影响人们的结论。\u003c/p>","explains":"\u003cp>【why】心理学研究表明，人类的痛苦往往源于人际关系的不良。因此人际关系一直是我们生命中至关重要的一部分。然而，人际关系也会给我们带来痛苦和压力，人类的情感需求使我们需要建立和维护亲密关系。在建立亲密关系中，其实信任是我们的第一步。\u003cbr>【What】：原文片段的民意调查，可以发现100%的人对“大多数人”存有戒心，很难做到相互信任。主要因为产生不信任的原因是人们不了解你。大家都不知道你是谁，怎么信任你呢？\u003cbr>“我是谁”的故事，具有真情实感的讲述一个关于自己的故事，或是自己的亲身经历，或是能够体现自己与众不同的其他故事，从故事中，在人们的大脑中画出你的画像，更加容易产生对这个形象的认可，从而取得信任。\u003cbr> 【How】 怎样讲好“我是谁”的故事呢？可分为三步。\u003cbr> 1、 收集故事：自己的亲身经历一般随手拿来，其他的故事需要把功夫用在平常，收集这些故事，判断这些故事可以帮助自己树立什么样的形象。\u003cbr> 2、确定目标：每次讲关于“我是谁”的故事之前，一定确定好目标是希望对方了解什么样的你，有助于提升你的影响力。\u003cbr> 3、生动表述：讲故事不是讲案例，需要生动的语言表达，有趣、有料、有结果，最终才能打动对方。\u003cbr>【举个例子】\u003cbr>\u003c/p>\u003cp>\u003cbr>【where】\u003cbr> 讲到这里了，可能有同学有疑问了，介绍自己的时候讲一个故事也太麻烦啦，简单介绍一下自己不就好了吗？是的，我们通常认为的介绍“我是谁”，仅仅限于姓名、性别、职务，从履历表上巴拉下来的数据信息，这能让别人了解你吗？不能！人们对一个人的看法，往往会带着有色眼镜来看待，凭着以往的经验判别眼前的人是否值得信赖，这种天生的防备心态，仅仅靠履历表的数据信息，无法打破人们的预防心态，反而加深了他们理性的思考：这些信息是真的吗？你无法得到对方真正的信任。而如果讲述一下亲身经历呢，一种形象代替了人们的经验判断，产生了新的经验，那么人们将更容易信任你。一般适合相对正式的场合。\u003c/p>","interaction":"\u003cp>【A1（激活学习者经验）5分钟）】\u003cbr>各位小伙伴，通过我介绍以上的原文片段，接下来邀请小组花3-5分钟进行组内分享，近期在生活或者工作有没有遇到需要自我介绍的场景，无论是成功还是失败的经验都可以讨论。\u003cbr>\u003cbr>谢谢大家的讨论，我们邀请一位小伙伴来分享吧。\u003cbr>学习者案例记录：\u003cbr>\u003cbr>【A2便签（学习者规划应用）（3分钟）】\u003cbr>\u003cbr>感谢XX小伙伴的分享，拆书帮倡导的就是拆为己用，学以致用，今天我们学会了“如何讲好我的故事”，我们来试着把它用起来。请大家想一想，在接下来一个周或一个月里，你会遇到哪些情况，可以用这种方式去讲自己的故事呢？请大家用1分钟时间思考一下，在便签上写下你的行动方案。\u003cbr>特别提醒：这里的方案不能仅仅是表决心，要写清楚事情发生的时间、地点、人物、已经如何表达。\u003cbr>学习者案例记录：\u003cbr>\u003cbr>\u003cbr>【总结1分钟】\u003cbr>以上就是我用今天的拆页，讲好“我是谁”的故事的方法的分享，希望在生活、工作中对大家有帮助，我的1-2晋级就到这里，谢谢大家的参加。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1732013725000,"updated_at":1732013725000,"ria":true},{"id":18365,"topic":"三倍提升你的可信任度","learn_goal":"","remark":"三倍提升你的可信任度\n在任何人允许你影响他们之前，他们想要知道：你是谁？ 为什么你在这里？ 如果你不花时间给这两个问题积极的答复， 那么他们会编造他们自己的答案——通常是消极的。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"绘宇","city":"南昌"},"club":{"name":"南昌火炬分舵","city":"南昌"},"prologue":"\u003cp>【自我介绍】1分钟\u003c/p>\u003cp>大家好欢迎来到南昌火炬分舵拆书练级1-1的活动现场。首先我给大家做个自我介绍，我叫绘宇，\u003c/p>\u003cp>我的三个标签是:1.健康美妆达人 2.80后小学生宝妈 3.正在升级打怪的新手拆书家\u003c/p>\u003cp>【拆书帮介绍】2分钟\u003c/p>\u003cp>大家肯定好奇拆书帮是一个是什么组织?接下来我用2分钟时间，来介绍拆书帮和拆书法，拆书帮是赵周老师创立，是集结学习爱好者的青年组织公益社群，目前全球有68个分舵，远在日本，新加坡。\u003c/p>\u003cp>“拆书法”是一种成人学习方法论，强调以学习者为中心而不是以知识为中心。拆书的“拆”不是“拆散”而是转化和内化。\u003c/p>\u003cp>“拆书法”分为个人学习的RIA便签阅读法和组织学习的现场拆书法两种，个人学习通过便签法，即在学习过程中运用便签拆解知识，以实现学习后能够活学活用。组织学习则由一位拆书家引领并推动一群人将知识化为已用。就学习者的学习成效而言，一位拆书家所创造的价值丝毫不逊于一位培训师。\u003c/p>","ratings_count":2,"texts":[{"id":22654,"quote":"\u003cp>【过渡语】\u003c/p>\u003cp>那现在就由我来带领大家拆解一下今天的片段。今天我分享的书籍是《故事思维》，作者是是世界级故事大师安妮特.西蒙斯真正的奠基之作，这本书详细阐释了六大类故事，讲透了用故事提升个人影响力的方方面面。接下来请大家花2分钟时间来阅读一下我挑选的这个片段。阅读完的伙伴请抬头示意我。\u003c/p>\u003cp>【原文片段】2分钟\u003c/p>\u003cp>\u003cstrong>三倍提升你的可信任度\u003c/strong>\u003c/p>\u003cp>在任何人允许你影响他们之前，他们想要知道:你是谁? 为什么你在这里?如果你不花时间给这两个问题积极的答复， 那么他们会编造他们自己的答案--通常是消极的。\u003c/p>\u003cp>人们认为任何试图影响他人的人都想从中获利，这是人之常情。 大多数人潜意识下断定，你的获利就意味着他们的损失，这也是人之常情。我们总是本能地对外界树立屏障，用怀疑来保护自己。\u003c/p>\u003cp>你需要讲一个故事来证明你正是他们能够信任的人，不同的场合需要不同的故事。举个极端的例子，假设一个孩子想加入流氓帮派，于是讲他偷窃(或更恶劣)的故事，帮派成员可能会相信他，并接纳他。 我当然知道你不是黑帮成员，所以你讲的故事应该是能证明你的品德，或者能说明你赚取利润的能力的。不管是什么故事，只要能立竿见影地让你的听众产生共鸣，与你建立某种关联，能让别人了解你是个什么样的人就行。\u003c/p>\u003cp>想想你和意图影响你的人在一起的经历一-你的上司、同事、销售人员、志愿者、传教士和顾问，找出一个成功和一个失败的案例。你和他们之间的关系如何?你是因为这个人影响了你才与他关系亲密的，还是因为你感到和这个人关系亲密才被影响到?为什么你相信这个人而不是另一个人?\u003c/p>\u003cp>你应该首先了解对方是什么人，他们能从与你的合作中获取什么。当然，你潜在的利益很重要，但是你对于对方可信度的判断，极大地影响了你是否相信他们可以给你带来潜在的收益。\u003c/p>\u003cp>因此，无论你怎么强调“对你来说意味着什么”、能获得潜在的私利，或者合乎逻辑的理由和推断，作为听众，他们会分析你所说的每一个字，判断你是谁、你的目的，最终评价你的可信度。\u003c/p>","explains":"\u003cp>【拆书家讲解引导】分钟\u003c/p>\u003cp>好的，我看到大部分小伙伴已经阅读完了。\u003c/p>\u003cp>【what】\u003c/p>\u003cp>今天我们讲的这个拆页的标题叫:三倍提升你的可信任度，这个三倍是一个概念性的数字，也可能是两倍或者四倍，用大白话讲就是有效提高你信任度的自我介绍的方法。\u003c/p>\u003cp>【why】 \u003c/p>\u003cp>在我们这个社会，我们经常需要向陌生人介绍我们自己，例如面试的时候、参加拆书帮活动的时候、或者参加其它社群活动的时候等等，那我们一般都是怎么做自我介绍的呢?通常都是我叫什么名字?来自哪里?我是什么职业?但这么介绍的结果通常都是人家就记不住得你了，这就导致一个结果?那就是个人信息无效传递，别人根本不记得你，更不要说让别人去信任你。\u003c/p>\u003cp>【How】\u003c/p>\u003cp>那通过什么样的一个方式呢?下面我就把这个步骤给梳理出来。\u003c/p>\u003cp>第一步，告诉对方你是谁，就是你有什么特质?\u003c/p>\u003cp>第二步，你为什么在这里?也就是让这个特质和对方产生关联，那通过什么样的方式告诉对方呢?\u003c/p>\u003cp>第三步，用故事的形式告诉对方。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>这个方法是有它的使用边界的，主要适用于你去一些相对正式的商务和社交的场合，对方对你的能力和价值比较重视的地方。如果你去一些吃喝玩乐的场所或者亲人朋友聚会，就不大可不必这么麻烦的介绍自己。\u003c/p>","interaction":"\u003cp>【分享A1 便签】 2分钟\u003c/p>\u003cp>不知道大家看完原文后有没有联想起自己的相关经历呢!下面我跟大家分享一个发生在我身上的案例:\u003c/p>\u003cp>【自己的例子】\u003c/p>\u003cp>在我第一次上美丽课的时候，我对着我的两个顾客滔滔不绝的分享了整整2个小时的专业护肤知识，课后我还沾沾自喜，觉得经过我专业的讲解，她们一定会非常认可我，结果在第二天我给他们做电话服务的时候，顾客竟然差点忘了就在前一天我给她们上过美丽课的事！这简直让我大受打击，在复盘总结的时候，我才发现在美丽课上，我只分享了专业知识，完全忘了跟她们讲“我的故事”，让她们根本没有真正的认识我并记住我！\u003c/p>\u003cp>【分享A2便签】1 分钟\u003c/p>\u003cp>我们说拆书法是以自我为中心的学习法，阅读、理解、反思过后，关键是要规划应用。我读完这个片段后给自己规划的从今日起运用故事思维的方式 。\u003c/p>\u003cp>目标:在下周在三个不同场合分享“我的故事”\u003c/p>\u003cp>行动(具体步骤):通过美丽课的形式，穿插“我的故事”，提升顾客对我的信任度。\u003c/p>\u003cp>我会这样分享我的故事\u003c/p>\u003cp> 我是陈绘宇，我是位10年工作经验的美容顾问（对应第一步），为什么做了10年，是因为我是一个爱美的女性，我认为一个女性的成长，要兼顾事业和家庭，同时要能自我成长。（对应第二步），刚好这份工作可以满足我的需求，这是我10年前的照片，你可以看看，是不是差别很大。（对应第三步）\u003c/p>\u003cp>以上是我的 TF1-1的练级现场，感谢大家的参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1732013553000,"updated_at":1735196096000,"ria":true},{"id":10196,"topic":"三倍提升你的可信任度","learn_goal":"","remark":"日常生活中，我们需要与许许多多的人交流和接触，有的人你一下子觉得他值得信赖，有些人无论说什么，你都不相信他，这是为什么呢？因为我在理性的大脑上消耗了太多的时间，而缺乏对感性大脑的重视。\n\n\n","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"易伯伯","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>学习目标：通过现场RIA学习，学习者在自我介绍时，能够用“提高信任的自我介绍法”来介绍自己。 \u003c/p>\u003cp>大家好，我是今天的拆书家易伯伯。\u003c/p>\u003cp>\u003cstrong>F 特征：\u003c/strong>今天带拆的书，书名叫《故事思维》，作者是美国的安妮特 ·西蒙斯，她开创性地提出商界沟通中常用的六大类故事，并详细阐释了在何种情况下、如何讲述这些故事。还曾经服务过美国航天总局、美国国税局以及微软等大型公司。\u003c/p>\u003cp>\u003cstrong>A优势：\u003c/strong>这本书相比其它同类书籍，例如麦基的那本《故事》，它的一个优势在于是把故事思维运用于商业领域，它可以让你马上上手易操作，不需要像其它教你写故事的书一样，要有很强的框架思维和优美的文笔，并需要长时间的训练。这是它的一个优势\u003c/p>\u003cp>\u003cstrong>B1利益：\u003c/strong>我们在生活和工作中，经常遇到一个问题，就是你想把事情讲好，吸引别人的注意，却发现自己讲的东西索然无味，刚刚那个小伙伴就非常好，讲得索然有味，对方勉强应和着，双方陷入尴尬。或者想跟对方拉近距离，却不知道怎么拉近。跟他进一步做沟通。那么这本书可以带给你解决这些问题的办法。\u003c/p>\u003cp>\u003cstrong>B2利益：\u003c/strong>我们在人际沟通或是商业交流中，经常需要做自我介绍，但总是难以被记住，而对方讲完了，你也记不住对方，今天我们拆解的片段主题叫是：三倍提升你的可信任度，也就是用故事的形式做自我介绍，提升你自我介绍的效果和影响力。让对方记住你，更加信任你的一个方法，下面我们一起来阅读原文片段。\u003c/p>","ratings_count":1,"texts":[{"id":14029,"quote":"\u003cp>下面请大家花１分钟时间来阅读一下我挑选的这个片段。阅读完的伙伴请抬头示意我。\u003c/p>\u003cp>\u003cstrong>三倍提升你的可信任度\u003c/strong>\u003c/p>\u003cp>在任何人允许你影响他们之前，他们想要知道：\u003cstrong>你是谁？ 为什么你在这里？ \u003c/strong>如果你不花时间给这两个问题积极的答复， 那么他们会编造他们自己的答案——通常是消极的。\u003c/p>\u003cp>人们认为任何试图影响他人的人都想从中获利，这是人之常情。 大多数人潜意识下断定， 你的获利就意味着他们的损失，这也是人之常情。我们总是本能地对外界树立屏障， 用怀疑来保护自己。\u003c/p>\u003cp>\u003cstrong>你需要讲一个故事来证明你正是他们能够信任的人， 不同的场合需要不同的故事。 \u003c/strong>举个极端的例子， 假设一个孩子想加入流氓帮派， 于是讲他偷窃（或更恶劣）的故事， 帮派成员可能会相信他，并接纳他。 我当然知道你不是黑帮成员，\u003cstrong>所以你讲的故事应该是能证明你的品德，或者能说明你赚取利润的能力的。不管是什么故事，只要能立竿见影地让你的听众产生共鸣， 与你建立某种关联， 能让别人了解你是个什么样的人就行。\u003c/strong>\u003c/p>\u003cp>想想你和意图影响你的人在一起的经历——你的上司、 同事、 销售人员、 志愿者、 传教士和顾问，找出一个成功和一个失败的案例。你和他们之间的关系如何？你是因为这个人影响了你才与他关系亲密的，还是因为你感到和这个人关系亲密才被影响到？ 为什么你相信这个人而不是另一个人？\u003c/p>\u003cp>\u003cstrong>你应该首先了解对方是什么人，他们能从与你的合作中获取什么。\u003c/strong> 当然，你潜在的利益很重要，但是你对于对方可信度的判断，极大地影响了你是否相信他们可以给你带来潜在的收益。\u003c/p>\u003cp>因此，无论你怎么强调“对你来说意味着什么”、 能获得潜在的私利，或者合乎逻辑的理由和推断，作为听众，他们会分析你所说的每一个字， 判断你是谁、你的目的，最终评价你的可信度。\u003c/p>","explains":"\u003cp>好的，我看到大部分小伙伴已经阅读完了。\u003c/p>\u003cp>\u003cstrong>【一般人的做法怎么做及不这么做的坏处】\u003c/strong>\u003c/p>\u003cp>在我们这个社会，我们经常需要向陌生人介绍我们自己，例如面试的时候、参加拆书帮活动的时候、或者参加其它社群活动的时候等等，那我们一般都是怎么做自我介绍的呢？通常都是我叫什么名字？来自哪里？我是什么职业？但这么介绍的结果通常都是人家就记不住得你了，这就导致一个结果？那就是个人信息无效传递，别人根本不记得你，更不要说让别人去信任你。\u003c/p>\u003cp>\u003cstrong>&lt;细化行动步骤&gt;\u003c/strong>\u003c/p>\u003cp>今天我们讲的这个拆页的标题叫：三倍提升你的可信任度，这个三倍是一个概念性的数字，也可能是两倍或者四倍，用大白话讲就是\u003cstrong>有效提高你信任度的自我介绍的方法\u003c/strong>。\u003c/p>\u003cp>那通过什么样的一个方式呢？下面我就把这个步骤给梳理出来。\u003c/p>\u003cp>首先第一步，告诉\u003cstrong>对方你是谁，就是你有什么特质？第二步，你为什么在这里？也就是让这个特质和对方产生关联，\u003c/strong>那通过什么样的方式告诉对方呢？对，也就是第三步，用故事的形式告诉对方，好了，那这样就结束了吗？大家看一下这个拆页底下的一句话：\u003cstrong>你应该首先了解对方是什么人，他们能从与你的合作中获取什么。\u003c/strong>\u003c/p>\u003cp>所以，这才是这个方法的第一步，也就是你在自我介绍之前要先要了解受众，了解对方是一个什么样的人。然后才是用故事的形式告诉对方你是谁，你有什么特质，跟他们有什么关联？所以，这个拆页的整个顺序应该是：\u003c/p>\u003cp>\u003cstrong>【行动步骤】：\u003c/strong>\u003c/p>\u003cp>第一步：了解你的受众，根据受众来做自我介绍。\u003c/p>\u003cp>第二步：找出你最想呈现的某个特质，或者说能力。\u003c/p>\u003cp>第三步：让这个特质和对方产生关联。\u003c/p>\u003cp>第四步：把这个特质用故事的形式呈现，让对方信任你。\u003c/p>\u003cp>\u003cstrong>&lt;举例&gt;A1\u003c/strong>\u003c/p>\u003cp>这么讲有点抽象，我举个例子：我在拆书帮一直都是用三个标签做自我介绍，我通常都会这么说。第一我是爱吃辣的广东汕头人；第二我是一个狼人杀爱好者，第三我从事的行业是品牌策划行业。\u003c/p>\u003cp>请问这三个标签里面没有按照这个方法来？（\u003cstrong>互动：没有\u003c/strong>）\u003cstrong>，\u003c/strong>也就是没有根据这个场域的人来做自我介绍，这里其实都是爱学习的人。我说我是一个狼人杀爱好者，这个标签其实跟大家没有什么关联。我是个爱吃辣的广东汕头人，如果你们爱吃辣，或者你们里面有汕头人，才会和我产生联系，但几率也很低。\u003c/p>\u003cp>\u003cstrong>A1+转负为正：\u003c/strong>\u003c/p>\u003cp>那用今天的方法，我应该怎么做自我介绍呢？首先要了解来这里的，都是一些爱学习的小伙伴。那么我最应该突出的就是：我也爱学习，我也会学习，能够给大家带来知识的这样一个人。那我会怎么样故事的方式去讲解呢？我会说：\u003c/p>\u003cp>大家好，我叫易伯伯，我们在深圳经常都会有一个问题，就是要搬家，而我每次搬家最痛苦的就是我的书非常非常的多，让我搬家的时候非常的痛苦，有一次搬家还下雨了，我的很多书都淋湿了，当时我就对自己说，我以后尽量不买书，但现在的情况就是我的书架已经摆不下了，这叫好了伤疤忘了痛。而我每年在自我教育上花费的钱都在一万以上。前两年我觉得，看了那么多书，要不去学一下培训和演讲，于是去年加入了拆书帮，并一个打怪升级的拆书家；今年疫情期间，我还通过网络，经过一个多月的考核，成为混沌大学的辅导员。这就是我用这四个步骤来做自我介绍。\u003c/p>\u003cp>\u003cstrong>好，总结一下我新的自我介绍，\u003c/strong>第一步了解的受众，也就是在座是一帮爱学习的小伙伴，第二步，找出我最想呈现的特征，也就我是个爱学习，会学习的人。第三步，我要找到关联，深度学习者、拆书家和混沌辅导员来跟大家产生关联。第四步：通过搬家时书太多、每年在自我教育上的投入和成为拆书家和混沌大学辅导员的经历，以故事的形式告诉大家，我是一个值得信赖的拆书家。\u003c/p>\u003cp>\u003cstrong>【预防异议&amp;适用边界】\u003c/strong>\u003c/p>\u003cp>这个时候有的小伙伴可能会说，每次都要用这种方式来自我介绍会不会很麻烦。（\u003cstrong>互动：有一点\u003c/strong>）\u003cstrong>，\u003c/strong>是的，这个方法是有它的使用边界的，主要适用于你去一些相对正式的商务和社交的场合，对方对你的能力和价值比较重视的地方。如果你去一些吃喝玩乐的场所或者亲人朋友聚会，就不大可不必这么麻烦的介绍自己。\u003c/p>","interaction":"\u003cp>\u003cstrong>&lt;分组演练&gt;\u003c/strong>\u003c/p>\u003cp>我们三个为一小组，先讨论如何用我们刚刚说的四个步骤，对牛齐做一个自我介绍，大家可以先写下来，然后分别扮演牛齐和郝仁，以对话的形式，把这个方法告诉牛齐如何做自我介绍。大家可以先讨论一下，再进行演练，请大家用6分钟来讨论和准备。大家看一下场景设计的内容\u003c/p>\u003cp>\u003cstrong>&lt;场景设计&gt;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>角色：“牛齐”和“郝仁”\u003c/strong>。\u003c/p>\u003cp>牛齐是一个拥有十年销售经验的人，入行的时候曾经笨嘴笨舌，不懂业务两个月没开过一个单，最后靠好学（加入拆书帮，学习拆书）和勤奋在销售行业站稳脚跟；还曾经在某公司从零做到月销售额上亿的业务管理者，管理过十几个人的业务团队；还曾顶着巨大压力，带领团队将跌入谷底的企业重新拉到正规上，本人也坚持健身，能跑完全马，明天他将新入职一家销售团队士气低迷的公司，销售团队相互猜忌。面对这个团队，他想用一种容易获得信任的方法来做自我介绍。但不知怎么做，郝仁用“提高信任的自我介绍法”和他说了怎么介绍自己能够获得信任。\u003c/p>\u003cp>（备注：场景设计中包含很多干扰信息，目的是为了让学习者根据诸多信息找到要用故事去做自我介绍的线索，验证学习者是否真正掌握了这个方法）\u003c/p>\u003cp>\u003cstrong>&lt;角色扮演&gt;\u003c/strong>\u003c/p>\u003cp>好，接下我就邀请其中一个小组的到台上进行演练一下，让大家一起来学习一下，如何能够把一条信息真正传递出去。\u003c/p>\u003cp>牛齐：郝仁，我现在要进入一家新公司了，我想用一个的自我介绍，让他们来信任我，你觉得有什么方法吗？\u003c/p>\u003cp>郝仁：你的团队是什么样一个状态啊？\u003c/p>\u003cp>牛齐：现在这个团队是做销售的，士气比较低迷，而且团队之间还相互猜忌，力气没往外使。\u003c/p>\u003cp>郝仁：那你觉得他们的需求是什么呀？\u003c/p>\u003cp>牛齐：他们的需求？肯定是挣钱啊，就是开单，有钱，有更好的发展。\u003c/p>\u003cp>郝仁：那如果你去了，他们对你的需求是什么？\u003c/p>\u003cp>牛齐：肯定是想让我把他们从这个差的现状带出来。\u003c/p>\u003cp>郝仁：也就是觉得你很靠谱，让他们觉得你是一个靠谱的老板，愿意跟着你干，对不对？\u003c/p>\u003cp>牛齐：对，化腐朽为神奇。\u003c/p>\u003cp>郝仁：行，那你觉得你有没有什么特质让他们觉得你很靠谱？有没什么东西可以给对方呈现？\u003c/p>\u003cp>牛齐：比如说我觉得我最牛的就是从一开始笨嘴笨舌，到最后能接上亿的项目。甚至到一家新的公司把一个烂的团队带到特别好。\u003c/p>\u003cp>郝仁：也就是你也可以用一个靠谱的故事，告诉大家，你们也可以复制。\u003c/p>\u003cp>牛齐：对，从最初的低起点到最后的高峰。\u003c/p>\u003cp>郝仁：那你可以用这个故事来告诉大家，你是个靠谱的领导，我过去的经历，我行你也行，我可以带领大家往前干，就这样。\u003c/p>\u003cp>牛齐：好的，谢谢\u003c/p>\u003cp>拆书家：可以把几个步骤梳理一下。\u003c/p>\u003cp>郝仁：好，我们把几个步骤总结一下。首先第一步，我们要了解你的受众，他们的需求是什么，答案是他们需要一个靠谱的领导；第二步，从牛齐的经历找到哪些特质，\u003c/p>\u003cp>牛齐：从低谷到高峰，曾经化腐朽为神奇，\u003c/p>\u003cp>郝仁：对，也就是化腐朽为神奇的可复制的靠谱的经历。然后第三步，跟大家的现状做一个关联，因为大家现在也需要一个可复制的靠谱的东西来告诉大家我也可以，非常需要这个东西。第四步就是把这段经历变成一段故事告诉大家。\u003c/p>\u003cp>牛齐：对，最后我就告诉大家，虽然现在状态也比较差，但我也曾经待过这样的现状，我相信可以让大家从菜鸟变成雄鹰。\u003c/p>\u003cp>好！非常感谢两位小伙伴的表演，很好的将我们今天所学的四个步骤演绎出来。然后我刚刚在场下的时候发现这边的小伙伴也已经把故事给演绎出来了，大家都非常的出色。\u003c/p>\u003cp>\u003cstrong>&lt;一句话总结&gt;\u003c/strong>\u003c/p>\u003cp>今天的这个方法，说他简单也简单，说他难呢，也挺难的，因为需要大家不断的去练习和打磨。也希望未来大家有更好的呈现，更好的自我介绍，让大家一下子就能记住你，并对你产生信任，这就是我今天的分享，谢谢大家！ \u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1596131495000,"updated_at":1596603132000,"ria":true},{"id":9717,"topic":"如何讲好一个故事","learn_goal":"\"是在跟随我完成本次RIA现场学习后， 学习者通过听到、看到","remark":"您是否总是苦于无法在公众场合精彩的描述自己？\r\n这本书可以帮你进行自我提升；\r\n您是否总是陷入一件事无法全面而生动的表达？\r\n这本书可以带你突破；从而化解你空洞而\r\n无聊的尴尬境地。我从上个月开始阅读这本书，\r\n我把书中的方法运用到自己身上，\r\n通过讲故事的方式输出自身的价值，\r\n并且在每一次读书分享会上都因为我精彩的表达，\r\n而得到别人充分的肯定和欣赏，\r\n也提升了自己在人群当中的影响力。","level":"TF2-1","duration":30,"status":29,"type":0,"chaishujia":{"username":"会跳舞的瑜小姐","city":"长沙"},"club":{"name":"长沙橘洲分舵","city":"长沙"},"prologue":"一、step1:提前发拆页给大家，人手一份\r\n （提前分好组）\r\n 学习目标：是在跟随我完成本次RIA现场学习后，学习者通过听到、看到、闻到、摸到和尝到五个感官要素，从而帮助你讲好一个故事。\r\n二、 step2: 用1分钟介绍自己、今天拆的书籍、以及分组（1分钟 ）\r\n开场： 我就是我，颜色不一样的烟火，各位亲爱的小伙伴们，大家晚上好，我是雷蕾，雷蕾就是我，一名热爱舞蹈的瑜伽老师，感谢大家陪伴我度过接下来的拆书时光。我今天带拆的主题是《如何讲好一个故事》，今天的学习目标是在跟随我完成本次RIA现场学习后，学习者通过听到、看到、闻到、摸到和尝到五个感官要素，从而帮助你讲好一个故事。我今天带拆时间为15-20分钟。在拆书之前，为便于有序讨论，我们先分一下组，以中间线为间隔，分前后两组，并请每个小组选出小组长。\r\n【Step2-1】用FAB法介绍图书（2分钟）\r\nF:特征（Feature），核心是“书”，用于满足好奇心。\r\n 我今天带拆的书籍是《故事思维》，书的作者是美国作家安妮特 ·西蒙斯，这本书是她的奠基之作，畅销全球十余年。她开创性地提出商界沟通中常用的六大类故事，并详细阐释了在何种情况下、如何讲述这些故事。在书中用各种案例，让你明白讲故事胜于讲道理。通过这本书，你能够很快学会运用故事思维，讲故事的各种方法和技巧，迅速成为一个很会沟通，人人都喜欢的人。\r\nA：优势（Advantage），重点是“比较”，用于建立安全感。\r\n这本书自面世以来，就在社会上引起了强烈的反响。好故事永远胜于讲道理。她认为，用讲故事的方法与人沟通，影响他人，将会让你事半功倍。与其他同类书籍相比，这本书更像是一本指导手册，全书以案例和说故事的方式，让读者在实践中逐步体会到故事思维的神奇之处。这也是这本书能够在众多实用类书籍当中脱颖而出的原因。\r\nB：利益（Benefit），强调的是“你（学习者）”，用于引发兴趣。\r\n您是否总是苦于无法在公众场合精彩的描述自己？这本书可以帮你进行自我提升；您是否总是陷入一件事无法全面而生动的表达？这本书可以带你突破；从而化解你空洞而无聊的尴尬境地。我从上个月开始阅读这本书，我把书中的方法运用到自己身上，通过讲故事的方式输出自身的价值，并且在每一次读书分享会上都因为我精彩的表达，而得到别人充分的肯定和欣赏，也提升了自己在人群当中的影响力。","ratings_count":1,"texts":[{"id":13558,"quote":"\u003cp>\u003cp>\u003cstrong>三、step3:接下来有请一位小伙伴为我们朗读原文片段。（1分钟）如何讲好一个故事\u003c/strong>\u003c/p>\u003cp>\u003cstrong>《让人们听到、闻到、尝到你的故事》\u003c/strong>\u003c/p>\u003cp>讲故事的目的，就是让听众看到、摸到、闻到、尝到故事，这样才能让他们身临其境。杰.奥卡汉是个模仿中的高手，最善于给故事添加声效。在他的故事里，如果需要刮风，他便鼓起腮帮，撅起嘴，模仿大风吹过的声音。\u003c/p>\u003cp>在身边没人的时候，你不妨尝试一下。模仿某个夜晚的电闪雷鸣，模仿清晨的一缕微风，模仿俄克拉荷马州广袤而寂静的平原。试一下，一定很有趣。给你的故事加入声音的元素，故事就会变得妙趣横生。\u003c/p>\u003cp>气味和滋味与声音一样重要，它们也能勾起人们的情感记忆，甚至会让人产生生理反应。例如，让你的听众们去想象巧克力饼干出炉时的场景，人们不自觉地张大鼻孔，脸上浮现出享受的神色，那是巧克力饼干的香味带给他们的感受。反之，难闻的味道，会让人皱眉、搓鼻子，心生厌恶。\u003c/p>\u003cp>用声音、气味和滋味，把听众引入你的故事，给他们身临其境的感觉，你就能全方位地调动听众的感官，让他们用全身体会故事。\u003c/p>\u003c/p>","explains":"\u003cp>\u003cp>\u003cstrong>四、step4:【I】讲解引导（用自己的语言重述知识）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3分钟\u003c/strong>\u003c/p>\u003cp>好的，感谢这位帅气的小伙伴给我们带来了这么有能量的朗读，谢谢！\u003c/p>\u003cp>无论是在生活中还是在工作中，如何影响别人、打动对方，都是一项重要的技能，而讲故事是实现这一点的最佳方式，讲一个好故事永远胜过讲道理。\u003c/p>\u003cp>讲故事不是与生俱来的天赋，而是可以通过后天训练形成的本领。什么样的故事能够打动别人？通过哪些方法可以讲好一个故事？在《故事思维》这本书中都有答案。今天跟大家分享讲故事中的一个技巧，充分调动我们感知世界的五种感官—嗅觉、味觉、听觉、触觉、视觉，让听众能看到、听到、摸到、尝到你说的的故事，就像故事正在在他身上一样，在脑海里构建出一幕幕画面一样真实。\u003c/p>\u003cp>案例：\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cstrong>不那么做的坏处\u003c/strong>：小时候，我们最常听到的讲故事：从前，有一座山，山里有座庙，庙里有个老和尚...其实这是一种记叙文的方式来讲故事，具备了时间、地点等基本要素，但是不够打动人心。\u003cstrong>（一般做法）\u003c/strong>\u003c/p>\u003cp>当这样的故事来开始，估计大家都昏昏欲睡，没有听下去的欲望了。\u003cstrong>（坏处/结局）\u003c/strong>\u003c/p>\u003cp>如果真正地打动人心，应该结合我们在片段中的感官5要素，我们就可以这样讲，从前，有一座山，去往山上的路旁，有许多鲜花，有红色、蓝色，好像在向我招手，闻到了花的清香，时不时还传来鸟儿的声音，远远地看到了山上的庙，飘起一缕缕白烟。终于登到山顶，来到这座庙前，一位老和尚正在庙前拿着扫帚在扫地，我向前去问：师傅，我想来求平安，为家人祈福。老和尚说：菩萨，心诚则灵，您费了这么多心思来庙里，菩萨自当如愿。\u003cstrong>（结合感官5要素的栗子）\u003c/strong>\u003c/p>\u003c/p>","interaction":"\u003cp>\u003cp>【A1】环节&nbsp;&nbsp;【提出一个显像问题，让学习者更容易联想到特定情境，从而激活经验】（5分钟）\u003c/p>\u003cp>现在请大家回顾一下自己的生活，你是不是有过这样的经历，想向朋友或家人分享一件你特别喜欢的物品或者有意思的故事，可到了嘴边，却表达不清，他双眼迷茫地看着你，或者你去某次分享会上描述自己的某段经历时，讲了半天却枯燥无味，但还没有完全表达出意思？你最近有过一次这样的感受吗？是什么时候，是什么事情？每人1分钟的时间，分小组讨论，共4分钟。讨论完毕后，各组选一名代表进行分享，请问我的指令清晰吗？开始…4分钟后，请一个代表分享。分享时间1分钟。….\u003c/p>\u003cp>例子分享：请b组分享，就是我们在上研究课的时候，我们老师在讲到中美贸易战的时候，就没有描述的特别的清晰，感觉整个过程一笔带过，最后直接总结。让我们听的一头雾水……\u003c/p>\u003cp>【A1+】反思+加工环节&nbsp;请学习者结合自己的经验和你给的行动步骤，反思类似情况更好的做法是怎样。并在小组内分享。（3分钟）\u003c/p>\u003cp>谢谢小伙伴的分享。接下来请大家根据今天学习的内容---通过感官五点，即听到、看到、摸到、闻到、尝到五个要素，结合刚才小伙伴分享的案例，如以后再遇到这样的情况，你会如何去丰富你的故事？先在小组内讨论，2分钟后请一个代表分享。…请问我的指令清晰吗？..邀请做分享，分享1分钟。…..\u003c/p>\u003cp>有请b组分享：就是我们老师她讲中美贸易战的时候，说到他去美国的一些事情，但是他讲了很多让我们也没有记住很没吸引力，最后就总结了，如果他运用故事思维的几个要素，把他下飞机开到了什么高矮的房子建筑描述出来，听了当地的人如何聊天，以及那边的美食怎么样，以及接触当地人的感受如何我想一定会有一个丰富的课堂。\u003cbr>\u003c/p>\u003cp>好的，谢谢大家精彩的分享\u003c/p>\u003cp>结束：柏拉图曾经讲过：谁会讲故事，谁就拥有世界。\u003c/p>\u003cp>这句话表明：讲故事，是一种能力，是一种力量，是一种手段，故事讲得好，可以让人更具魅力和影响力。而我也希望大家通过学习感官五要素之后，充分发挥了自己会讲故事的本领，并运用到自己的领域中去，让自己不断的发光发热。\u003c/p>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1581671368000,"updated_at":1581671368000,"ria":true},{"id":9314,"topic":"如何运用故事思维","learn_goal":"知道讲故事的重要性、讲故事的要点、养成故事思维","remark":"你会讲故事吗？说故事永远胜于讲道理，讲好一个故事，可以赋予冰冷的数据和残酷的事实与温情，可以触及最有心机最强硬最敌对的人内心深处的柔软所在。故事并非与生俱来的天赋，是可以学习和逐步提高的思维模式，其中关窍所在，就在今晚《故事思维》解锁人的手中，助你迅速长控全局。","level":"TF1-1","duration":15,"status":null,"type":0,"chaishujia":{"username":"明哲","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;主题：一个故事家的日常练习\r\n拆书家：明哲\r\n所在级别：TF1-1\r\n开场：自我介绍：大家好：我是明哲，之所以给自己起明哲这个名字，是希望自己能更开明、智慧、更通晓真理。如果用三个关键词来形容现在的自己话是以下3个：第1个，信仰，我是一个基督徒，信仰指引着我的人生，第2个关键词是：唯美，我喜欢各种形式的美，美食美景美文。第3个关键词是：突破，有很多需要自我突破的东西，拿掉自我设限，发挥潜能。\r\n拆书帮介绍：介绍完我自己，我给大家介绍下拆书帮。拆书帮是基于拆书法的学习爱好者的社群，在各地有很多分舵，是一个公益性的青年自组织。使命是帮助更多的学习爱好者成长为拆书家。\r\n拆书是一种学习的方法论，是以学习者为中心，不是以知识为中心，通俗的来说就是你读完一本书，可以将书中的知识运用到实际工作生活中，提升自己各方面的能力。适用于提升能力，解决问题为目标的成人学习，\r\n拆书法是可应用于个人学习的便签学习法让人读一本书就能达到参加同主题培训的效果，也可以应用于组织学习的拆书帮现场学习法。组织学习的应用是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。从学习者的学习效果来衡量的话,一位拆书家创造的价值不亚于一位培训师。\r\n今晚我们来拆解这本书是《故事思维》。接下来请用一分钟来看一下拆文\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":0,"texts":[{"id":13099,"quote":"\u003cp>去做一个每日横扫故事的清道夫吧!任何一件产生感情或由于感情引发的事情都可以成为一个故事。当你看到一个人有你所钦佩的品质或完成了你向往的目标，就让他们给你讲讲他们的故事吧。这实际上对你的健康有好处。一项研究发现，分享故事可以提升你的幸福感，还可以降低心率和血压。你在任何地方都能发现故事，因此读故事、看电影以及让别人讲故事给你听，顺理成章。\u003c/p>\u003cp>安静思考几分钟，然后大略记下关于故事的想法。你可以在任何时候任何地点构思故事。比如长途旅行中、堵车途中、排队等候时、枯燥的会议中间、躺在床上的时候、洗澡的时侯，都是良好的时机。一些东西会成长，而一些不会。如果你足够幸运个故事能够从你嘴里自动冒出来。\u003c/p>\u003cp>《学习之旅》(书中关于名人生活中重要时刻的叙述，可以成为你故事的素材)的作者贝弗・利凯，使用了7种方法寻找故事。我在此加了一些回忆，来帮助你们入门，加深记忆。\u003c/p>\u003cp>1.寻找模板:反复循环的主题，帮助你定义你是“谁”;后续的令人兴高采烈的结果证明你走上了正轨;反复出现失败的结果，是你为什么要来的理由;描述你人生中的荣誉时刻，它们是怎样紧紧相连的，对你来说又有怎样的意义。\u003c/p>\u003cp>2.寻找结果:回忆那些过去你通过努力得来的特别好或者特别坏的结\u003c/p>\u003cp>果，看看它们对你现在选择处理事情的方法有着什么样的影响;思考一下这些对你发展人际关系产生影响的或好或坏的结果;读一读像《伊索寓言》那样有教育意义的故事，去激发唤起你人生中类似经历的回忆。\u003c/p>\u003cp>3.寻找经验教训:铭记你人生中令人痛苦的危机，明确地表达出你得到的经验教训;回想你曾犯过的最严重的错误;哪一次，你庆幸自己听了父母的话;你事业中的转折点及你学到的东西;回首过去，再考虑一下这些事情你可能会有不一样的做法。\u003c/p>\u003cp>4.导找有效可用资源:记住改变你的那个故事，然后用老故事来编新故事，记住你听到过的貌似会有用的故事;一个在家庭生活中有效的故事是否可以用在工作上(或者反之亦然);询间影响其他人的故事是什么并获得使用他们故事的许可。\u003c/p>\u003cp>5.导找弱点:谈谈你的软肋;上次哭是因为什么;讲述一个让你非常开心、兴奋地想跳舞的故事;回忆一个尷尬的瞬间;回忆你想钻到桌子底下藏起来的时刻;回忆你深爱的家人的感人故事。\u003c/p>\u003cp>6.寻找未来的经验:将你每天幻想的“它会怎样”，加上现实生活中は中的人物拓展成一个完整的故事(人们喜欢被代入故事中):将你的担忧发展为成熟的故事，包含所有潜在负面结果一一它们会如何结東、会影响到谁。\u003c/p>\u003cp>7.寻找故事的回忆:找出一个令你难忘的故事并挖掘出含义;出于某个原因，你最爱的电影或者最喜欢的书一一试着复述你的想法、观点，这样他人就能领会你想表达的意思。\u003c/p>","explains":"\u003cp>\u003cstrong>I\u003c/strong>\u003c/p>\u003cp>\u003cstrong>WHAT: \u003c/strong>\u003c/p>\u003cp>这段话告诉我们，7个方面的素材让我们发展出一个关于你自己的生动而鲜活的故事。这些素材都是我们亲身经历过的，有那些开心的、哭泣的、尴尬的、你担忧的，有失败到成功的经验，有犯过的严重的错误、还有痛苦的危机，还有你最喜爱的电影、书等，在日常驾刻意的整理练习，是我们发展故事思维和个人影响力关键所在。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>WHY:\u003c/strong>&nbsp;&nbsp;\u003c/p>\u003cp>这样做的好处是：\u003c/p>\u003cp>1你的故事更真实、鲜活、丰富性。\u003c/p>\u003cp>2整理的同时，也是自我观察，自我认知、总结的过程，也更有意识的自我完善、自我成长。\u003c/p>\u003cp>3你生活的每一天都成为你故事的新篇章，你是这个新故事的作者和主人翁，透过将自己的生活故事化，你会更有意识的为自己描绘人生蓝图，更有意识的创作属于你自己的人生剧本。\u003c/p>\u003cp>4发现更多的生命的意义，智慧、影响力将随之而来。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>HOW: \u003c/strong>\u003c/p>\u003cp>从哪7个方面的素材整理故事？\u003c/p>\u003cp>1：我是谁？：那个从失败——成功——荣誉时刻，对你很有意义，能定义你是谁的那些事。\u003c/p>\u003cp>2：我的关系：过往你的人际关系有哪些成功或失败的故事，对你现在为人处事的方法产\u003c/p>\u003cp>生影响的事。\u003c/p>\u003cp>3：我的教训: 你犯过的最严重的错误，经历的痛苦的危机，以及最庆幸的事，在其中学习到的经验教训。\u003c/p>\u003cp>4：我的资源：将自己的或他人的那些对工作或家庭有影响力的故事进行收集、改编并加以应用。\u003c/p>\u003cp>5：我的情感：曾经另你开心的、哭泣的、尴尬的、感人的、和深爱的家人的那些事。\u003c/p>\u003cp>6：我的未来: 我担忧的、我期待的关于未来的故事，它怎们将有怎样的正面或负面的结局。\u003c/p>\u003cp>7：我的最爱：你最爱的电影和书，讲出你的想法、观点、感受。\u003c/p>","interaction":"\u003cp>上个月，为一对新人做婚礼司仪，人到中年才结婚的他们，相貌平平、男方甚至还有些秃顶，和人们所期待的颜值不太相符，但在我将他们感人的爱情故事呈现出来之后，台下响起真诚的掌声，我想这就是故事的力量，是他们自己真实感人的故事使得这场平凡的婚礼有了灵魂。\u003c/p>\u003cp>反思：当时没有学过这7个方面的素材来整理故事，巧合应用了第5条情感这条；故事里有开心、有哭泣、有感人、有深爱的家人的那些事，对比上面7方面，介于在婚礼的场景中，下一次我还可以将第6条的素材增加到故事里面，使故事有更多的完整性。\u003c/p>\u003cp>目标：我决定下周一开始到周日，每晚应用这7方面的素材，先来编写自己的7个故事。\u003c/p>\u003cp>行动：\u003c/p>\u003cp>1这周六将素材7方面贴在办公桌前预热，碎片时间回忆往事。\u003c/p>\u003cp>2下周一开始，每晚8点写故事，按7方面的顺序，每天写一个，每完成一个对着镜子自己赞赏自己。\u003c/p>\u003cp>3写故事的第二天碎片时间将故事讲给老公听，让他提出反馈和建议，直到7个故事都写完为止。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1574400988000,"updated_at":1574647126000,"ria":true},{"id":9311,"topic":"如何讲故事&讲好故事","learn_goal":"学习者可以学习到如何讲故事的能力","remark":"不知道大家有没有这样的困惑，辛辛苦苦搜集素材、数据，摆事实讲道理，写出长篇累牍的汇报PPT、演讲稿，在宣讲的时候，我们在一头侃侃而谈，而听众貌似一点兴趣也没有，听的很无感的样子。\r\n今天待拆的畅销书作者西蒙斯的经典书籍《故事思维》这本书，将告诉你以故事思维来破局营销沟通方法，通过讲故事&讲好故事的方式引起他人兴趣，让他人接受观点，愿意和你一起来解决沟通问题。","level":"TF3-3","duration":60,"status":29,"type":0,"chaishujia":{"username":"陈蕙茗","city":""},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家晚上好，我是参加TF3-3训练的陈蕙茗。罗辑思维创始人罗振宇老师说过：“21世纪最重要的能力就是写作和演讲的能力，而在这其中，讲好故事的能力是可以两者结合，并且可以帮助两者跃迁的。”今天的两个拆页片段都和讲故事这个能力有关系。我们先从第一个片断开始。第一个片断的学习目标，希望我们现场的学习者可以通过RIA学习后，可以识别讲故事比讲真相更容易让人接受、深入人心，能够正确使用“分析问题、匹配故事、匹配现实”的三个步骤，找到工作、生活中用故事沟通的场景，从而达到解决问题的沟通效果。\r\n事件场景：不知道你们有没有过这样的经历，辛辛苦苦搜集素材、数据，摆事实讲道理，写出几十页的PPT、汇报材料，在宣讲的时候，我们在一头侃侃而谈，而听众貌似一点兴趣也没有，恨不得马上就结束。（现场小伙们点头，你们也有这样的场景是吧）。再比如，你苦口婆心地和小孩讲，要好好珍惜时间好好学习，但小孩却是一幅不耐烦的样子，像小时候父母说我们一样，左耳朵进右耳朵出的情况。\r\n提问：所以我们会忍不住想，我们付出了这么多努力，却还是没有收获，引起不了对方的兴趣呢？为什么我们讲了那么道理，但是达不到我们想要的沟通效果呢？\r\n影响：诚然， 我们可以发现讲道理有可能会变成我们沟通的阻碍，陷入沟通的囧境，会让对方觉得有点呆板、不幽默，阻碍了和你沟通的想法，最后变成你想达到的沟通效果也没办法达到。\r\n解决：那有没有什么方法可以帮助我们破解这个沟通囧境呢？今天待拆的畅销书作者西蒙斯的《故事思维》这本书，将会指导我们如何以故事思维来破局沟通囧境，让我们在生活和工作中去讲好故事，达到解决问题的沟通效果。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":13095,"quote":"\u003cp>下面邀请大家阅读原文片断， 时间是2分钟。\u003c/p>\u003cp>想一想你自己是否有过这样的经历：如果你跟你的同事、领导，或者你的爱人直接讲述某些\u003cstrong>真相\u003c/strong>，他们会很难接受。一般来说，直白地讲述\u003cstrong>真相\u003c/strong>会让你处处碰壁。如果你径直对老板说：”你这么做是行不通的！” 老板通常会这样回应你：“管好你自己，少管闲事！” 这时候，你就知道讲\u003cstrong>故事\u003c/strong>的重要性了。\u003cstrong>故事\u003c/strong>不那么直接，它更亲切，不易招来抵触。\u003c/p>\u003cp>假如，一群固执的领导同处一室，讨论陷入僵局，这对于一个喜欢讲\u003cstrong>真相\u003c/strong>的人来说是很危险的一一除非你知道怎样讲一个好\u003cstrong>故事\u003c/strong>。\u003c/p>\u003cp>在这样的状况下，我会讲一个关于拉里的\u003cstrong>故事\u003c/strong>。\u003c/p>\u003cp>拉里是我养的一条狗。我牵着拉里出去散步，途中有一根电线杆，拉里从电线杆的一侧走过，而我从另一侧走过，于是身子便被电线杆挡住了。这时拉里就会扭过头来看着我，想知道为什么我们走不动了。我就算用一整天的时间告诉它往后退，它却只有在我往后退的时候才会跟着往后退。而且，只有这样我们才能解决问题，然后继续往前走。\u003c/p>\u003cp>当我对一屋子的领导讲这个小\u003cstrong>故事\u003c/strong>时，他们知道我并不是真的在讲我的狗。醉翁之意不在酒，我的意思是显而易见的。\u003cstrong>真相\u003c/strong>就在其中，而且因为\u003cstrong>真相\u003c/strong>被包含在故事里，他们便接受了\u003cstrong>真相\u003c/strong>。他们没有当着我的面拒绝，他们会听我的\u003cstrong>故事\u003c/strong>，也常常会在他们的位置上做出让步，而这也让他们从僵局中走出来，继续向前走。\u003c/p>\u003cp>这就是\u003cstrong>故事\u003c/strong>的力量。当你想影响别人时，\u003cstrong>故事\u003c/strong>便是最有力的工具。\u003c/p>","explains":"\u003cp>大家都阅读完了，我来讲讲我的理解。\u003c/p>\u003cp>【概念与匹配案例】\u003c/p>\u003cp>我们一起回忆下，有没有发现原文片段中频频提到的两个关键词：一个词出现了6次，另一个出现8次。是哪两个关键词。\u003c/p>\u003cp>学习者互动：故事、真相。\u003c/p>\u003cp>拆书家解释：是的，故事和真相都是讲事情。真相是对事情的真实情况描述，它会给人一种刻板，不近人情，有可能太犀利了，让人不太愿意去听。而故事则是讲述事情的手段，可真实或虚构，通过故事的手法会给人有吸引力和感染力的感觉，让人愿意听。\u003c/p>\u003cp>举例子\u003c/p>\u003cp>大家应该都听过“邹忌讽齐王纳谏”故事，在我们小时候，那我们换位思考一下，如果邹忌直接对齐王说，你要注意呀，你现在作为一国之君很多人会蒙蔽你，如果我们用这种方式去讲述真相的时候，你觉得齐王容易接受吗？ 容易还是不容易？\u003c/p>\u003cp>学习者互动：不容易\u003c/p>\u003cp>拆书家解释：不容易对吧，讲真相是不容易接受。\u003c/p>\u003cp>所以邹忌换位思考，邹忌去和城北的徐公比美，问身边的人：“你们觉得我们俩谁美呀？”身边的人都说他美，但是当徐公来到他家做客后，他发现事实就是徐公比他颜值高。他作为一家之主都会被别人蒙蔽,齐王你作为一国之君不是更容易被人蒙蔽吗？所以他就以这样一个故事让齐王去纳谏，这样的话，容不容易接受？会不会沟通效果更好？\u003c/p>\u003cp>学习者互动：好（点头）\u003c/p>\u003cp>拆书家解释：的确这样沟通效果更好。所以我们可以总结一下，讲故事比讲真相更容易打动人心，更容易让人接收，也更容易达到我们想要达到的沟通效果。如果邹忌直接说真相，他是没有办法让齐王去纳谏的，让他真正的广开言路，达到他想达到的沟通效果。所以讲故事的魅力就在于此。\u003c/p>\u003cp>【HOW】\u003c/p>\u003cp>因此，基于原文片段的理解和前面案例对比，我拆解出在沟通场景下讲故事的三个步骤。\u003c/p>\u003cp>1、分析问题&nbsp;&nbsp; 剖析目前存在的问题，找到真相。\u003c/p>\u003cp>原文作者意识到存在的问题（拉里的故事）—一群固执的领导同处一室，讨论陷入僵局，谁都不肯让步。\u003c/p>\u003cp>2、匹配故事，可以利用故事要素或框架，讲一个类似的故事。\u003c/p>\u003cp>这里作者就讲了一个主人带着小狗拉里一起散步的故事，走在路上被电线杆阻碍了，遇到这种情况要怎么办？主人带着小狗一起往后退，才能解决问题。\u003c/p>\u003cp>3、匹配现实。故事匹配后，就能自然地让人联系到想要表达的信息。\u003c/p>\u003cp>通过讲述这个故事给固执不肯让步的领导听，让他们反思自己的行为，各自往后让一步，平心静气，才能达到解决问题的目的。\u003c/p>\u003cp>这三个步骤很好的帮助我们找到沟通的场景，去讲故事。\u003c/p>\u003cp>【例子】\u003c/p>\u003cp>我讲一个我的经历，几年前刚负责公司产品部的时候，下属有一个很普遍的问题：容易陷入细节产生纷争，不愿意互相协商，到最后都要跑到我这里来解决。比如这个按钮要不要，老大你来做下决定。然后呢，我总是给他们讲道理，但是一个下属说这个有好处，另外一个说没有好处，弄的我非常尴尬，最后由投硬币的方式来决定要不要采用按钮，或者投票的方式。我觉得没有达到很好的沟通效果。\u003c/p>\u003cp>然后学完这个片段，我发现我可以用讲故事的方法告诉他们，应该怎么样去更好的协同合作。\u003c/p>\u003cp>第一步：分析问题\u003c/p>\u003cp>产品经理比较扣细节这个问题，不会换位思考，我就要去思考用讲故事来沟通的场景\u003c/p>\u003cp>第二步：匹配故事\u003c/p>\u003cp>我想起我看过的一篇文章《画杨桃》的故事，在一堂画画课上，一个学生把杨桃画成了五角星，其他同学都笑了。为什么会这样呢？老师让同学们去他的座位看的时候发现，那个角度看杨桃还真是五角星。\u003c/p>\u003cp>第三步：匹配现实\u003c/p>\u003cp>要换位思考的能力，你在不同的角度看到的问题是不一样的。那个扣细节按钮的人可能会觉得，他是站在用户的角度来考虑。也就是双方要去协同的，才能把这件事情更好地做好。\u003c/p>\u003cp>这样的事情就可以通过讲故事来解决。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>那我们再来讲讲讲故事的适用边界。它就可以用在我们很多的沟通场景当中，特别适用于工作当中的产品营销文案、品牌宣讲等方面，生活中与孩子、父母等亲密关系都可以用运用到这个场景。\u003c/p>\u003cp>但是它不太适用的范围，如专业性会议，是个学术会议，就是需要行业报告，就是需要讲事实、摆道理，你再和我讲故事就不太适合了。\u003c/p>","interaction":"\u003cp>【a2催化应用】【教学习者编写剧本】\u003c/p>\u003cp>前面的讲解部分就到这里，下面进入情景演练。刚刚我们有讲到在工作或生活当中，可以讲故事，那我们一起来想想：\u003c/p>\u003cp>1、可能在讲方案的时候，可以故事开头引入，引发共鸣或思考。\u003c/p>\u003cp>2、跟父母沟通时，可用类比向他们介绍一些产品或新观点。\u003c/p>\u003cp>3、当小孩做错事，可用故事类比，让他们意识到问题。\u003c/p>\u003cp>场景不设，可以是上面的这几种场景，也可以是自已想一个场景，我们来写一个剧本，运用刚学到的讲故事沟通场景的三个步骤，设计出人物、双方的对话、背景等来写剧本，用时2-3分钟，最后我们请一位小伙伴上台来分享一下。\u003c/p>\u003cp>\u003cstrong>【学习者案例】\u003c/strong>学习者RANGO：\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>背景： 在公司分享，程序员的代码没有那么讲究，代码不太规范，今天放一些乱七八糟的东西，明天放一些乱七八糟的东西，久了以后，代码就没法看了。（这就是第1步：分析的问题）\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>人物\u003c/p>\u003c/td>\u003ctd>\u003cp>A 学习者RANGO\u003c/p>\u003c/td>\u003ctd>\u003cp>B&nbsp; 同事程序员\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>事情：给同事程序员做分享，怎么去写好代码，怎么要他们去改进\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>对话： &nbsp; A:我去黑排角徒步，黑排角徒步的路上风景特别漂亮，然后垃圾成堆，可能是一些游人忘了带走东西，最后变成垃圾一大堆。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>A：在我们IT行业有一个大师就说：“有一个童子军军规，你在离开你的营地的时候，一定要在你离开的时候比你来的时候更干净一点点。”\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>A:解决黑排角垃圾问题，可以通过这样的方式来解决；然后，我们写代码也可以用这个方法来解决。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>A的解释：第2步：匹配黑排角垃圾问题，第三步：引申到我们要这样去解决代码问题，用童子军军规启发。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>谢谢这位小伙伴，非常好。&nbsp;\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":13096,"quote":"\u003cp>第一个片段我们就拆解到这里，我们进入第二个片段的学习。\u003c/p>\u003cp>我们已经知道讲故事比讲真相更容易穿越他人的心理防御，知道运用三个步骤可以找到工作国、生活中的沟通场景。那如何讲好一个妙笔生花、极富感染力的故事呢，接下来我们第二个片段要学习的内容。\u003c/p>\u003cp>片段2的学习目标，学习者能够正确使用“传递意义、描述五感、突出角色”的三个步骤，讲出带有意义、细节、形象的好故事，从而增强自己的说服力。\u003c/p>\u003cp>在第2个片段学习之前，我们先来做一下量表自测题，利用自己的第一印象圈，圈出适合你的得分，然后做个统计。做完的小伙伴，请举手示意一下。&nbsp;\u003c/p>\u003cp>请按1-5分的标准给自己打分，1代表完全不符合，5代表非常符合。然后把自己的分数做个统计，根据自己的实际情况给自己打分。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>完全不符合-----非常符合\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>1、当我在公众场合讲解晦涩概念的时候，我总是会使用生活中的案例做比喻。\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2、当我遇到听众（领导、同事等）挑战的时候，我总是会使用生活或工作中的案例引发听众思考并解决问题。 &nbsp; \u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3、当我讲故事说服他人的时候，我总是会尽量描绘出各种感官感受，让听众有置身于现场之感。\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4、当我讲故事打动他人的时候，我总是会建立和听者之间的联系，与听众建立情感共鸣，走进他的世界。\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5、当我讲故事说服他人的时候，我总是会关注描述清晰的角色个体细节，让听众记忆深刻，难以忘记。\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>解释自测题：\u003c/p>\u003cp>我看大家都已经做完了。\u003c/p>\u003cp>21分及以上：请问一下有21分及以上的？恭喜，这两位小伙伴挺擅长讲故事的，平常会用故事思维来影响他人，增强自己的影响力和说服力。15-21分：有没有15-21分的小伙伴？这部分的小伙伴也是做的不错的\u003cstrong>，\u003c/strong>还要再学习一些讲故事的技巧，更好地增加自己的说服力。\u003c/p>\u003cp>15分以下：那15分以下的小伙伴，可以好好地学习一下。可能平常的时候不太习惯用故事思维去和别人沟通，通过今天拆解的这两个片段后，可以多运用一下讲故事这个思维。当你有这个意识的时候，就会做得更好。我们做这个量表自测题的目的就是给大家一份警醒，\u003cstrong>运用我们的故事思维去破局我们的沟通阻碍。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>接下来我们带着学习目标，一起来阅读一下原文片段，用时2分钟。\u003c/strong>\u003c/p>\u003cp>我们能够记住那些一个个情节交织的，对我们有意义的、对我们的想法有着影响的事情，或是让我们感觉好或坏的事情。我们能够记住的，是那些能让我们情绪波动的故事。好的故事会被铭刻在听众的大脑中，字字句句被串成意义深远的整体，激发出生动而又强烈的情感。我们都记得，野狼&quot;呼時呼時吹气，直到把房子吹倒&quot;的《三只小猪》的故事。 然而大多数人却不记得数学课上的&quot;向量&quot;。\u003c/p>\u003cp>你要是想让人们记住什么，你就要让你的故事在人们头脑里留下一个难忘的形象或者镜头。让它能像《辛德勒名单》中穿红衣服的小女孩儿、《发条检》里圆挣着的眼晴，试图打电话回家的外星人一样清晰地在人们的脑海里留下印记。\u003c/p>\u003cp>细节越具体，越容易产生广泛的联系，这貌似不合常理，却是所有讲故事者共知的秘決。如前文所述，一个成功的故事\u003cstrong>必然是触动了人类某种共性的故事\u003c/strong>。其实，要触动人类的共性，首先要\u003cstrong>描述个体的个性\u003c/strong>。\u003c/p>\u003cp>例如，你若想通过自己的故事唤起听众对母亲的回忆，你首先要细致地描绘自己的母亲。你可以提到某个平凡的一天，母亲穿着朴素的衣服开着常见的车，送你去上学。这段叙述无需华丽的辞藻，也不必情节曲折，只要有清晰的细节，便能够让听众记起自己的母亲。\u003c/p>","explains":"\u003cp>大家看完了，我来讲讲我的理解。\u003c/p>\u003cp>我们一起来回忆一下，觉得原文片段中有哪些关键词，是我们可以讲好故事的要素呢？\u003c/p>\u003cp>学习者互动：个性、情绪波动、难忘的形象、细致的描绘、细节。\u003c/p>\u003cp>【拆书家回应】大家讲的都综合在一起了，这些关键词告诉了我们讲好一个故事的要素。首先它是要有意义的，让我们感受到故事的价值观；是要有细节的，让我们脑海中有强烈的画面感的；是要有情感的，拔动我们情绪，产生心与心的共鸣；是要有角色，要有形象，让我们愿意为主人公伸张正义或者频频点赞；\u003c/p>\u003cp>【对比说明】\u003c/p>\u003cp>这样说吧，讲一个故事不难，但讲好一个故事并不是一件容易的事情。从古至今，每天都诞生了数不清楚的故事，但只有一些好故事才会流传下来。\u003c/p>\u003cp>举个例子来说，我们天天看到的一些八卦故事是不是好故事呢？ \u003c/p>\u003cp>学习者互动：不是，只是资讯\u003c/p>\u003cp>【拆书家回应】不是好故事，它并没有传递出价值感，没有意义。它只是资讯。\u003c/p>\u003cp>那千百年来传承下来的小马过河、龟兔赛跑等等，是不是好故事？\u003c/p>\u003cp>学习者互动：是的，它是有寓意的。\u003c/p>\u003cp>【拆书家回应】是的，这点特别好，它传递了价值观，还有人物角色的，有画面感等等。也就是好故事与一般的故事是有差别的。\u003c/p>\u003cp>再举一个故事的营销案例，故事是可以用在营销案例中。（见上图）这是江小白的一个营销案例，一个年轻人借酒消愁的样子，他刚好失恋了，就去买酒，在这个过程中就一幅很消愁的样子。这时一句文案出来：“说不出的事叫心事，留不住的人叫故事。”这样故事营销案例容易走进用户的心目中？会比一般的酒更容易打动用户吗？\u003c/p>\u003cp>学习者互动：针对某些人群，失恋、情绪低落的人会比较有触动。\u003c/p>\u003cp>【拆书家回应】是的，针对它的目标用户来。这个容易打动他，就好像我也有这样的经历，打动了我的心，传递出我也在慢慢走出消沉的价值观，又有情感的共鸣。这就是一个好故事的营销案例。\u003c/p>\u003cp>How :\u003c/p>\u003cp>那么，刚刚讲完，我从几个点来剖析，它传递出了一个讲好故事的特点：要有价值感、情感、角色感（主人公）、因此，我基于原文片段和以上案例，拆解出如何讲好故事的三个步骤：\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp;&nbsp; 首先找到传递的意义和价值。就像思维框架一样，要找到那个WHY，找到意义点，传递出来价值，通过价值来影响他人，与我们达成统一。\u003c/p>\u003cp>2.&nbsp;用我们熟悉的“五感法”。就是我们从小学的，你耳朵听到什么，你眼睛看到什么，你鼻子闻到什么，你舌头触摸到什么，用这感官去占领，让你感受到很好，更细节、形象的东西。\u003c/p>\u003cp>3.&nbsp;突出主人公（角色感），什么样的角色讲什么样的话，让你更难忘。比如我们说到猫和老鼠，这个故事的主人公就特别形象。\u003c/p>\u003cp>举个例子：\u003c/p>\u003cp>之前给一个公众号投稿，最后没有中。这篇文章中大致是想表达，国庆节，我有一个闺蜜A一直告诉我国庆要去哪里玩，而另一个闺蜜B在她的眼中没有假期概念，假期也在学习的事。主编反馈我说，“你这篇文章没有传达出来什么意义，你只是在感触，但没有说传达什么价值观；你的感官占领，细节的东西太少了；你想突出哪位主人公。”\u003c/p>\u003cp>今天学完这个片段后，我整理完后，我可以用步骤改一下这篇文章。\u003c/p>\u003cp>1、 首先找到传递的价值感和意义。我们的每一个选择，暗含了命运的轨迹。当你自律的时候，你就能过上更好的人生，变成自己想要的样子。但如果你不是那样，你只是想玩，又抱怨，你是永远没有办法改变自己的人生。我想传递这个正面的价值观。\u003c/p>\u003cp>2、 增加五感。用我们在微信中聊天的话语、她拍的一些照片、她喜欢一些什么东西，增加真实感。\u003c/p>\u003cp>3、突出角色：用三分之二的篇幅突出有想法闺蜜朋友B，眼睛里没有概念假期的朋友。她也是有内心的挣扎，为什么会转变成这样正能量的人，也是有一个过程的，会加入一些这样的篇幅。这样的话，会显得这篇文章更形象一点、更有价值感。\u003c/p>","interaction":"\u003cp>我们先来分下小组，分成两组。\u003c/p>\u003cp>【\u003cstrong>[A1\u003c/strong>\u003cstrong>反思经验\u003c/strong>\u003cstrong>]:\u003c/strong>在上一个片段中，我们大家都写了一个故事，大家回过头看看，自己讲的那个故事是不是好故事？如果运用到我们今天讲的讲好故事的三个步骤，觉得哪个步骤会更难一点？我们在小组内讨论一下，讨论4分钟，到时请每一组小伙伴派一个代表来分享。\u003c/p>\u003cp>第一小组代表：（也是前面故事剧本的分享者RANGO）\u003c/p>\u003cp>前面代码的故事讲的挺无聊，下次有这样的分享，我可以运用今天的方法做得更好。\u003c/p>\u003cp>1、要传递一下价值，小伙伴番茄帮我升华了一下，其实就是一种生活态度。就像童子军军规，我们每一次在离开营地的时候，都让它变得更干净一点点，这样整个营地就会变得更干净。就像我们的生活态度一样。我们整理家务的时候，抽出一大块的时间来整理，就让它变得更干净一点点。\u003c/p>\u003cp>2、第二是感官占领。照片还不够，垃圾感受不到。让大家想象（另一位小伙伴说在办公室制造一些垃圾，味道会比较重）。想象一下垃圾，再想象一下代码，我们每一天都走那里过，每天都在代码里找BUG，就像在垃圾里找BUG一样。黑排角我可能是一年去一次，每天都在垃圾堆里寻找。然后给他们一些时间慢慢想，想完之后可以想象一下那个味道，嗅觉上也想像一下。然后再问他们要怎么来解决这个问题。\u003c/p>\u003cp>3、第三角色，就是参与者，让大家都参与进来。\u003c/p>\u003cp>讲好故事的三个步骤更个更难？&nbsp;&nbsp; 五感占领会比较难。\u003c/p>\u003cp>另一个小组代表发言：\u003c/p>\u003cp>讲好故事的三个步骤更个更难？&nbsp;&nbsp; 五感占领会比较难。\u003c/p>\u003cp>\u003cstrong>【A3微行动学习】\u003c/strong>\u003c/p>\u003cp>【明确新的问题】大家都不用投票了，都觉得五感占领特别难，我们就以此为案例，为什么这个会很难呢？探讨背后的原因？比如刚刚有讲听到的，眼睛看到的，这些是我们日常生活中会感受到的，为什么会觉得特别难呢？\u003cstrong>背后本质的原因是什么？\u003c/strong>看上去又是每天会遇到的，探讨一些本质。讨论出一点就记录一点，在小组内讨论出来。用时三到四分钟，再来分享一下。\u003c/p>\u003cp>第一组代表发言： \u003c/p>\u003cp>1、 \u003cstrong>要从一个案例里，充分调动出来会难（追问）调用的五感比例不一样，\u003c/strong> 有些人可能是视觉型，有些人是听觉型。正常来说，都是听觉视觉用的比较多，另外三个用的比较少。\u003c/p>\u003cp>2、 只讲一个简单的事情是没有对比冲突的，没有那种震撼的感觉，\u003cstrong>你要制造强烈的对比\u003c/strong>。（追问）用对比造成强烈的冲击，会忽视对比的作用，就像心里学说的，如果你是同一种颜色，你是感觉不到差异化的。\u003c/p>\u003cp>第二组代表发言：\u003c/p>\u003cp>1、 \u003cstrong>只是专注于我们自己。\u003c/strong>（我执，很容易变成我只在自己的世界里面，很容易忽视别人）\u003c/p>\u003cp>2、 \u003cstrong>认识不足\u003c/strong>（追问）我认识的东西有限，举个例子，他在讲劳斯莱斯的车子，讲的很历害，但是我对这个没有研究过，连牌子我也不知道怎么样的。再精采我还是感受不到你的）因为对事情不了解，有认识的盲区。\u003c/p>\u003cp>【讨论解决方案】\u003c/p>\u003cp>好的我们找到了这些原因，有以上四点，可那接下来我们一起来解决方案。举个例子，我们总是专注于自己，那我们就要多去倾听，有同理心，多去观察，这就是我们的一个解决方案。\u003c/p>\u003cp>我们投票来选一个本质问题来讨论：1）调用的五感比例不一样&nbsp; 2）忽视对比的作用。3）总是专注于自己 4）认识不足\u003c/p>\u003cp>最终投票第2点，忽视对比的作用 大家觉得非常重要。\u003c/p>\u003cp>通过讨论，忽视对比的解决方案如下三点：\u003c/p>\u003cp>1）找出反面例子、正面例子，搜集素材。\u003c/p>\u003cp>2）找出之前和之后的差异。如减肥前，减肥后。结婚前，结婚后。\u003c/p>\u003cp>3）夸张手法，特别小的一件事联系到价值观提升。就是一个小行为的改变，影响差距大。\u003c/p>\u003cp>【布置作业-找人分享】拆书帮一直提倡学以致用，教是最好的学，所以接下来给大家布置下一个作业，请大家在接下来一周内找到你要分享的人，可以是我们的朋友、同事、下属等等，把我们讨论的这个“如何讲好一个故事”的方法分享给他？想想你会和谁分享？你会怎样分享？可以帮助到他解决什么问题？请大家花2分钟时间写在便签纸上，呆会请一个伙伴上来分享下。\u003c/p>\u003cp>学习者归一分享：\u003c/p>\u003cp>分享人物：室友\u003c/p>\u003cp>解决事情：室友的妈妈想要室友回老家去做老师，她在深圳做客服之类的工作。她一直想在深圳，不想回去。她不喜欢老师这个职业，而且工资又低。在深圳工资高，朋友又多，不想离开。\u003c/p>\u003cp>解决方法：让她和她妈妈去讲一个故事，传递在深圳发展的价值感和好处，先和她妈妈讲，深圳的发展较好，对未来有多大作用，讲一下深圳的创业者在这边得到了什么，让老妈感受到在深圳发展是很大的，不要局限于铁饭碗。\u003c/p>\u003cp>【有力结尾】：\u003c/p>\u003cp>回顾一下，我们今天的学习内容，第一个片段我们讲的是什么呢？学会“分析问题、匹配故事、匹配现实（故事后面的意义）”的三步曲来讲故事，找到我们生活和工作当中生活的场景，通过讲故事的方式达到我们想要的沟通效果。第二个片段讲的是什么？如何讲好一个故事，运用“传递价值、运用五感、突出角色”步骤来讲好一个故事，我们找到解决五感的办法，就是找到例子，找出之前和之后的差异，运用夸张的手法。今天就是大家一起来找到了解决方法，这一点非常好，愿我们都用故事思维去突破我们沟通的阻碍，成为一个会讲故事的高手！谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1574345637000,"updated_at":1574346252000,"ria":true},{"id":8419,"topic":"讲有“人情味”的故事","learn_goal":"学习讲有“人情味”的故事，触及共通的人性，","remark":"通过讲自己的有“人情味”的故事，让自己变得更容易接近，从而增进感情与相互了解。","level":"TF2-3","duration":30,"status":29,"type":0,"chaishujia":{"username":"郑春红","city":"沈阳市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp;\u003cstrong>学习目标\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; 学习讲有“人情味”的故事，触及共通的人性，发挥个人影响力，影响别人愿意配合或增加亲近感。&nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; 大家好，我是紫钰，爱学爱玩爱快乐的紫钰。\u003c/p>\u003cp>首先，我们先来分一下组，左手边的伙伴是一组，右手边的伙伴是一组。\u003c/p>\u003cp>&nbsp; &nbsp; \u003cstrong>图书介绍\u003c/strong>\u003c/p>\u003cp>\u003cstrong>F\u003c/strong>\u003cstrong>特征\u003c/strong>\u003cstrong>：\u003c/strong>今天我们来一起学习的是《故事思维》，这本书的作者安妮特·西蒙斯，是将故事思维应用在商业领域的先驱，作者开创性地提出商界沟通中常用的六大类故事，并详细阐释了在何种情况下、如何讲述这些故事，彻底讲透了用故事提升个人在商界影响力的方方面面。\u003c/p>\u003cp>\u003cstrong>A\u003c/strong>\u003cstrong>优势：\u003c/strong>这是一本沟通与经营管理领域的销售书，被推崇为商界推广故事技巧的“圣经”，美国国家航空航天局、美国国税局、微软公司一致推崇的故事课程，读起来趣味性和指导性都很强。\u003c/p>\u003cp>\u003cstrong>B1\u003c/strong>\u003cstrong>利益：\u003c/strong>你有过在与朋友聚会时想讲个故事活跃一下气氛，却发现自己的故事不咸不淡，其他人也是在勉强应和着，让自己陷入了很尴尬的境地吗？你有过希望与对方拉近距离，却不知道应该讲些什么的时候吗？相信《故事思维》这本书可以带给你解决这些问题的办法。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; B2利益：\u003c/strong>今天我们学习片段的主题是：讲有“人情味”的故事，通过我们自己有“人情味”的故事，让别人更多的了解我们，进而增进双方关系，甚至影响对方。下面我们一起来阅读原文片段。\u003c/p>","ratings_count":2,"texts":[{"id":12066,"quote":"\u003cp>\u003cstrong>片段来源：《故事思维》\u003c/strong>\u003c/p>\u003cp>\u003cstrong>主题：讲有“人情味”的故事\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【原文】： \u003c/strong>\u003c/p>\u003cp>当我们发现一个享誉世界的伟大领导者还留着儿时的泰迪熊，他的形象就会变得更有“人情味”，也更容易接近。当我们发现一个邪恶的暴君在他的狗生病的时候彻夜难眠，他也会显得更加有人性。故事让我们触及了神秘之处，善恶混杂 我们共同的人性。&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003c/p>\u003cp>在我家乡的教堂里有一对富有的夫妇(每个教堂都有一对)、他宾德莱森夫妇，被当作贵族一样供着。每个星期天，他们挺直后背坐靠背凳上，穿戴得一丝不苟，对我来说，他们就是另一个世界的人。&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003c/p>\u003cp>最近，我回故乡探亲，午饭的时候我凑巧挨着宾德莱森夫妇坐。我不知道该说点什么。直到宾德莱森夫人开口说，“那就像我挂掉了主日学校的考试”，我跟她说，我都不知道你还会不及格。她笑着说，当她还是个小女孩儿时，父母换了教堂，即使在之前的教堂里她已经是三年级但由于她的年龄，新教堂把她放到了二年级班。她说：“我非常羞愧，感觉就像我被留了一级，像挂掉了主日学校的考试一样。”此时，对我来说宾德莱森夫人才变成了一个正常人。我仿佛能看到那个脆弱的小女孩仍旧存活在这个威严端庄的女人身体里。我能将那一部分的她与我联系在起，那部分就像我自己一样。&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003c/p>\u003cp>&nbsp; &nbsp; 当一个故事带我们触及人性时，我们才会意识到，其实彼此更多的是相通而非相悖。一旦你创造出了那种感情，你想要影响的人就更愿意配合你。他们从本质上感觉到：“我们是一样的，你和我……现在你想我为你做点什么？”\u003c/p>","explains":"\u003cp>\u003cstrong>What:\u003c/strong>这个拆页让我们学习到，可以通过讲自己的有“人情味”的故事，让自己变得更容易接近，从而增进感情与相互了解。 \u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>Why: \u003c/strong>如果我们表现的过度的理性刻板、过度注重事实、数据和理性分析，会让我们的影响力大打折扣，成为人际关系的绊脚石。\u003cbr> &nbsp;&nbsp; \u003cstrong>&nbsp;\u003c/strong>预防异议：有人可能会说，讲故事很简单啊，谁不会讲故事呢，但是要讲好一个故事，而且要通过一个故事让别人愿意接受我们，与我们成为朋友，甚至去影响对方，就需要一些技巧了。\u003c/p>\u003cp>\u003cstrong>How:\u003c/strong>我们一起来看一下，如何来讲好一个有“人情味”的故事呢？我们可以分成以下三个步骤：\u003cbr> &nbsp;&nbsp;&nbsp; 1、讲\u003cstrong>自己的故事：\u003c/strong>故事要是自己真实经历过的，我们自己的故事是让对方了解自己，愿意与我们深入交往的最好工具。\u003c/p>\u003cp>2、\u003cstrong>表现“脆弱”：\u003c/strong>在讲故事的时候，可以适度地表现自己的“脆弱”，比如一次比较尴尬的童年经历，或者某次被人误解而产生的委屈，抑或自己曾经因为暗恋过一个男生而辗转无眠等等，只要是能够与对方产生共鸣，而且自己也觉得可以分享的小“脆弱”，都可以是非常好的素材。\u003c/p>\u003cp>3、\u003cstrong>有感情地表达：\u003c/strong>在讲故事的时候，要投入自己的真情实感，投入地表达出自己的经历，以及这件事对自己当时的影响，这样可以更容易让对方与你有感情上的连接。\u003c/p>\u003cp>【反面案例】：今年5月份，我们机构接了一个小学生心理团建的阶段性课程，在第一次上课的时候，我与主讲老师都只是简单的做了一下自我介绍，就开始了后面的课程，没有在一开始的时候创造机会让孩子们更深入地了解两位老师，所以这些学生只是把我们当作了“老师”，没有能够很好地与大家建立关系，接近距离。\u003c/p>\u003cp>\u003cstrong>【正面案例】：\u003c/strong>如果应用了今天我们学习的拆页，我可以讲一个我自己的具有“人情味”的故事，让孩子们更好的了解我们：\u003c/p>\u003cp>第一步，讲我\u003cstrong>自己的故事\u003c/strong>\u003c/p>\u003cp>第二步，\u003cstrong>表现“脆弱”：\u003c/strong>提前想好一个自己小学时，与孩子们有共鸣的自己的“脆弱”的故事。\u003c/p>\u003cp>第三步，\u003cstrong>有感情地表达：\u003c/strong>\u003c/p>\u003cp>我的故事是这样的：\u003c/p>\u003cp>在我上小学一年级的时候，我们班新来了一个班任，在他的一次课上，因为我没有理解题意，被老师误会不认真学习，当着全班同学的面，掐着我的脸把我提到教室前面训了一顿，小时候特别害羞的我差点因为这件事退学，这段经历对当时的自己来说真的很糟糕。后来误会解除了，这名老师居然成了对我帮助最大的启蒙老师。所以，和一名新来的老师打交道，就如同一次探险，你不知道这次探险是会让自己失望，还是会挖到宝藏，但你总是要充满希望的。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; Where:\u003c/strong>这个拆页适用于在试图与不太熟悉的人建立良好关系，或者想对对方施加影响，让对方接受自己时。需要注意的是，对方的可信度是需要提前进行判断的，而且自己讲的故事要多大程度的表现自己的“脆弱”，也需要有所掌握，以免过度暴露让对方感觉不舒服，反而影响关系的建立。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】促动参与\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>我们刚刚学习了如何讲一个有“人情味”的故事，让自己与对方的关系更亲近，现在我们一起来做一个演练。请大家认真听一下要演练的场景：你作为一名亲子教育的讲师，下周要给几十名家长做一次家庭教育讲座，那么，你如何运用今天我们学习的拆页，讲一个具有“人情味”的故事，让这些家长在第一时间接受你，愿意听你的讲座呢？\u003c/p>\u003cp>&nbsp; &nbsp; 现在我们开始分组演练，演练时间3分钟，3分钟后我会请伙伴为我们讲一讲你的故事。\u003c/p>\u003cp>&nbsp; &nbsp; 下面我们来请一位伙伴为我们分享。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; 小勇：我来分享一下我和我儿子的故事，有一天加班，我到家已经八点半了，然后我儿子就特点想让我陪送他玩，那我想我已经工作一天了，就陪他玩一会吧。结果玩到九点半，我想差不多可以洗漱了，但是孩子却还是想玩，他会找各种理由来挑战你的极限，我再回忆那天还是会觉得比较崩溃，那天我们折腾到大概十二点多，一点多才睡，我觉得每个家长都会遇到这种让自己很崩溃的时候。我们说人生是一场修行，做家长也是一场修行，我希望能够和家长一起通过学习来探讨，怎么才能够做一个更好的家长，谢谢！\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; 结语：\u003c/strong>谢谢小勇的分享。学会讲各种各样的故事，来影响甚至帮助我们身边的人，是一件很有趣的事，希望通过我们今天的拆页学习，可以让大家在生活中更容易与陌生人建立连接，通过讲自己的故事，不断地来影响他人，帮助有需要的人！谢谢大家。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp;&nbsp;\u003cbr>\u003c/strong>\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1563263196000,"updated_at":1563263285000,"ria":true},{"id":7930,"topic":"打造故事思维","learn_goal":"设想、有效讲述一个愿景的故事","remark":"是商界说故事第一人安妮特•西蒙斯的巅峰之作，讲述了如何涉及与己相关的六个故事，如何有效说给他人，提高影响力。","level":"TF3-3","duration":60,"status":29,"type":0,"chaishujia":{"username":"转圈圈","city":"青岛"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp;\u003cstrong>&nbsp; &nbsp;\u003c/strong>\u003c/p>\u003ch3>【开场】\u003c/h3>\u003cp>大家好，我是青岛筹备分舵的新手拆书家转圈圈，非常高兴地又再次拆书练级，我的三个标签是:1.喜欢分享的义工老师;2.愿意改变的学习者;3.致力于使世界变美的理工男。\u003c/p>\u003cp>我们现在的坐标是青岛，时间是晚上7点半，今天进行我的TF3-3级别的线下拆书，要求时长50～60分钟。\u003c/p>\u003ch3>【分组】\u003c/h3>\u003cp>今天前来学习的有张小喆老师、胡海默老师、任慧敏老师、刘珊珊老师、赵红老师，按照线下活动要求，今天的学习讨论分为2组，在桌子东侧的一组，西侧的一组。为了方便学习，请张老师和胡老师担任今天的组长。\u003c/p>\u003ch3>【图书介绍事件场景法】\u003c/h3>\u003ch3>【事件场景】\u003c/h3>\u003cp>上周在一个教育机构，又见到该机构的校长侃侃而谈，听者也是一个创业者，能力强，马校长希望他能够一起干教育，他要将自己的经营模式扩展，在这个宏大的网络中，他表示，他可以只当现有机构的小校长，愿意在整个教育网络帝国中当小弟，以此吸引合伙人。但是他显然找错了对象，那个听众明显在敷衍，过一会儿就走了。\u003c/p>\u003ch3>【提问】\u003c/h3>\u003cp>你都是怎样让别人相信你的故事的？是不是向别人平铺直叙讲述你的目标，甚至委屈一下自己，放弃一些利益来吸引他人，但是效果不怎么地？有没有尝试做出改善，变得更有影响力呢?\u003c/p>\u003ch3>【影响】\u003c/h3>\u003cp>现实中，经常会出现这样的情况，你的目标很宏伟，但是呢，你不会用更有吸引力的方式向他人表达自己，你只是描述了一个平铺直叙、苍白乏味的事实，没有打动他人，很多机会、资源离你远去，你渐渐孤立独行，事业逐渐渺茫。你是一个不会地球语言，只会开飞碟的外星人吗?让他人认为你过来就是抓人，或者对地球不利的。\u003c/p>\u003ch3>【解决】\u003c/h3>\u003cp>《故事思维》这本书，就介绍了解决你这些问题的方法。这是故事大师安妮特・西蒙斯的奠基之作，畅销全球十余年。书中开创性地提出商界沟通中常用的六大类故事，认为说故事永远胜于讲道理，但说故事并非是与生俱来的天赋，是一种可以学习和逐步提高的思维模式。今天学习的主题就是设想一个‘愿景’故事、有效向他人介绍你的‘愿景’故事，学成后就会有影响他人的法力，他人会听你的故事，理解你的计划和他们在其中所扮演的角色，会跟随你一同实践这个‘愿景’故事，甚至可能会成为这条路上的先锋。\u003c/p>\u003ch3>【总学习目标】\u003c/h3>\u003cp>今天我们的学习目标是:在跟随我完成本次的现场学习后，伙伴们能够在协同他人完成共贏目标时，使用明确目标、构建场景、描述利益的步骤设想一个‘愿景’故事，使用接近他人、聆听他人、修改和传播故事的方法，将设想的‘愿景’故事表达到他人，促进人群清醒、合作，促进共同愿望的实现，使劳动变得更有意义。\u003c/p>\u003cp>下面给大家2分钟的时间阅读第一个片段。阅读完毕后，请大家给我举手示意一下。\u003c/p>","ratings_count":2,"texts":[{"id":11478,"quote":"\u003cp>拆解片段来自《故事思维》P22～23\u003c/p>\u003cp>主题：“愿景”的故事\u003c/p>\u003cp>当听你说故事的人（不管对方是一个人还是一群人）已经了解你是个什么样的人，以及你讲故事的目的，那么，他们接下来最想听到的是，你究竟能给他们带来什么好处。\u003c/p>\u003cp>我相信任何人在讲故事之前，都会考虑到听众的收获。然而，许多人在描述将会给对方带来的利益时表现得非常槽糕。有时演讲者过于注重如何将他的思维翻译成听众听得懂的语言，或者如同报流水账一样描述了一个平铺直叙、苍白乏味的事实，这就像，当人们准备听你描述寿司的滋味时，你没有讲述一个活色生香的吃寿司的故事，只是干巴巴地说，“生鱼片味道还不错”。\u003c/p>\u003cp>假设，某个CEO梦想他的公司“5年内发展成拥有20亿资产的公司”。这个愿景可能会让他每天都充满了干劲，但这不意味着那些在大厅里听他描绘宏图的区城经理、推销员或者行政助理也会跟他一样，他们甚至可能对他描绘的宏图不屑一顾。\u003c/p>\u003cp>他可能已经迷失在自己的幻想中了——把公司变成“拥有20亿美元资产的公司”所能带来的好处，完全没有意识到其他人跟他的感受不一样。作为公司的CEO，他面临的情况将更加槽糕，因为在大厅里听他高谈阔论的人只会假装拥有和他一样的愿景。我看到过不少CEO听到员工说“我们没有什么愿景”时发怒的神情，他们会大吼：“怎么会没有呢?——你们难道不想让公司价值几十亿美元吗? ”老兄，要是你的员工说他们没有什么宏大的心愿，那他们就是真的没有。\u003c/p>","explains":"\u003ch3>【片段1学习目标】\u003c/h3>\u003cp>在跟随我完成本次的现场学习后，伙伴们能够在向他人讲述愿景前、使用明确目标、构建场景、描述利益的步骤设想一个‘愿景’故事，避免平铺直叙愿景，促进人群合作，促进共赢目标的实现。\u003c/p>\u003ch3>【WHY】\u003c/h3>\u003cp>亚里士多德曾说过，没有图像，人的心灵便不会思考。按这个道理，要想让人们思考，调动潜意识能量，就需要一个“愿景的故事”。如果你不这么干，只能描述了一个平铺直叙、苍白乏味的事实，很难促使他们全身心为共同的目标工作。严重时，你只能默默独行，成就有限。而那些没有方向，缺少愿景的人群，将持续浑浑噩噩，过不了英雄般的人生。\u003c/p>\u003ch3>【WHAT】\u003c/h3>\u003cp>这个片段中提到了“愿景”，什么是愿景呢?\u003c/p>\u003ch3>【强化概念讲解】\u003c/h3>\u003cp>愿景，最初见于西方管理类的图书中，英文“Vision”，早期的翻译家们把它译作“视野”。度娘说：愿景是一种由组织领导者与组织成员共同形成，具有引导与激励组织成员的未来情境的意象描绘。这个定义比较艰深，不好理解，下面我举例子说明一下。\u003c/p>\u003cp>【举例子，对比出概念的逻辑】\u003c/p>\u003ch3>【案例折返1】\u003c/h3>\u003cp>数码港有个卖计算机的店，老板最近大发佛性，念叨:原所有人天雨有伞，路黑有灯，请问，这是不是他开店的愿景呢?\u003c/p>\u003cp>学习者回答:不是。\u003c/p>\u003cp>拆书家:肯定不是。为什么呢?因为，它错误地认为未实现的愿望都是愿景。“愿景”关键差异点在于它以目标为基础，案例中，天雨有伞，路黑有灯，这于一个计算机店老板的工作相关吗?不是，所以这不是“愿景”，只能是一个个人在生活方面的期望。\u003c/p>\u003ch3>【案例折返2】\u003c/h3>\u003cp>我们经常提到“为人民服务!”是不是一个愿景?\u003c/p>\u003cp>学习者回答:是?不是?\u003c/p>\u003cp>拆书家:不是吧。为什么呢?因为，它看不出目标是否达成。“愿景”关键差异点在于是描述的是目标已经达成的情景，是目标终了的状态描述。案例中，为人民服务是一个动作，不是动作的结束，也不是一种状态，所以它不是愿景，那它是什么呢?它是行动过程中需要遵循的规则，这是“宗旨”。\u003c/p>\u003ch3>【案例折返3】\u003c/h3>\u003cp>我们经常带孩子看影视剧，武侠剧，描述江湖儿女快意恩仇的有这么一句话:相忘于江湖，孩子也比较感兴趣，请问，这是不是愿景呢?\u003c/p>\u003cp>学习者回答:是?不是?\u003c/p>\u003cp>拆书家:是。为什么呢?因为，它能联系到场景，“愿景”关键差异点在于它具备场景的要素，比如时间、地点、人物、事件。案例中，时间是未来，人物是江湖儿女，地点是江湖、事件是忘记。\u003c/p>\u003ch3>【互动】\u003c/h3>\u003cp>拆书家:请问江湖是在哪里?\u003c/p>\u003cp>学习者回答:旅店、酒馆、路上\u003c/p>\u003cp>拆书家:江湖是指这一类地方。\u003c/p>\u003cp>拆书家:有未来具体时间吗?年月日?早晨?晚上?\u003c/p>\u003cp>学习者回答:没有…\u003c/p>\u003cp>拆书家:但肯定是未来。\u003c/p>\u003cp>拆书家:是不是这些都比较虚？\u003c/p>\u003cp>学习者回答:是?不是?\u003c/p>\u003cp>拆书家:是。为什么呢?因为，它没有具体的场景，“愿景”关键差异点在于它把具体事物都抽象了，只留一些要素框架。案例中，基本要素仍是存在的，比如：时间是未来，人物是江湖儿女，地点是江湖、事件是忘记。这是一种升华，是一种意象描述，是抽象的情景展示。\u003c/p>\u003ch3>【知识点最后定义】\u003c/h3>\u003cp>综上所述，所谓愿景，就是希望的情景。它具备下列特征:\u003c/p>\u003cp>1、以目标为基础。\u003c/p>\u003cp>2、是目标达成之后的情景或状态描述。\u003c/p>\u003cp>3、可简化为一种意象描述，有时间(未来)、地点、人物、事件等一些代表性要素，方便传播和记忆，但它是虚幻的而不是具体的。因为目标着眼未来，还没有真实发生，它只是人脑中过往场景的升华意象，是具体事物的抽象。\u003c/p>\u003ch3>【引出使用步骤，给出具体的How】\u003c/h3>\u003cp>基于上面的讲解，结合原文，我们要设想一个“愿景的故事”，需要以下步骤:\u003c/p>\u003cp>第一步:明确目标。明确你要实现的目标，不要被目前要解决的问题现象所左右。\u003c/p>\u003cp>第二步:构建未来目标达成的场景。利用想象力发起一场头脑风暴，未来目标达成后，你希望会发生的地点、人物、事件、进过与结果。需要强调的是好的事件、好的结果。\u003c/p>\u003cp>第三步:描述他人得到的利益或者下一步行动的意义。未来的结果能够产生利益，让他人看到、感觉到自己能够得到的利益，认识到下一步行动的意义。\u003c/p>\u003ch3>【举个例子】\u003c/h3>\u003cp>就以阿里巴巴的‘愿景’故事说说吧。\u003c/p>\u003cp>阿里巴巴，要做电子商务。马云说，我们的愿景是“让客户相会、工作和生活在阿里巴巴，并持续发展最好102年。”有个‘支付宝’产品，就是他弄的，目标是让更多的人使用网上支付。\u003c/p>\u003cp>那么，一旦达成这个目标，就会有卖电脑的、实鞋子的、批发零售的…等等，都到阿里巴巴交易和支付，当然也有募捐的、碰瓷的，订餐的，要饭的……，此时在你的脑袋里，会有各种各样的场景，这也是阿里巴巴的目标比较能得到很多人认可的原因。\u003c/p>\u003cp>这些场景都有产品、业务，都要付款，都有支付流程，都有购买之后的需求满足，都有商品的展示、都有交易的喜怒哀乐。\u003c/p>\u003cp>假若你是拆书帮的一名拆书家，如果有人对你说：“让我们相会、工作和生活在阿里巴巴，并持续发展最好102年。”你肯定会笑，因为到阿里巴巴平台上拆书，你觉得有点虚。\u003c/p>\u003cp>如果他对你说：“想想看 ，线下活动时，一名拆书家介绍的书你比较感兴趣，你对这本书充满了期待。那很好，马上去阿里巴巴下单，网上支付，也许第二、第三个你慵懒的早晨，快递小哥就礼貌地敲响你的门：‘美女，你的书到了！’”\u003c/p>\u003cp>又或者对你说：“当你有点饿了，不想做饭，那就在手机上动动手指，刷卡支付，一会儿，就有骑手告诉你，‘美女，你要的烧饼到了，到楼下取吧’。色香味俱全的烧饼马上就能吃到了。”\u003c/p>\u003cp>这是一种什么样的感觉呢？你能够体验到那散发墨香的书籍，体会到那令人击节赞叹的故事吗？能够体会到那酥脆香满腮的感觉吗？\u003c/p>\u003cp>我想，即使没有一些送红包的促销活动，我也会去体验一下。\u003c/p>\u003ch3>【点破燃点】\u003c/h3>\u003cp>理解起来很累吧，现在请问一下伙伴们，在明确目标、构建场景、描述利益中，最难的是哪一点呢?\u003c/p>\u003cp>学习者1:构建场景。\u003c/p>\u003cp>学习者2:利益描述。\u003c/p>\u003cp>拆书家反馈:为什么呢?是因为构建场景需要丰富想象力，对于我这个理工男有点不容易。另外，说到利益，大家都觉得不好意思。不过这没啥，‘亲兄弟还明算账呢’，利益描述没啥不好意思的。\u003c/p>\u003ch3>【WHERE】\u003c/h3>\u003cp>这个方法适用于向家庭、团体中的成员介绍你的计划目标、你追求的初心、梦想，或者你觉得有必要去改善一下自己的方式，让他们更投入时。\u003c/p>\u003ch3>【预防异议】\u003c/h3>\u003cp>有些小伙伴说，愿景需要用故事来讲述吗?一句话的简述足够激励吧，为什么还要讲一个‘愿景’的故事呢？\u003c/p>\u003cp>拆书家:愿景有简化描述，但是细节可能不具体，对于以理性思维为主的人可能会感觉比较抽象。另外，愿景需要调动更多人，如果根据具体情境再补充细节，那么就更能吸引人，扩大影响力，促进他人明白自己的角色和任务，跟随你一同实践这个‘愿景’故事。\u003c/p>\u003cp>【互动】【追问】\u003c/p>\u003cp>有一个参加冯老师课程的学员，她比较懒，她说:“我的愿景是‘孩子在学习，老公在拖地，我在沙发上看手机。’这是不是愿景呢? ”\u003c/p>\u003cp>学习者:是。\u003c/p>\u003cp>这是一个能够激励人的愿景吗?\u003c/p>\u003cp>学习者:是，但是只能激励一个人，不能激励其他人。\u003c/p>\u003cp>拆书家：是的，是愿景。但不是一个有效的愿景。为什么呢?因为它只能激励一个人，不能激励很多人。“愿景”是否有效，关键在于目标是否合适。目标是愿景的基础，目标要符合SMART，如果有问题，愿景的故事就会出现问题。案例中，家庭是有共赢目标的。如果脱离了这个目标，愿景的故事就不会被他人认同，寸步难行。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>从上面的例子可以看出，愿景必须依托符合原则的目标，赋能范围是有共同目标的人群，目标如果有问题，愿景也很难凑效，赋能范围变小，影响力变小。\u003c/p>\u003cp>这类愿景还有:“宁愿在宝马车里哭，不愿在自行车上笑”，“我爸是李刚”等等。\u003c/p>","interaction":"\u003ch3>【A2】催化应用【教学习者编写剧本】\u003c/h3>\u003cp>通过刚才的学习，大家已经了解如何设想一个愿景的故事了，赵周老师在《这样读书就够了》里面提到:在大脑中过一遍，等于在实际中应用了一遍。所以我要请大家每人编一段小故事，要求是未来一周内可能发生的场景，可以是家庭中、工作中、合伙中等等，要设计2个角色交代一下故事的起因，发展的经过，最后通过设想“愿景的故事”达到了一个什么样的结果。\u003c/p>\u003cp>故事当中要交代你或者你和他人的共赢目标，要使用我们刚刚学到的明确目标、构建场景、利益描述等步骤，最后形成一个 “‘愿景’故事”，需要注意的是，分享的一定是你未来可能遇到的情景，不是你的过往经历。由于时间比较短，‘愿景’故事的要求不一定要非常精致，实用就行了。\u003c/p>\u003cp>两个组可以分别先讨论，请把讨论的摘要写在一张纸上，时间5分钟。\u003c/p>\u003cp>5分钟后我请一组伙伴分享自己的故事，OK，那现在开始。\u003c/p>\u003cp>【案例记录】\u003c/p>\u003cp>时间:明后天\u003c/p>\u003cp>地点:家中\u003c/p>\u003cp>人物:罗萃老师和她儿子\u003c/p>\u003cp>背景or起因:罗老师说他儿子基础弱，期中考试成绩不理想，母子俩讨论一下如何提高，目标是争B保C，加油。\u003c/p>\u003cp>【互动】\u003c/p>\u003cp>罗老师:我儿子喜欢班里的一个女孩，希望将来能够走到一起。（明确目标）\u003c/p>\u003cp>拆书家:这就完啦？场景呢?需要找到未来成绩很好后的一个场景来讲设计这个愿景的故事。\u003c/p>\u003cp>经过(包含对话):\u003c/p>\u003cp>罗老师:那个女孩成绩好，你感觉他喜欢什么样的男孩?\u003c/p>\u003cp>罗老师儿子:她肯定喜欢成绩好的男孩。\u003c/p>\u003cp>罗老师:你愿意和她并驾齐驱吗?（构建场景）\u003c/p>\u003cp>罗老师儿子:愿意!\u003c/p>\u003cp>结果:(罗老师:)我和儿子的‘愿景’故事，就是我和孩子共同努力，将来他能够和他心爱的女孩共同学习，成绩相当，并驾齐驱，将来能够生活在一起（利益描述）。\u003c/p>\u003cp>【互动】\u003c/p>\u003cp>大家觉得罗老师的‘愿景’故事对她儿子好用吗？\u003c/p>\u003cp>学习者：好用。\u003c/p>\u003cp>【两个片段之间的关系】\u003c/p>\u003cp>第一个片段解决的问题是当向他人展示愿景时，为避免平铺直叙，更有效调动他人思考，就设想一个愿景的故事，ok现在故事有了，怎么才能有效讲给他人听并影响他人呢?这是第二片段要解决的问题，呈递进关系。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":11479,"quote":"\u003cp>【自测指令】\u003c/p>\u003cp>在阅读片段2之前，请你做一个简单的测试，看看你过去的情况怎么样。在发给大家的8个题目中，请按照1～6分的标准给自己打分，1代表完全不符合，6代表非常符合。请仔细阅读下面表格中的每句话，根据自己的实际情況为自己打分。\u003c/p>\u003cp>1.我觉得过往经历对一个人的改变有很大的阻碍。123456\u003c/p>\u003cp>2.我需要考虑在某项合作中他人能够获得的利益和支出。123456\u003c/p>\u003cp>3.我使用听众的群体语言去和他们沟通。123456\u003c/p>\u003cp>4.我感觉每个人都很忙着去做自己觉得对的事情。123456\u003c/p>\u003cp>5.我需要放下姿态，创造机会接触要影响的人。123456\u003c/p>\u003cp>6.在觉得对方胡说时，我耐着性子去试图了解他为什么这么说。123456\u003c/p>\u003cp>7.我觉得同他人谈鸡毛蒜皮的小事很有意义。123456\u003c/p>\u003cp>8.我对一个人谈起他的过往保持高度专注。123456\u003c/p>\u003cp>合计分数:\u003c/p>\u003ch3>【解释量表题】\u003c/h3>\u003cp>您以前是怎么把自己的‘愿景’故事讲给别人的呢?让大家做这个测试题的目的，就是想了解一下大家以前的做法。测试题共8道，总分48分。\u003c/p>\u003cp>如果你得了48分，那是一件少有，值得恭喜的事情，因为在凝聚人心方面你绝对是一个高手!\u003c/p>\u003cp>如果你得了24～47分，说明你有效地把自己的‘愿景’故事讲给他人，但并不完美，还有努力的空间。\u003c/p>\u003cp>如果你得了23分以下，那你需要留意了，你还有较大的提升空间。你，今天来对了!接下来关于拆页内容的学习，你会有较大的收获。\u003c/p>\u003cp>下面请大家阅读第二个拆页P194～P195，时间2分钟。\u003c/p>\u003cp>【R2】原文片段\u003c/p>\u003cp>主题:讲一讲你的‘愿景’故事\u003c/p>\u003cp>无论你打算影响谁，一个预示美好未来的故事都可以促进你们之间的合作。聆听你希望影响的人们讲故事，是推动人们向你所希望的方向前进，并共同打造未来新故事的唯一路径。\u003c/p>\u003cp>“愿景”故事可通过深度理解当下故事中的恐惧、希望和梦想而搭建起来。“愿景”故事可以劝说一个年轻人洁身自好，可以劝说靠救济金生活的人去寻找工作，也可以让一位员工更关注客户服务。\u003c/p>\u003cp>如果你希望影响的人有不同的文化背景，或者仿佛是来自其他星球的叛逆少年，那么这些对你起作用的未来故事不一定对他们有效。如果你试图讲述一个有效果的故事，那你就必须理解他们的经历和他们的世界。\u003c/p>\u003cp>如果你想改变某个人或者某个群体的某一行为，你必须去他们的住所拜访他们，站在他们的角度，分析你所扮演的角色。你是一个说外语的局外人吗?你为改善客服提出的新系统、对你的员工意味着更多的工作、又一个愚蠢的企业项目，还是更自豪，更多工资，更少工作负担？\u003c/p>\u003cp>聆听、不要啰唆。聆听意味着不管你是否同意，都要努力去挖掘对方行为的真正含义。\u003c/p>\u003cp>一个总裁请求我的帮助，他刚刚进行了一次并购，员工有抵触情绪和消极情感，但是他不愿坐下来倾听员工的故事，也没有提供愿景，要知道，未来故事能够解决并购之后的恐惧和欲望。\u003c/p>\u003cp>如果不做出改变，那么总裁和我都在浪费时间和精力。我意图唤醒他，需要知道是什么原因让他在影响他的员工方面产生了问题。\u003c/p>\u003cp>我听到总裁说:“好，那我们暂时搁置那些，你有什么好的策略建议?”我很诧异，暂时搁置?最佳陈述事实的方法是保全事实的完整性。暂时搁置人们的深度恐惧和欲望，或许是一个暂时有用的策略，但并不能获得长久持续的影响力，如果你要获得的是长久的关系、承诺、忠诚，或者不寻常的创造力，你必须花时间了解、聆听整个故事，以及你希望影响的对象的完整世界。\u003c/p>","explains":"\u003ch3>【简短互动】\u003c/h3>\u003cp>第二个片段大家已经看完了，在讲解之前，请大家做几个填空题。\u003c/p>\u003cp>这个片段的关键词是什么?\u003c/p>\u003cp>学习者:聆听。\u003c/p>\u003cp>聆听什么内容呢?\u003c/p>\u003cp>学习者:他人的经历和他们的世界。\u003c/p>\u003ch3>【I】拆书家讲解引导\u003c/h3>\u003cp>好的，非常棒，接下来我讲解一下这个拆页。\u003c/p>\u003ch3>【片段2学习目标】\u003c/h3>\u003cp>在跟随我完成本次的现场学习后，伙伴们在向他人传播愿景时，能够使用接近他人、聆听他人、修改和传播故事的方法，将适合具体场景的‘愿景’故事表达到他人，启发他人思考，促进共同愿望的实现。\u003c/p>\u003ch3>【WHAT】\u003c/h3>\u003cp>本片段讲的是，‘愿景’故事能够改变他人，但接受的前提时，要能够顺利沟通，需要你聆听他人，纵向到点，包括与工作、切身利益相关的事，横向到边，包括与工作无关的完整故事。\u003c/p>\u003ch3>【WHY】\u003c/h3>\u003cp>为什么呢?是因为‘愿景’故事不过是把交流的内容披上了故事的外衣，容易被人接受，但是这个故事的中心是你的目标，要使故事真正有效，朝着你希望的方向前进，还需要聆听他人的经历和完整的世界。如果你不这么做，可能就无法有效进行情感上的连接，因为你面对的可能是一个外星人，不在一个频道，更难以达到交流的效果，更谈不上接受和实践你的‘愿景’故事。\u003c/p>\u003ch3>【WHERE】\u003c/h3>\u003cp>这个方法可以工作、家庭、团体中，用在你想影响和改变的人群中间。\u003c/p>\u003ch3>【HOW】\u003c/h3>\u003cp>根据拆页的内容，我梳理了一下行动步骤:\u003c/p>\u003cp>第一、放下姿态，主动接近他人。暂停宣贯‘愿景’故事，调频或者降维，走进他人的外在世界。\u003c/p>\u003cp>第二、聆听他人的内心世界，重点围绕目标及切身利益提问。抱着好奇心，要聆听他人对整个环境的反应；围绕共赢目标提问，了解目标的具体环境条件；收集与目标相关的利益诉求，明确原因。\u003c/p>\u003cp>第三、用现实场景填补你的‘愿景’故事。运用同理心，穿着他人的鞋子走上几步，想一想，‘愿景’故事如果补充了这个细节，应该长成什么样子，把它切换成适合场景的模式，在适当的时候明确表达。\u003c/p>\u003ch3>【互动】\u003c/h3>\u003cp>美国有一位很有名的将军，写了一首诗，诗的名字是《塑造我儿子》有一段是这样写的：\u003c/p>\u003cp>求你让他有一颗纯洁的心，\u003c/p>\u003cp>并有高尚的目标，\u003c/p>\u003cp>使他在能指挥别人之前，\u003c/p>\u003cp>先懂得驾驭自己，\u003c/p>\u003cp>当迈入未来之际，永不忘记过去的教训。\u003c/p>\u003cp>拆书家:请问，这是不是一个愿景?\u003c/p>\u003cp>学习者:是!\u003c/p>\u003ch3>【反馈】\u003c/h3>\u003cp>拆书家:肯定是，他的目标是将孩子培养成一个真诚、自控、知过必改的人。这里面有人物，有未来发生的事件的情景。大家有没有知道这个将军名字的?\u003c/p>\u003cp>学习者:麦克阿瑟。\u003c/p>\u003ch3>【案例】\u003c/h3>\u003cp>这个愿景，也是我推崇的愿景。我儿子从小要求不太严，习惯养成的不好，甚至感恩之心也需要加强。如果我直接和他说，孩子，你需要控制自己，孩子，你需要记住上次不听爸妈话的教训，估计头也不回就怼你了。\u003c/p>\u003cp>所以，我需要放下父母高大上的姿态，平等的去交流。\u003c/p>\u003cp>孩子的语言我不会，因为好长时间没有好好交流了。我必须使用他能接受的方式。\u003c/p>\u003cp>想起来了，小的时候经常给他读故事。那么按照故事思维的套路，我就给他讲故事。\u003c/p>\u003cp>这个时候，这段诗文就成了两个故事《伊卡洛斯之翼》与《迈达斯国王》。\u003c/p>\u003cp>先说的是伊卡洛斯之翼。\u003c/p>\u003cp>伊卡洛斯渴望能在天空中飞翔，他收集树枝和羽毛，用石蜡将它们打造成一对非常坚实且华丽的羽翼。通过练习，他学会了飞翔，但他的父亲告诉他，儿子，你非飞不可的话，就去飞吧。但是，千万不要飞得太高，离大阳大近了。我替你担心啊，干万记住我说的话。可是在飞的过程中他忘记了父亲的话，绕着螺旋状的飞行轨迹不断向太阳靠近，最后翅膀融化跌落而死。\u003c/p>\u003cp>收尾时我说:“一定要听爸妈的话，不听老人言，吃亏在眼前。”\u003c/p>\u003cp>儿子不高兴了，对我说，如果再多上一句，下次就别说了。\u003c/p>\u003cp>下次讲的是《迈达斯国王》，我先端出一盆花，告诉儿子，这叫迈达斯国王，儿子很好奇，说这是我送给妈妈的，不就是“肉肉”吗，怎么是国王了，我说，我给你讲个故事，你就明白了。于是我顺利讲完了这个点石成金和没能控制自己受到教训的故事。\u003c/p>\u003cp>这次我没说为什么要讲这个故事，只是问他，猜猜为什么这盆“肉肉”叫迈达斯国王?孩子最后过来告诉我，我知道了，“肉肉”的尖端是金色的，像点石成金的手指吧?真是神奇!\u003c/p>\u003cp>至于他是否领会我讲这个故事的含义，我想日后他会理解，有助于他控制自己，知过必改。\u003c/p>\u003ch3>【预防异议】\u003c/h3>\u003cp>有的伙伴说了，听你说起愿景，怎么像诗一样?愿景是诗吗?诗是愿景吗?\u003c/p>\u003cp>拆书家:愿景同诗的共同点是都经过了情感的投入，意境的升华，在不同的场景下能产生意象，进驻人的心中，温养人的心灵，赋予强大的能量。像微软公司的愿景:“计算机进入家庭，放在每一张桌子上。”这本身就是一个需要很多人一起创作的宏大史诗，不过少了一些艺术感，少了些幻境。对于诗来说，蕴含了一个个有趣的灵魂，包括他们的一个个愿景，艺术感也很强，为了使拆解有趣，就拿来做例子了。\u003c/p>","interaction":"\u003ch4>【微行动学习】【互动提出问题】\u003c/h4>\u003cp>下面，让我们回顾一下把‘愿景’故事有效讲给他人听的三个步骤，是什么呢?\u003c/p>\u003cp>学习者:第一、放下姿态，主动接近他人。第二、聆听他人的内心世界，重点围绕目标及切身利益提问。第三、用现实场景填补你的‘愿景’故事。\u003c/p>\u003cp>这三个步骤，大家已经考虑在将来如何运用了吧，想想看，这三个步骤或者其中的小步骤，哪一步最难?\u003c/p>\u003cp>给大家一分钟的时间考虑下，然后请每组的小伙伴逐个发言。\u003c/p>\u003cp>红姐:用暗喻或明喻的方式告诉对方你的愿景，即补充一个含场景的‘愿景’故事。\u003c/p>\u003cp>张老师:具体的场景中如何体现你的愿景，在具体的场景中如何变化。\u003c/p>\u003cp>罗老师:聆听比较难，如何有效的听和提问呢?\u003c/p>\u003cp>胡老师:在愿景故事形成的过程中，如何构建场景。\u003c/p>\u003ch4>【1.明确问题】\u003c/h4>\u003cp>我梳理一下，大家共提出了这么几个问题，红姐和张老师的问题实质是一个问题，在第一个片段讲述时，有学习者也提出了2个问题需要解决。\u003c/p>\u003cp>我合并一下。现在共有四个问题要解决\u003c/p>\u003cp>第一个如何在“愿景”故事中构建场景。\u003c/p>\u003cp>第二个如何在“愿景”故事中描述他人利益。\u003c/p>\u003cp>第三个如何将‘愿景’故事适合具体的场景来表达?\u003c/p>\u003cp>第四个是在讲‘愿景’故事的过程中，如何聆听和提问?\u003c/p>\u003cp>由于时间有限，今天只能选择一个解决，大家怎么看?举手表决一下，选哪个比价有价值?\u003c/p>\u003cp>经统计，第二、第四个问题1票，第一、第三个问题2票。\u003c/p>\u003cp>在构建场景和将‘愿景’故事适合场景来表达的两个问题中，哪个更有解决价值呢?\u003c/p>\u003cp>再次统计，第一个问题3票，第三个问题1票。\u003c/p>\u003cp>好的，大家表决的结果是第1个问题。\u003c/p>\u003cp>好的，那现在我把第一个重复一下，请大家仔细听，今天我们要解决的问题是: 如何在设想“愿景”故事中构建场景？对吗?\u003c/p>\u003cp>学习者:是的。\u003c/p>\u003ch4>【2.引导分组讨论问题的本质】\u003c/h4>\u003cp>好，这个问题最初是胡海默老师提出的，那么请胡老师作为今天要解决问题的案主，有请胡老师把自己的具体的情况说一下，说明你要实现的愿景，在过程中碰到了哪些困难，可能遇到的不利情况。\u003c/p>\u003cp>时间:最近\u003c/p>\u003cp>人物:胡老师;\u003c/p>\u003cp>背景:最近筹划一个教育资源平台，把优质的教育资源以较低价格输送给教育机构，同时也吸引一些课程开发个人或者机构、投资人、学生，把他们的资源也吸聚到这个平台上，平台收取定比例的管理费用。\u003c/p>\u003cp>问题是，如何提炼场景的共同要素，把平台的特点总结成一句话的‘愿景’故事，使听到的人一下子就明白平台的意义即功用，并吸引他前来加盟。\u003c/p>\u003cp>拆书家:对于这个问题，书中并没有给出明确的答案。现在请大家以小组为单位，讨论一下：\u003c/p>\u003cp>假如你是案主，为什么会产生这个问题?产生这个问题的本质原因是什么?大家可以结合过往经验，尝试相互追问，深入的探讨一下。时间是2分钟\u003c/p>\u003cp>讨论的过程中，如果还有对问题产生的场景不明白的地方，可以由小组长再问问案主。\u003c/p>\u003ch4>【3.明确问题的本质】\u003c/h4>\u003cp>好，看见大家基本讨论出来结果，那请小组长分享一下你们讨论的结论。\u003c/p>\u003cp>小组1:胡老师的问题不是构建场景，而是如何把构建出来的场景简化成一句话，即从具体上升为意象的概括描述。\u003c/p>\u003cp>案主表述中，基本的要素都已经找到，但进行概括表达时出了问题，每次表达不固定，需要想办法把典型场景固定下来。要要解决的核心问题是如何找到经典的概括的语言。\u003c/p>\u003cp>小组2:我觉得描述不容易一致，是因为概括不到位，描述的不够经典。\u003c/p>\u003cp>拆书家：经过各组讨论，各小组共给出了共同的答案，问题的本质是: ‘愿景’故事简化的不够，需要找到一句经典的概括的语言。\u003c/p>\u003cp>【追问】\u003c/p>\u003cp>大家同意这种说法吗?\u003c/p>\u003cp>学习者:是。\u003c/p>\u003cp>下面，请问一下案主:胡老师，大家认为是你的‘愿景’故事概括简化的不够，导致你每次的表述不一致，你同意这种说法吗?\u003c/p>\u003cp>胡老师:我同意。\u003c/p>\u003cp>好的，经过讨论，大家认为问题的本质是:如何概括简化胡老师资源集聚平台的‘愿景’故事，大家还有没有其它想法?\u003c/p>\u003cp>学习者:没有\u003c/p>\u003ch4>【4.引导分组讨论解决方案】\u003c/h4>\u003cp>好的，既然我们已经找到问题的本质，下面，我们就利用5分钟时间，请组长带领大家讨论，到底如何解决这个问题?请各位伙伴根据案主描述的情況，运用同理心，以小组为单位，讨论出每组的解决方案。\u003c/p>\u003cp>5分钟后，请各小组长派员分享自己组的讨论成果。\u003c/p>\u003ch4>【5.讲解成果】\u003c/h4>\u003cp>大家讨论的非常热烈，现在我们请组长分享一下最后讨论的结果。\u003c/p>\u003cp>第一组:\u003c/p>\u003cp>第一步:找到类似行业的简述的“愿景”进行分析，找出共同点；\u003c/p>\u003cp>第二步:套用修改；\u003c/p>\u003cp>第三步:运用明喻等修辞方法。\u003c/p>\u003cp>第二组呢?\u003c/p>\u003cp>第一步:参考借签其他单位的‘愿景’。\u003c/p>\u003ch3>【追问】\u003c/h3>\u003cp>拆书家:两组都提供了自己的解决方案，两组\u003cstrong>出奇的\u003c/strong>一致。大家还有没有什么补充的?\u003c/p>\u003cp>学习者:没有。\u003c/p>\u003cp>拆书家:任老师来的晚，说一下你的意见。\u003c/p>\u003cp>任老师:在提炼场景要素方面再进一步努力，找到共同要素。\u003c/p>\u003ch4>【确认】\u003c/h4>\u003cp>经过大家修改完善，最后的解决方案是：要找到共同要素，需要以下步骤:\u003c/p>\u003cp>第一步，要借鉴其他类似功能组织的愿景描述;\u003c/p>\u003cp>第二步，套用修改；\u003c/p>\u003cp>第三步，运用明喻等修辞方法。\u003c/p>\u003cp>请问胡老师:你觉得这个方案能解决你的问题吗?\u003c/p>\u003cp>胡老师：结果呢？我需要结果。\u003c/p>\u003ch3>【拆书家反馈】\u003c/h3>\u003cp>本次只是讨论一种可行的方法，只提供你解决问题的方法。至于结果，需要你按照这种方法持续用功，那么满意的结果就会在某一天出来了。\u003c/p>\u003cp>胡老师:可以。\u003c/p>\u003ch3>【拆书家反馈】【总结】\u003c/h3>\u003cp>感谢大家的分享，经过大家的集体学习讨论，我对如何对愿景简化描述也加深了理解，由于时间关系，先交流到这儿，遗留下的其他问题，活动结束后建群，抛在里面讨论!\u003c/p>\u003cp>【找人分享的A2】\u003c/p>\u003cp>最后给大家布置一个作业，想想，你在家庭、工作、或者一个协会中，有没有共同需求的人群，根据组织的愿景，当前的具体情况，设想出一个‘愿景’故事，看看能否被他们接受，如果效果不好，想一想有没有运用上今天的步骤，一步一步继续练习，如果有了新体会，新想法，也可以在刚才的群里讨论。让大家都学习下讲一个愿景的故事，提高自己的影响力。\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>人不是活在真空中，我们要与他们交流，使用故事来表达是一种不错的思维，我们需要设想并向他人讲述一个‘愿景’故事，达成我们的共赢目标，这样生活才更有意义。\u003c/p>\u003cp>在最后，让我们重温帮主在去年底一起聚餐时描述的“愿景”故事:\u003c/p>\u003cp>多年之后，我们这些人可能老了，也有伙伴去其他地方发展了，但是拆书帮仍在，大家聚在一起，谈谈心，说说自己的事，大家一起出出主意，帮助解决，以书为伴，共同成长。\u003c/p>\u003cp>好的，我今天的拆书过级就到这里，谢谢大家。\u003c/p>\u003cp>【作业分享】(张老师)\u003c/p>\u003cp>我现在一个人当辅导老师，当前主要教数学，带了几十个学生，累得够呛，我需要招聘1-2个老师，扩大师资力量，同时也给自己省出一点时间学习。我的愿景是“让孩子回归课堂”。这个愿景可能与其他机构的目标不一样，我以孩子为中心，让他们都知道为自己的将来负责，而不是为了自己生存，去挣孩子和家长的钱。我是这么干的，第一、在招聘时，我会仔细了解应聘者的情况，看他是否是一个能放下姿态，主动接近他人的人。第二，我会问他们的家庭成员情况，喜欢什么和不喜欢什么，对薪金的要求。第三，我把“让孩子回归课堂”的愿望分孩子报名前、课程中、课程后的几个阶段，‘应该如何对待孩子’讲给他们听，并说一下自己在这方面的亲身经历，如果他们认同了，我觉得就可以试用了。结果，只有一两个人理解我的做法，并愿意和我一起搭伙，很多人并不认同我的做法，这也许是那些自由流动的老师一直没有固定工作的原因吧。非常感谢五一期间，能够参加这次学习，现在我已经能够把自己的‘愿景’故事熟练地讲给一起代课的老师和家长，发展自己的小组织了。\u003c/p>\u003cp>【微行动学习中胡老师问题的解决结果分享】（见图）：\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":11480,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}},{"id":11481,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1558445392000,"updated_at":1559457565000,"ria":true},{"id":7482,"topic":"@讲好“我是谁”的故事@","learn_goal":"学习者学习使用“我是谁”的故事，提升个人在社群里的影响力。","remark":"学习者学习使用“我是谁”的故事，提升个人在社群里的影响力。","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"翔翊","city":"淄博"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;开场：\r\n【自我介绍+目标介绍】\r\n拆动乾坤，赋能你我！亲爱的小伙伴们，大家过年好！我是今晚的拆书家高力，用三个标签来介绍我自己就是：二级拆书家、RIA学习力导师、正在奋战1000天日更达人。今天我要拆解的片段来自于《故事思维》一书中“我是谁”的故事这个主题。\r\n学习目标：\u003cstrong>在跟随我完成本次RIA现场学习之后，学习者能够把讲我是谁的故事三个步骤应用到人际交往中，迅速提升自己的关注度和信赖感。\u003c/strong> 【分组】为了方便后续大家的交流讨论，我给大家简单分下组，左手边一组，右手边一组，谢谢大家的配合！\r\n &nbsp; &nbsp;\r\n【技能点：场景法介绍图书】\r\n事件场景：在这个自媒体爆发的年代，人际交往已经不仅仅限于聚个会，面对面侃大山。微信群、朋友圈、知乎、百家等已经成为人际交往的主战场。你无论进入一个新的微信群，还是在朋友圈发一个帖子让大家关注你，是你出现在这里的首要目的。\r\n提问：怎么办呢？当下的你，可能会像幼儿园老师教小朋友那样：大家好！我叫XX！我是个一名小男生/小女生，希望大家喜欢我！（用脚趾头想想，朋友圈、微信群里有几个会买你的卖萌帐？）还有可能巴拉出自己的个人简历：我叫xx，xx年xx月出生，在xx公司工作，家住xx小区~~~\r\n影响：以上的两个方法，最终你都无法达到引起关注的目的，那么结果只有一个就是：在自己的人际圈里默默无闻，成为冷冷的冰雨中那颗孤独的星辰。\r\n解决：《故事思维》这本书，教给我们讲话“我是谁”的故事，让你迅速引起大家的关注，大大提升自己的影响力。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":2,"texts":[{"id":10949,"quote":"\u003cp>\u003cp>下面请小伙伴们用1分钟左右的时间阅读一下原文片段，读完的小伙伴请给我一个示意。\u003c/p>\u003cp>\u003cstrong>R：阅读原文\u003c/strong>\u003c/p>\u003cp>一项由《纽约时报》和哥伦比亚广播公司新闻部在1999年进行的民意调查发现，63%的受访者相信与“大多数人”相处，你“一定要小心再小心”；37%相信“大多数人一有机会就想利用你”。如果你认为这代表了你想影响的对象，那么你首先要做的就是，证明你可以被信任。\u003c/p>\u003cp>\u003cstrong>如何做到呢？\u003c/strong>刚才的那个研究给了我们一个提示：应答者也表示在他们“有交情的人”当中，85%能够“尽力做到公正”。嗯……会是一件很简单的事情吗？让人们了解你是谁，促使他们认为自己与你有“私交”，那么你的信任度必然会提高三倍吗？想象一下我们的口头语：“他人不错，我了解他”或“不是因为我不信任她，我只是不了解她”。\u003c/p>\u003cp>我们不让人们了解我们是谁，他们怎么会信任我们，并且受到我们的影响呢？要是我们不能把说服他人的企图，与回答我们是谁很好地结合，那就无异于与人们心中的评判标准擦肩而过。我们对理性的大脑花费了太多的时间而忽略了感性的大脑。感性的大脑对于被忽视非常敏感。感性的大脑更要重视、防患于未然，虽然毫无根据，但是它更能影响人们的结论。\u003c/p>\u003c/p>","explains":"\u003cp>\u003cp>\u003cstrong>【强化概念讲解、引出知识点逻辑、步骤和明确边界】\u003c/strong>\u003c/p>\u003cp>在这个拆页中，我们看到了怎样讲好一个”我是谁“的故事，让自己的信任度提高三倍。怎么样讲好一个”我是谁“的故事呢？\u003c/p>\u003cp>比如你加入了一个500人跑步大群，想做一下自我介绍，那就讲个”我是谁“的故事吧。\u003c/p>\u003cp>你说“大家好！我是xx，我曾经参加过2次全马，1次半马，每天坚持晨跑锻炼，很高兴加入咱们群”。这是一个讲我是谁的故事吗？不是，这是在说流水账，很难在一个500人的大群里引起大家的关注，因为群里比你牛掰的多的去了，你缺乏讲出自己的特色，无法和群里的大咖产生私交感。\u003c/p>\u003cp>再或许你说：大家好！我是xx，我曾经徒步去了拉萨~~~对不起，伙计，您进错群啦！虽然徒步拉萨很牛掰，但这是跑步群啊！往往会让群主或者本群的粉丝产生反感，明显是来踢场子的！缺乏针对性的故事，忘记了进入跑步群的目的是什么，也不是一个好的”我是谁“的故事。\u003c/p>\u003cp>又或者你这样说：大家好！我是xx，我是一名参加过国际马拉松跑步的业余选手，在那次比赛中，我遇到了XX~~（注意，在此我们说的是普通人，对于专业的获得名次的选手，光环自带，无须累述）。这是个好的”我是谁“的故事吗？不一定哦，虽然或许有了独特性，但单一的叙事模式，缺乏对感性大脑的刺激，关注度往往会在不久之后就难产，难以实现持续性的影响力。无法激发感性大脑的故事，也不是好的”我是谁“的故事。\u003c/p>\u003cp>\u003cstrong>how：\u003c/strong>所以，我们从一个”我是谁“的故事的三要素：私交感、目标感、激发感性大脑，归纳出三个步骤：\u003cstrong>1、讲出我的独特之处；2、对比讲述自我经历；3、说明我的目标。\u003c/strong>\u003c/p>\u003cp>在这三步中，最重要的、也是最难的一步是对比讲述自我经历。感谢的大脑，最喜欢关注曲折的经历，去看一下大咖们的演讲，将自己的经历的套路，均是一开始讲自己多么惨，然后通过不一样的经历，自己变得多么强大。对比讲述，就是回想自己曾经的状态，生动的表达出来，然后描述当下不一样的状态，这样的对比效果，最容易启动对方的感谢大脑。\u003c/p>\u003cp>\u003cstrong>举例\u003c/strong>:为了大家更好的理解这三步，我来讲一个”我是谁“的故事：\u003c/p>\u003cp>大家好！我是高力。我是一名靠跑步实现减肥40斤的跑步爱好者\u003cstrong>（独特）\u003c/strong>。两年前，我是一个200斤的大胖子，在一次看到自己的背影照片之后，完全被刺激到了，下定决心通过跑步减肥。通过两年的努力，我已经成功减肥40斤，并且参加过4次半程马拉松线上比赛。\u003cstrong>（对比描述）\u003c/strong>进入我们群，我渴望能向各位跑步前辈请教，提高自己的跑步技能，为挑战全马做准备。\u003cstrong>（目标）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>适用边界：\u003c/strong>\u003c/p>\u003cp>我是谁的故事，不仅仅可以用在群里自我介绍，也可以用在推荐自己的朋友给别人认识，也可以用在面试、演讲等其他场合。\u003c/p>\u003c/p>","interaction":"\u003cp>\u003cstrong>技能点：教学习者编剧本。\u003c/strong>\u003c/p>\u003cp>我的讲解完毕，下面邀请各位伙伴活动一下大脑，参与到下面的互动中。\u003c/p>\u003cp>假设有这样一些场景：小周为了实现2019年某个目标，需要加入一个社群，进入群里，第一步一定是做自我介绍。为了提升自己被关注度，他向你请教。\u003c/p>\u003cp>据此编写一个小剧本。在这个有人物有情节的有发展的故事中，请大家应用刚刚学的讲“我是谁”的故事三步法：\u003cstrong>1、讲述自我独特之处，2、对比讲述自我经历，3、说明目标\u003c/strong>\u003c/p>\u003cp>大家请注意剧本需要包括背景、人物、情节变化（包括：起因、经过、结果）和双方的对话、动作等，几百字即可，摘要写在纸上。记住要把今天学到的方法（\u003cstrong>讲述自我独特之处，对比讲述自我经历，说明目标\u003c/strong>）用在剧本中，现在给大家6分钟时间在小组内进行讨论来编这个小剧本，6分钟后请一组小伙伴起来讲讲他的剧本。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>分享者：张伟\u003c/p>\u003cp>人物：小周\u003c/p>\u003cp>起因：想加入一个写作群，提升自己的写作能力\u003c/p>\u003cp>经过：小周给我打电话，约在周日的下午在咖啡厅聊一下加入社群的事情\u003c/p>\u003cp>对话：\u003c/p>\u003cp>小周：哥，听说你一直在日更，而且有不错的写作群资源，给我推荐一下呗！\u003c/p>\u003cp>我：可以啊，xxx群就不错，你可以加入。\u003c/p>\u003cp>小周：可我一直有个困惑，加入进去之后要进行自我介绍，我之前加入的群，总是写不好这个自我介绍，你能帮我出出主意吗，帮助我提升群里的被关注度？\u003c/p>\u003cp>我：嗯~~首先你可以给自己提三个问题：在写作方面，你有哪些独特之处？\u003c/p>\u003cp>小周：之前坚持写过小故事，每天一篇，坚持写了100天。\u003c/p>\u003cp>我：嗯，能坚持写100天，确实不错。那么，再回答一个问题：在进群之前，你经历了什么？之前的状态是什么样？现在的状态是什么样子的呢？产生对比感，才会给别人留下深刻的印象。\u003c/p>\u003cp>小周：让我想想~~~大学的时候，虽然比较喜欢写作，但总是感觉写不出什么好的文章，经常词穷。但我不想把这个爱好放下，于是一直坚持写日记，现在积累了不少素材。\u003c/p>\u003cp>但就是不知道如何有逻辑的把这些素材组合起来，成为一篇好的文章。\u003c/p>\u003cp>我：嗯，不错的经历。最后一个问题：你加入这个写作群的目的是什么？\u003c/p>\u003cp>小周：向各位写作大神请教，学习写作的逻辑结构。\u003c/p>\u003cp>我：嗯嗯，如果你把这些问题的答案连起来，作为一个自我介绍试试。\u003c/p>\u003cp>结果：\u003c/p>\u003cp>大家好！我是小周。我是有一名故事写作的践行者，曾经坚持写小故事100天。大学的时候，虽然比较喜欢写作，但总是感觉写不出什么好的文章，经常词穷。但我不想把这个爱好放下，于是一直坚持写日记，现在积累了不少素材。很荣幸进入这个群，我想向各位老师学习写作的逻辑结构。\u003c/p>\u003cp>\u003cstrong>【反馈及结语】\u003c/strong>\u003c/p>\u003cp>听了张伟伙伴的分享，我发现大家学习力好强呀，很快的就能把我们今天学的知识应用到实际场景中去，真的非常棒，我们给自己一次掌声，希望今天的拆书给你们一个很好的体验，谢谢大家的积极参与，今晚我的拆书到此结束。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1553526294000,"updated_at":1556071677000,"ria":true},{"id":7092,"topic":"讲好我是谁，赢得好人生！","learn_goal":"掌握通过讲故事进行自我介绍的方法，达到在短期时间内给沟通对象","remark":"“我是谁”这个问题，你有没有认真地问过自己？\r\n在你过往的生活中，面对一群新的朋友、一份新的工作、一次公开的演讲等等，你会如何介绍你自己？\r\n我们都知道第一印象的重要性，很多时候，别人对你的第一印象可能就是从你的自我介绍开始。如何能够讲出一个打动人心，让人记忆深刻的自我介绍？\r\n你可能尝试过一些方法，来告诉别人你是谁，这次我们来学习如何讲一个故事，来展现你独特的魅力。","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"郑远霞","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"开场（30秒）\r\n大家好，我是今天的拆书家郑远霞，今天我带领的是2-3的拆页。首先我想给大家讲一个故事，在二十多年前，湖北的一个小县城有一位小姑娘，并不出众的外表、普普通通的家世让她非常不自信，直到有一次机缘巧合她被选为学校一个大型文艺活动的主持人，从此对公众表达产生了浓厚的兴趣，也萌发了成为一名老师的心愿。长大以后，她在走上讲台的道路上潜心追寻，直到今天她能够有机会来给更多的人分享她的收获。相信大家已经猜到这个人是谁了，对，这个故事的主人公就是我，我是用匠心做课程，用诚心做教育，用真心对客户的亲子教育讲师郑远霞。今天我和大家一起来学习如何讲“我是谁”的故事。选自《故事思维》这本书。\r\n分组（20秒）\r\n为了便于我们的学习和讨论，今天我们分为一个小组，现在我们分成小组坐在一起。\r\n一、学习目标：（10秒）\r\n通过跟随我完成本次拆页的RIA线下学习，大家能够运用讲故事的方法进行自我介绍的方法，达到在短期时间内给沟通对象留下深刻印象，获取信任的目的。\r\n二、图书介绍（1分钟）\r\nF 特征（核心是“书”，用于满足好奇心）：\r\n《故事思维》是世界级故事大师安妮特.西蒙斯真正的奠基之作，这本书详细阐释了六大类故事，讲透了用故事提升个人影响力的方方面面。\r\nA 优势（重点是“比较”，用于建立安全感）：\r\n这本书畅销全球数十年，被誉为在商界推广故事技巧的“圣经”，是微软、美国国家航空航天局一致推崇的故事课程。与同主题其他书籍相比，这本书既体现了扎实的理论基础支持，又以大量的作者亲身经历为依托，非常生动易于操作。\r\nB 利益（强调的是“学习者”的利益，用于引发兴趣）\r\nB1：你有没有遇到过这样的情况？你有机会在一位对你来说很重要的场合介绍你自己，你想让别人留下深刻印象，但是罗列完自己的个人基本信息，然后就没有然后了？学习完这个拆页，你将学会讲一个“我是谁”的故事，提升你自我介绍的效果和影响力。\r\nB2：如果你在人际沟通或是商业展示中，呈现了完美的逻辑体系，却缺乏故事案例的支撑，难以打动人心，讲故事能够为你锦上添花；如果想要是说服对方，却不知从何说起，讲故事能为你雪中送炭。《故事思维》中的6大故事模块，9类讲述技巧，10个情景策略，将全面升级你的故事思维。","ratings_count":1,"texts":[{"id":10486,"quote":"\u003cp>亲身经历比起其他形式的交流更能让别人丁解你是 谁”。客观数抿不足以产生信任。人们最终根据主观证据相信你的意见和你的话。\u003c/p>\u003cp>你可以用亲身经历来说明你不为人知的另一面。除此之外， 你还可以用许多其他方式来告诉人们,你是谁。\u003c/p>\u003cp>你不一定要讲亲身经历。 这本书中不乏神话, 历史故事, 经由朋友复述的故事, 热门时事和寓言, 如果你讲故事的方式确实能够从个人角度揭示一部分 “你是谁”,那么任何形式的故事都能变成一个 “我是谁” 的故事。\u003c/p>\u003cp>当一个人讲了有关特蕾莎修女的故事, 那就表明他懂得感恩和虚心向他人学习。我们可以下结论他并没有囿于小我, 值得信任, 我们可以和他分享我们的故事。如果他选择讲的故事表明他懂得自我牺牲,我们便相信, 他在谋求私利的同时也会考虑别人的利益。当我们看穿故事,知道讲故事的人已经意识到自己的缺点, 没有否认事实、 隐藏真相, 我们确实可以相信他, 与他共同直面棘手的问题, 而不是假装一切“都非常不错”。\u003c/p>\u003cp>我曾经看到过很多领导者用故事来描还目己的不足,心理学家将这个现象称为自我剖析。这个理论的原埋之一是,如果找足够信任你 愿意向你袒露我的缺点, 那么你也应该相信我,向我说明你的不足。倘若一个人能够毫无保留地批判自己, 那么我们就会觉得, 不仅是他的话可以相信, 他的其他方面也值得信任。\u003c/p>\u003cp>例如, 一位经理刚刚上任, 他给员工们开会讲述了这样一个故事: 当他刚走上管理岗位时, 对员工的管理过于严苛,员工们愤而反抗, 指责他独断专行。 当听到新来的老板讲述自己被员工谴责的故事, 你一定会非常震惊。 不过我们也应该知道, 真正的力量并非来源于完美, 而是来自于认识到自己的不足之处。 一个领导敢于正视自身的不足, 也是展示了自己的力量.\u003c/p>","explains":"\u003cp>\u003cstrong>【What】\u003c/strong>我们在生活中经常会遇到要做自我介绍的情况，告诉别人“我是谁”，是你打开人际沟通的第一步。除了常见的个人信息的罗列，这个拆页告诉了我们一个新的思路：用讲故事的方式告诉别人“我是谁”。故事的内容可以是你的亲身经历，也可以是你从别处听来的故事，按照一种特定的模式加工，生活中的很多素材都可以被加工为一个“我是谁”的故事。特别是在人际沟通中，我们要袒露自己的不足的时候，常常会觉得难以开口，承认或争辩都会因为这些问题失去机会。而用讲一个“我是谁”的故事，能够把你的观点直达人心地传递，得到别人的信任与合作。\u003c/p>\u003cp>\u003cstrong>【异议预防】\u003c/strong>你可能会说，这个方法做起来实在是太难了，感觉不知道该怎么讲故事。的确，要讲好一个故事是需要一些积累，通过刻意的练习和复盘，我们讲故事的技能一定可以得到逐步提升的。当我们仅仅是使用一些客观数据来说明我们自己的时候，人们并不会很快地对你产生信任。而通过故事，人们可以在大脑中想象出一个具体的画面，有形象感，可以改变人们的主观认知。相对于讲好故事在人际关系中获得的信任和影响力，这些努力还是很有价值的。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>讲好“我是谁”的故事可以分为3步：\u003c/p>\u003cp>1、&nbsp;确定主题：根据自己这次自我介绍的场合，确定你要讲的这个故事，希望对方了解什么样的你。\u003c/p>\u003cp>（1）明确自己所要面对的场合性质，是商务、社群、社交……等等中哪一种。\u003c/p>\u003cp>（2）想想你想给这个场合中的人留下哪个特质的印象。\u003c/p>\u003cp>2、收集故事：自己的亲身经历需要我们平时留意回顾总结经验，其他的故事需要把功夫用在平常，用心收集这些故事。\u003c/p>\u003cp>（1）根据自己想要表现的特质，回忆一个自己过往相关的经验。\u003c/p>\u003cp>（2）如果自己的经验难以激活，回忆自己看过的故事，或者根据你的关键词搜索一个与之相符的故事。\u003c/p>\u003cp>3、讲述故事：把关于“你是谁”的故事讲述出来。如何呈现故事没有固定的套路，因人而异，而且可以通过刻意练习，让你的讲述技能不断娴熟。\u003c/p>\u003cp>（1）把你收集到的素材根据你被给予的时间进行整理，提炼核心故事结构，比如时间、地点、人物、主要事件等。\u003c/p>\u003cp>（2）把你要表现的特质融入到你的故事呈现中，在事件的发展或感受的描述中，表达出你想要传递的特质。\u003c/p>\u003cp>\u003cstrong>【反面案例】\u003c/strong>我在2010年的时候，被任命去管理一个销售团队，在第一次和团队开会做自我介绍的时候，我是按照传统的方式，把自己的背景信息罗列了一遍，\u003c/p>\u003cp>但是我与团队里的员工相比，背景信息里所显示的经验和业绩都没有特别出彩的地方，实际上这也是我自己觉得最不足的地方，我没有在这里做任何说明，信息陈述一遍就结束了我的自我介绍。结果大家只觉得来了一个年龄不大，工作业绩好像也不怎么样的主管，这让我在管理这个团队的初期遇到了很多的质疑和抵触，我花了很多时间和精力去改变我在他们心目中的形象认识。\u003c/p>\u003cp>\u003cstrong>【正面案例】\u003c/strong>按照讲故事的方式，我在刚刚上任的那个时候，可以给员工讲一个故事：\u003c/p>\u003cp>第一步，搜索我自己能和她们产生共鸣的亲身经历。\u003c/p>\u003cp>第二步，确定主题，希望对方了解主管是来帮助团队获取成功而不是个人出彩的。\u003c/p>\u003cp>第三步，讲述我的故事，当我刚走上销售岗位的时候，虽然自己销售经验并不丰富，但是我自己并没有放弃，而是用一切可以利用的时间来学习和提升自己的能力，同时我的主管在这个过程中给了我很多的鼓励和帮助，让我在很短的时间内就超过了和我同批入职的同事，成为一个综合能力突出的员工。而我的综合能力让我在工作中成功帮助了多名小伙伴突破工作瓶颈，获取优异业绩，这也是让我能够成为主管的最重要的原因之一。\u003c/p>\u003cp>\u003cstrong>【Where（适用边界）】\u003c/strong>并不是任何场合都需要讲一个很复杂的”我是谁”的故事，主要适合于演讲等较正式、给了你足够的时间来让你呈现的场合，在一些特定的场合可能会有相对固定的套路，并不适合用来个人发挥。\u003c/p>","interaction":"\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>【拆书家指令-场景设计】通过我的讲解，相信大家对用讲故事的方式做自我介绍已经有所了解了，现在我们要做一个小练习。\u003c/p>\u003cp>请大家认真听一下要演练的场景：明天你将第一次去到拆书帮参加线下拆书活动，这会是你第一次见到现场的小伙伴，你被告知将有3分钟的时间来做一个自我介绍，那么，现在你要怎样准备好一个“我是谁”的故事，在见面的3分钟之内，让大家对你印象深刻？\u003c/p>\u003cp>【拆书家指令-小组讨论】请在小组内，找到一名小伙伴，来扮演你的听众。你们需要设计出符合这个场景的人物台词，请你运用今天所学的三个步骤：\u003c/p>\u003cp>1、确定主题。\u003c/p>\u003cp>2、收集故事。\u003c/p>\u003cp>3、讲述故事。\u003c/p>\u003cp>现在开始小组内讨论如何做这个自我介绍，时间是2分钟。\u003c/p>\u003cp>好，讨论结束，现在请开始进行小组内的演练，时间是6分钟。\u003c/p>\u003cp>【拆书家指令-角色扮演】好！讨论场结束！我看到大家充分的表现了自己的表演天赋，很期待大家下面的表演！哪一组小伙伴先来呢？\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>犀首的案例：\u003c/p>\u003cp>我会这样来准备自己的“我是谁”的故事：\u003c/p>\u003cp>首先，我要分析，我将去的是拆书帮的线下拆书活动，那在拆书帮是一个和学习书有关的社群，所以我想表现出自己和读书、学习有关的特质，经过这个思考以后，我明确了我的主题是展现自己遇到问题肯钻研的特质。\u003c/p>\u003cp>接着我开始回忆一下自己的亲身经历，发现我在读书和学习上的确有很多困扰，比如我最近就发现，有一些书我虽然读过了，也画了线，有的甚至还做了笔记，但是我完全不记得自己读过这本书，这样让我学习很有挫败感。但是我并没有放过这个问题，而是积极寻找解决办法，也是这样我才会知道了拆书帮，虽然我并不清楚拆书帮是怎么一回事，但是我解决问题的想法很强烈，所以我才会去参加线下活动。\u003c/p>\u003cp>最后，根据我收集的材料，以及给我的时间是3分钟，我可以开始加工“我是谁”的故事，让大家看到一个爱学习、肯钻研的我。\u003c/p>\u003cp>感谢犀首的分享。希望大家在工作和生活中，能够运用到讲故事的方法，让自己的自我介绍变出新高度，今天我的拆书到此结束，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1547918570000,"updated_at":1547918570000,"ria":true},{"id":6781,"topic":"采用讲“我是谁”的故事进行自我介绍","learn_goal":"取得别人的信任，提升影响力","remark":"通过本次拆书活动，学习者在自我介绍时采用讲“我是谁”的故事技巧，取得别人信任，提升影响力。","level":"TF2-2","duration":20,"status":29,"type":0,"chaishujia":{"username":"翔翊","city":"淄博"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>\u003cstrong>学习目标：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;在跟随我完成这次RIA现场学习后，学习者能够讲一个“我是谁”的故事进行自我介绍，取得别人的信任。&nbsp;\u003c/p>\u003cp>\u003cstrong>自我介绍+分组：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;拆动乾坤，赋能你我！今天先讲一个奔四男人的故事：他过两关斩六将成长为一名一级拆书家，千里迢迢来到寒冷的北京度过了温暖的两天烧脑学习生活，成为一名RIA学习力导师；由于被200斤“熊大”般的体型刺激到了，经过两年的时间成为一名跑步健身爱好者。大家好！这个一直在成长路上死磕的男人就是我— 高力！\r\n我是本次拆书活动的带领者，欢迎大家来参加这次拆书活动！为了便于分享学习，我来先分一下组。左手边一组，右手边一组。好，谢谢大家配合！\u003c/p>\u003cp>\u003cstrong>FAB法介绍书籍 ：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;本次活动我要带领大家学习一段关于讲故事的片段，它来自于安妮特 · 西蒙斯的《故事思维》这本&nbsp; 书。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp;\u003c/strong>\u003cstrong> F\u003c/strong>\u003cstrong>：\u003c/strong>本书开创性的提出了商界沟通中的六大类故事以及如何讲好这些故事提升个人在商界的影响力。作者安妮特 · 西蒙斯，把故事思维运用于商业领域的先驱，曾经服务过美国航天总局、美国国税局以及微软公司。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; A\u003c/strong>\u003cstrong>：\u003c/strong>这本书畅销全球数十年，故事思维的理念被美国多家著名机构所认可。书中以大量的作者亲身经历为依托，非常生动易于操作。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; B\u003c/strong>\u003cstrong>：\u003c/strong>你有没有遇到过这样的情况：想让别人留下深刻印象，却只会干巴巴的说完自己叫什么，自己是什么公司/社群的，然后呢，然后就没有然后了！？阅读这本书，你将学会讲故事的技能，打动人心，引人入胜，让别人被你的故事着迷。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;我今天带给大家的这个片段，便是如何讲一个“我是谁”的故事，提升你的影响力，取得别人信任。\u003c/p>","ratings_count":1,"texts":[{"id":10137,"quote":"\u003cp>\u003cstrong>【拆书家指令】\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;请大家先用1分钟时间快速阅读完片段。（最后30秒时）阅读完的小伙伴举手示意一下。\u003c/p>\u003cp>\u003cstrong>【原文片段】拆解片段来自《故事思维》;P.15-16、18\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 一项由《纽约时报》和哥伦比亚广播公司新闻部在1999年进行的民意调查发现，63%的受访者相信与“大多数人”相处，你“一定要小心再小心”；37%相信“大多数人一有机会就想利用你”。如果你认为这代表了你想影响的对象，那么你首先要做的就是，证明你可以被信任。\u003c/p>\u003cp>\u003cstrong>&nbsp; 如何做到呢？\u003c/strong>刚才的那个研究给了我们一个提示：应答者也表示在他们“有交情的人”当中，85%能够“尽力做到公正”。嗯……会是一件很简单的事情吗？让人们了解你是谁，促使他们认为自己与你有“私交”，那么你的信任度必然会提高三倍吗？想象一下我们的口头语：“他人不错，我了解他”或“不是因为我不信任她，我只是不了解她”。\u003c/p>\u003cp>我们不让人们了解我们是谁，他们怎么会信任我们，并且受到我们的影响呢？要是我们不能把说服他人的企图，与回答我们是谁很好地结合，那就无异于与人们心中的评判标准擦肩而过。我们对理性的大脑花费了太多的时间而忽略了感性的大脑。感性的大脑对于被忽视非常敏感。感性的大脑更要重视、防患于未然，虽然毫无根据，但是它更能影响人们的结论。\u003c/p>\u003cp>…………\u003c/p>\u003cp>&nbsp; 亲身经历比起其他形式的交流更能让别人了解你是“谁”。客观数据不足以产生信任。人们最终根据主观证据相信你的意见和你的话。\u003c/p>\u003cp>&nbsp; 你可以用亲身经历来说明你不为人知的另一面。除此之外，你还可以用许多其他方式来告诉人们，你是谁。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;你不一定要讲亲身经历。这本书中不乏神话、历史故事，经由朋友复述的故事，热门时事和寓言，如果你讲故事的方式确实能够从个人角度揭示一部分“你是谁”，那么任何形式的故事都能变成一个“我是谁”的故事。\u003c/p>","explains":"\u003cp>\u003cstrong>【拆书家指令】\u003c/strong>\u003c/p>\u003cp>&nbsp; 时间到，大家看完这个片段应该对“我是谁”的故事有所了解了吧！下面我来说一下我对这个片段的解读。\u003c/p>\u003cp>\u003cstrong>【I：用自己的语言重述信息】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; What\u003c/strong>\u003cstrong>：\u003c/strong>通过1999年的一个民意调查，可以发现100%的人对“大多数人”存有戒心，很难做到相互信任。原因是什么呢？如果你是“大多数人”之一，产生不信任的原因是人们不了解你。大家都不知道你是谁，怎么信任你呢？\u003c/p>\u003cp>\u003cstrong>&nbsp; Why\u003c/strong>\u003cstrong>：\u003c/strong>“我是谁”的故事，具有真情实感的讲述一个关于自己的故事，或是自己的亲身经历，或是能够体现自己与众不同的其他故事，从故事中，在人们的大脑中画出你的画像，更加容易产生对这个形象的认可，从而取得信任。\u003c/p>\u003cp>\u003cstrong>&nbsp; 举个例子：\u003c/strong>当一个人讲了有关于特蕾莎修女的故事，人们感性的思维就会判断，这个人对特丽莎这么了解，他本身估计也是这样的人。那么一个懂得感恩和虚心学习的形象，呈现在人们的大脑中，人们也更加会相信你就是这样的人。\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【预防可能的异议】\u003c/strong>\u003c/p>\u003cp>&nbsp; 或许你可能会认为，介绍自己的时候讲一个故事也太麻烦啦，简单介绍一下自己不就好了吗？\u003c/p>\u003cp>\u003cstrong>&nbsp; Where\u003c/strong>\u003cstrong>：\u003c/strong>是的，我们通常认为的介绍“我是谁”，仅仅限于姓名、性别、职务，从履历表上巴拉下来的数据信息，这能让别人了解你吗？不能！人们对一个人的看法，往往会带着有色眼镜来看待，凭着以往的经验判别眼前的人是否值得信赖，这种天生的防备心态，仅仅靠履历表的数据信息，无法打破人们的预防心态，反而加深了他们理性的思考：这些信息是真的吗？你无法得到对方真正的信任。而如果讲述一下亲身经历呢，一种形象代替了人们的经验判断，产生了新的经验，那么人们将更容易信任你。\u003c/p>\u003cp>\u003cstrong>&nbsp; How\u003c/strong>\u003cstrong>：\u003c/strong>怎样讲好“我是谁”的故事呢？可分为三步。\u003c/p>\u003cp>&nbsp; 1、 收集故事：自己的亲身经历一般随手拿来，其他的故事需要把功夫用在平常，收集这些故事，判断这些故事可以帮助自己树立什么样的形象。\u003c/p>\u003cp>&nbsp; 2、确定目标：每次讲关于“我是谁”的故事之前，一定确定好目标是希望对方了解什么样的你，有助于提升你的影响力。\u003c/p>\u003cp>&nbsp; 3、生动表述：讲故事不是讲案例，需要生动的语言表达，有趣、有料、有结果，最终才能打动对方。\u003c/p>\u003cp>&nbsp; 今天的开场自我介绍，我讲了三个“我是谁”的故事，大家感觉如何呢？\u003c/p>","interaction":"\u003cp>\u003cstrong>【拆书家指令】\u003c/strong>\u003c/p>\u003cp>&nbsp; 好了，通过我的讲解，相信大家对怎样讲述“我是谁”的故事，有所了解了。下面请大家发挥自己感性的大脑，参加到我们的互动中来。\u003c/p>\u003cp>\u003cstrong>【分步催化1】\u003c/strong>\u003c/p>\u003cp>&nbsp; 参加年会、做一次报告、产品展示、公开课、经验交流......在你的工作和生活中，会遇到在这些情境下进行自我介绍吗？\u003c/p>\u003cp>&nbsp; 下面请大家思考并想出具体情景，在小组里进行讨论，时间2分钟，之后我会邀请1-2名伙伴分享一下。注意，只需要设想一个在什么样的场景下，你需要进行一次自我介绍。场景的要素包括时间、地点、面向人群、主题等内容。\u003c/p>\u003cp>\u003cstrong>【拆书家指令】\u003c/strong>\u003c/p>\u003cp>&nbsp; 时间到了，我听到每个人的场景都不一样，而且这个场景是不是已经在你脑海里形成一个图像了呢？下面我邀请xx伙伴来分享一下他的场景。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>&nbsp; 芒果（张亚军）\u003c/p>\u003cp>&nbsp; 时间：下个周日的晚上\u003c/p>\u003cp>&nbsp; 地点：世纪商务大厦\u003c/p>\u003cp>&nbsp; 面向人群：拆书帮淄博筹备分舵的伙伴们\u003c/p>\u003cp>&nbsp; 主题：介绍一下我的名字的来源\u003c/p>\u003cp>\u003cstrong>【分步催化2】\u003c/strong>\u003c/p>\u003cp>&nbsp; 好的，谢谢芒果伙伴的分享。下面请大家采用讲述“我是谁”的故事对自我介绍进行规划应用，在小组内分享，4分钟时间，然后我们邀请1-2位小伙伴来分享一下。\u003c/p>\u003cp>\u003cstrong>【拆书家指令】\u003c/strong>&nbsp;\u003c/p>\u003cp>&nbsp; 好了，大家分享完毕。谁来分享一下呢？好的，大家欢迎芒果伙伴来分享他的规划应用。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>&nbsp;芒果（张亚军）&nbsp;\u003c/p>\u003cp>&nbsp;故事：分享一个关于自己出生的故事\u003c/p>\u003cp>&nbsp;目标：让大家了解自己偏男性姓名的来源\u003c/p>\u003cp>&nbsp; 生动表达：我出生在军人世家。当时怀我的时候，不符合政策，爸妈费了好多劲，把我的出生日期提前了一年。由于当时正在召开亚运会，而且我家的男人都是军人，大家凑在一起一商量，那这个闺女就叫：张亚军吧！\u003c/p>\u003cp>&nbsp; 非常感谢小伙伴的分享。\u003cstrong>看来大家已经能够使用讲述“我是谁”的故事技巧了，\u003c/strong>希望大家能主动应用今天学到的方法，在不同的场合里更加有效的介绍自己，取得别人的信任，不断提升自己的影响力。我今天的拆书到此结束，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1544970750000,"updated_at":1544971251000,"ria":true},{"id":6701,"topic":"讲讲好故事，好好讲故事——如何用故事收服人心","learn_goal":"学习者通过学习后，可以运用故事思维讲好故事，好好讲故事","remark":"","level":"TF3-3","duration":50,"status":29,"type":0,"chaishujia":{"username":"吴佳音","city":"厦门"},"club":{"name":"厦门鹭岛抚琴分舵","city":"厦门"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;1.开场 \r\n大家好，我叫佳音，用三个标签来介绍自己。\r\n专业——心理学：曾经主修的学业。\r\n职业——培训师：现在的谋生之道。\r\n副业——拆书家：未来的成长之路。\r\n2.介绍图书 \r\n【事件】又是一年的年终岁末，又是一年的总结回顾。想想去年的工作总结时，我在那侃侃而谈，而听众呢，也在侃侃而谈。\r\n【提问】大家是否有过这种你讲的很累，听众听得也很累的情况呢？\r\n【影响】大家都累，最后就是没有达到预期的目标，甚至是颗粒无收。\r\n【解决】有句话叫：道理只能赢得辩论，故事可以收服人心。《故事思维》就是告诉大家如何通过故事收服听众的心。\r\n【A1】可能有伙伴会说，讲故事谁不会啊，我可是听《狼来了》、《皇帝的新装》这些伊索寓言长大的一辈，讲个故事还不是件容易的事情。真的是这样吗？接下来请大家做一个简单的测试。\r\n请大家仔细阅读表格中描述的每一句话，并与自己平时的做法进行对照，然后给自己打分，1分代表完全不符合，6分代表完全符合。\r\n请不要犹豫,看懂题意后马上做答并计分。&nbsp;\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>问题\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>1\u003c/strong>\u003c/p>\u003cp>\u003cstrong>完全\u003c/strong>\u003c/p>\u003cp>\u003cstrong>不符合\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>2\u003c/strong>\u003c/p>\u003cp>\u003cstrong>不符合\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>3\u003c/strong>\u003c/p>\u003cp>\u003cstrong>略不\u003c/strong>\u003c/p>\u003cp>\u003cstrong>符合\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>4\u003c/strong>\u003c/p>\u003cp>\u003cstrong>略微\u003c/strong>\u003c/p>\u003cp>\u003cstrong>符合\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>5\u003c/strong>\u003c/p>\u003cp>\u003cstrong>符合\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>6\u003c/strong>\u003c/p>\u003cp>\u003cstrong>完全\u003c/strong>\u003c/p>\u003cp>\u003cstrong>符合\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>1\u003c/strong>\u003cstrong>、当我讲解晦涩概念的时候，我会使用案例做比喻进行讲解。\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>、当我说服他人的时候，我会使用成功和失败的故事进行对比说明。\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>、当我需要使用故事的时候，我可以快速找到合适的素材。\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>4\u003c/strong>\u003cstrong>、当我讲故事的时候，可以吸引所有听众的注意力。\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>5\u003c/strong>\u003cstrong>、当我在现场遇到听众（学员、同事等）挑战的时候，会使用学员的案例引发学员思考并解决问题。\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>6\u003c/strong>\u003cstrong>、我会使用讲故事的方法让听众接收信息和技能，并在未来将技能付诸行动。\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>【I】大家可以计算下，你们所获得的分值。\r\n若分值是26以上，你拥有极好的故事思维。\r\n若分值是14—26（含），你有时候会使用故事思维，但仍需要加强，提升使用频次。\r\n若分值是14（含）以下，你很少使用故事思维，需要多加学习，并付诸行动。\r\n今天将会跟大家分享《故事思维》中的两个片段，分别是：不要让听众觉得无趣、引诱你的听众。接下来先跟大家分享第一个片段：不要让听众觉得无趣，接下来是阅读时间，请阅读完的伙伴举手示意我一下。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":10046,"quote":"\u003cp>阅读片段1 \u003c/p>\u003cp>\u003cstrong>《故事思维》P207\u003c/strong>\u003cstrong>——208\u003c/strong>\u003c/p>\u003cp>\u003cstrong>不要让听众觉得无趣\u003c/strong>\u003c/p>\u003cp>作为讲故事者，最大的失败莫过于使听众觉得厌烦。故事太长或者主题不集中都会让听众厌烦。讲故事时不考虑听众的情况，只站在自己的立场讲故事，或者因为各种担忧和害怕而不敢尽情发挥想象力，都会让听众觉得厌烦。没人愿意使人生厌，也没人愿意别人让我们生厌。许多人对自己评估不准确，因为担忧自己的故事会使人厌烦而不敢讲。\u003c/p>\u003cp>只要是人，就会有故事可讲——可讲的故事可能还不少呢。如何让听众觉得你的故事有意思?其实并不难，了解听众的趣味所在，讲讲你经历过的趣事。最简单的办法是通过人们之间的共性交流(怎么去“做”在下面讲)。不过，要是你怀疑听众厌烦了，也有具体的办法可以帮助你。\u003c/p>\u003cp>比如，有位年轻的工程师，在培训课上问我:“如果有人讲话的时候，发现自己可能讲得漫无边际、东拉西扯，他该做什么？——比如，做报告的时候，发现大家都厌烦了，他该怎么才能扭转局面。”他提问的方式，让我肯定了两点:第一，他跟我说的那个人不是某个人，而是他自己；第二，他察觉自己使人厌烦后开始焦虑，讲话更加没有头绪了。\u003c/p>","explains":"\u003cp>【学习目标】在跟随我完成本次的RIA现场学习后，学习者能够在面对听众觉得他讲话无趣的情况下（澄清），通过具体、停下、坦诚的方法（行为），让学员有兴趣继续听他讲话（界定）。\u003c/p>\u003cp>片段中这位年轻的工程师所遇到的问题，也是我们经常遇到的情况。可能是一场培训、可能是一个会议、可能是朋友间的闲聊八卦……\u003c/p>\u003cp>【互动】\u003c/p>\u003cp>问：如果你是听众，觉得别人讲的东西很无趣，你会怎么做呢？\u003c/p>\u003cp>答：开小差、玩手机、去上厕所、找其他人聊天、找借口开溜、故意找茬、……\u003c/p>\u003cp>问：如果你是讲话的人，当你发现你的听众开始出现上述的各种行为时，你会有什么反应呢？\u003c/p>\u003cp>答：会发慌、语速会加快、音调会提高、会觉得很热、很生气……\u003c/p>\u003cp>【HOW】无论是讲的人，还是听的人，都不希望出现无趣的情况，但是它却总是出现在不该出现的地方。当听众觉得你的讲话无趣时，有什么方法可以唤起他们的兴趣呢？ \u003c/p>\u003cp>一是具体，讲具体的东西。故事之所以称之为故事，是因为它有六要素：时间、地点、人物、起因、经过、结果。也就是说故事要有细节、有情节、有画面……你的讲述将会更加生动有趣。\u003c/p>\u003cp>二是停下，特别是当你讲述的内容已经偏离主题时主动停下。可能有人会说，停下来就冷场了，这样好吗？从原有的嘈杂声中突然安静下来，也是让听众集中注意力的一种方法。\u003c/p>\u003cp>三是坦诚，特别是当你所讲述的主题与听众的观念相抵触，学员提出挑战时。不妨坦诚一些。引导学员思考并解决问题，这也不失为一种好方法。\u003c/p>\u003cp>比如今年10月份公司做校招，12日去一家中专学校。当时是在学校里室内体育馆举办的，我记得当时公司招聘专员小姚上场讲了不到3分钟，台下就已经吵成一锅粥，最后她还是坚持把准备的内容讲完了。总共大概讲了7、8分钟，后面讲得飞快，差不多就是把PPT上的内容念完。\u003c/p>\u003cp>那天总共有两家公司，除了我们还有电信的，招聘岗位相近、薪酬和绩效也相当。但他们讲的还行，底下有点声响，但总体还不错。演讲结束后，现场咨询时非常尴尬，我们这就没人，而另外一家就陆续有几个咨询的学生，而且有些学生会主动过去拿宣传单页。最后现场没收到简历，公司宣传单页也发了不到十份。之后跟校方协商，将宣传单页再发到专业对口的班级。到现在一个多月，通过电子邮箱收到的简历就三份。\u003c/p>\u003cp>一旦听众觉得无趣，就会自动屏蔽你所提供的信息，这就是这场校招失败的一个主要原因。如果现场存在如此失控的情况，可以尝试先停下，选择一个重要的信息具体化。比如PPT中有关晋升通道，可以虚拟一位员工，如何做，做出什么成果，获得什么机会，并在多长时间内达到某一岗位等等，也就是说讲内容具体化。\u003c/p>\u003cp>【异议预防】在这个校招的场合可能无法使用坦诚的方法，但可以尝试具体、停下两种方法。三个方法可以独立使用，亦可同时使用，并无先后之分。当出现听众觉得你的讲话无趣时，不妨尝试下这三个方法。\u003c/p>\u003cp>【适用边界】只要这听众对你而言是重要的，可以使用这三个方法。比如，公司的领导、同事、下级，只有获得他们的支持，工作上更容易获得成就；你的家人、朋友，只有获得他们的理解，你的幸福感会更加爆棚。只要这个场合对你而言是有特殊意义的，也可以使用这两个方法。比如，你的年终述职、给下属传达工作、亲子共读……\u003c/p>","interaction":"\u003cp>&nbsp;A2 催化学习者应用 \u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>以上就是我对这个拆页的讲解。在一些重要的考试，如中考、高考等，在正式考试前，会有各种模拟考。这就是为了让考生能在正式考试中发挥出正常的水准。\u003c/p>\u003cp>为了让大家在今后能更好的运用今天所学到的方法，不让听众觉得无趣。接下来我们将做一个分组演练，分为两组进行讨论。\u003c/p>\u003cp>请大家设想下是否有过这样的经历，如你准备的会议内容，参会者却觉得无趣；你准备的培训内容，参训者却觉得无趣；你八卦着羽泉组合的陈羽凡吸毒被抓的事情，同事却觉得无趣……\u003c/p>\u003cp>只要这听众对你而言是重要的，或者这个场合对你而言是有特殊意义的都可以。面对听众觉得你的讲话无趣的情况，你将如何使用今天学到的方法进行突破呢？\u003c/p>\u003cp>请组内讨论下，编一段小故事，几百字即可，设计出任务、情节变化和当时双方的对话、动作等。将摘要写在一张纸上，时间五分钟。五分钟后我们将一位伙伴站起来讲讲他的剧本。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>小剧本\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>主题\u003c/p>\u003c/td>\u003ctd>\u003cp>小朋友觉得我讲故事很无趣\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>事件内容\u003c/p>\u003c/td>\u003ctd>\u003cp>我给小朋友讲故事，哥哥和弟弟总是听一会就走了。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>人物角色\u003c/p>\u003c/td>\u003ctd>\u003cp>角色A：曹志文&nbsp;&nbsp; 角色B：佳山\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>对白\u003c/p>\u003c/td>\u003ctd>\u003cp>角色A：他们走了以后，你会怎么做呢？有什么方法可以引起他们的注意呢？\u003cbr> &nbsp; 角色B：他们走了，没有听众了，就不讲了。有时候，哥哥发现爸爸不讲了，就会过来说，爸爸你继续讲、继续讲……（使用方法“停下”，可以达到吸引注意力的目的。）\u003cbr> &nbsp; 角色A： 为什么他们会走开呢？有没有什么方法可以让他们一直听你讲故事，不走开？\u003cbr> &nbsp; 角色B：可能是我讲故事太平淡了，就是跟着书里写的内容逐字讲完。我应该根据不同的角色，相对应的使用不同的声音、动作……这样讲故事就会比较生动，他们应该会比较喜欢。（使用方法“具体”，让听众觉得有趣。）\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>刚刚分享的主题是不要让听众觉得无趣，具体、停下、坦诚或许可以救你的场，但是我们更希望能做好充分的准备，引诱你的听众。\u003cbr>\u003c/p>\u003cp>比如那场失败的校招，如果准备工作更充分些，效果可能会完全不同。如何做充分的准备呢？接下来跟大家分享的就是这样一个片段——引诱你的听众。接下来是阅读时间，请阅读完的伙伴举手示意我一下。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":10047,"quote":"\u003cp>&nbsp;阅读片段2 \u003c/p>\u003cp>\u003cstrong>《故事思维》P213\u003c/strong>\u003cstrong>——215\u003c/strong>\u003c/p>\u003cp>\u003cstrong>引诱你的听众\u003c/strong>\u003c/p>\u003cp>要想讲听众感兴趣的故事，内容就要与听众相关。讲讲他们的希望、梦想、烦恼或者不为人知的担忧。必须确保它们是你自己了解的内容，而且要讲得具体。泛泛而谈会使人厌烦，只有把故事讲得生动具体才能打动听众。\u003c/p>\u003cp>讲故事的时候顾忌太多、谨言慎行或者故事粗浅、没有深度，或者为了政治正确而讲废话，都会让听众觉得无趣。带着热情讲，讲原汁原味的人间悲喜故事才能抓住听众的注意力。\u003c/p>\u003cp>要确保自己一直讲有趣的故事，最好的办法就是保持好奇心。\u003c/p>\u003cp>安娜·埃莉诺·罗斯福曾在给人的信中表示，她相信靠“诸如此类”这种泛泛而谈的话敷衍听众，对任何人都不是难事，但她怀疑“这些人是否真的还有好奇心”。拥有好奇心是确保你能吸引别人注意力的最关键的东西。\u003c/p>\u003cp>“自己感兴趣”和“要费力去理解”之间是有很大区别的。前者让人更主动，渴望发现意外的事物和探索未知的领域，后者意味着不积极思考，甚至对要费脑力才能理解事物有抵触情绪。\u003c/p>\u003cp>讲自己感兴趣的故事才会引起听众的兴趣，你必须找到自己感兴趣的东西。最能引起听众兴趣的故事往往来自好奇心的探索。我去企业演讲时，都会讲到“卫生间吐槽”的故事。\u003c/p>\u003cp>故事是这样的，有两个人参加完一个重要会议后去了卫生间，在那里透过隔间门与地板间的缝隙确认没有其他人后，才跟对方讲了自己的真实想法:“这破会议，真是浪费时间。”这个小故事想要说的是，人们在会议上不说实话，会后在私下里讲得更真实。这种故事会让听众联想到自己的亲身经历从而引发共鸣。是好奇心让我注意到这种现象，收获了这样一个好故事。好奇心可以帮助我们发现吸引人们兴趣的故事，因为这些故事来自他们的生活体验。\u003c/p>\u003cp>一直保持好奇心，可以帮助你发现许多故事，这些故事表面看起来没什么关联，可是会在你需要的时候奇迹般地出现。比如来自人们陌生的地方，比如新奇的思想领域的怪诞故事，都会引起人们注意。\u003c/p>\u003cp>讲故事的时候，像这样开头:“我的一个朋友以前是印度教的传教者，他说他住在贫民窟的时候……”又或者这样开头:“我曾遇见过这样一个的家伙，他开过货车、卖过毒品，还当过耶和华见证人(译者注:基督教派的一种)的传道者。”这样的开头保证能立马吸引听众的注意力。\u003c/p>\u003cp>有时候，在故事里加点怪诞的细节可以引起人们的注意。\u003c/p>\u003cp>我以前的一位同事经常讲一个大家都熟悉的故事，说在天堂和地狱各有一帮人，都围坐在一个很大的桌子周围，桌子上放着丰盛的美食，他们每个人手上都拿着约2米长的叉子。最后，地狱里的那帮人饿死了，因为他们不懂合作，拿的叉子太长，食物送不到嘴里。而天堂里的那帮人吃得津津有味，因为他们互相帮忙，相互喂食。\u003c/p>\u003cp>这是一个关于协作的故事。可我的这位同事讲起来的时候不停地笑，笑得像个孩子，引人发笑，能刺激听众的感官和情绪。这样更容易引起人们的回忆，让故事更加有趣。\u003c/p>\u003cp>如果讲故事的时候老是“直奔主题”，你可能会发现只有自己在讲，没人在听。\u003c/p>\u003cp>让你的故事生动起来，运用各种手段调动听众的听觉、视觉和嗅觉，把故事讲得有声有色、引人入胜。这样才能向听众传达你想表达的主题。\u003c/p>","explains":"\u003cp>【学习目标】在跟随我完成本次的RIA现场学习后，学习者能够在前期准备内容的时候（澄清），通过经历、收集、想象的方法（行为），主动收集并充实素材库（界定）。同时，通过前期主动的素材选择、素材使用方法的选择（行为），从而达到“引诱听众”的目的（界定）。\u003c/p>\u003cp>片段中提到了“要确保自己一直讲有趣的故事，最好的办法就是保持好奇心。”保有好奇心，才会发现有趣的故事。这说来好像很容易，我们来看看这几种情况。\u003c/p>\u003cp>【互动+概念讲解】\u003c/p>\u003cp>问：作为一个上班族，每天都是朝九晚五的上班，挤公交车；如果是开车，路上会堵车。有一天，当你发现街上人特别多，沿街店铺里的人都跑到街上来，你会好奇？\u003c/p>\u003cp>答：会，是不是又地震了。\u003c/p>\u003cp>问：这好奇心从何而来呢？是哪种类型的事物引发的好奇心呢？\u003c/p>\u003cp>答：特别、奇特、不一样……\u003c/p>\u003cp>总结：对，这是因为由于奇特的事情导致的惊奇，这种惊奇，是因为在日常生活中，有些不同于往日的、特别的事情出现，会引起你的关注，但是你没有进一步产生兴趣？\u003c/p>\u003cp>问：大家回想下，什么年龄层的人好奇心最强？\u003c/p>\u003cp>答：小朋友\u003c/p>\u003cp>总结：小朋友的好奇心非常强，只要是没见过的东西，他们都很好奇。但随着年龄的增长，很多人的好奇心慢慢减弱了。如果仅是对新奇的事物保有好奇心，那么随着年龄的增长，阅历的增加，好奇心将会慢慢减弱，甚至消失。因此，帮助我们发现有趣的故事的好奇心不能仅停留于新奇事物上。很多平凡的事情，只要我们保持兴趣，拥有不一样的思考和想象，一样也是可以产生奇妙的反应。\u003c/p>\u003cp>比如，著名科学家牛顿发现万有引力的例子。牛顿对一个苹果从树下掉落，而产生好奇，不断的观察和思考想象，为什么苹果掉落时不能往上跑，而是往下掉？对此产生专研的兴趣，最终发现了万有引力。\u003c/p>\u003cp>问：有伙伴会说：好奇害死猫。真的是这样吗？害死猫的，真的是好奇吗？\u003c/p>\u003cp>答：不一定。\u003c/p>\u003cp>总结：害死猫的应该是猎奇，而非好奇。因为好奇是有底线的，不能触及个人隐私、商业机密。\u003c/p>\u003cp>保有好奇心不但要对新、奇、怪的事物有好奇心，而且要用发现的眼睛在平凡、平常、平日的事物中去发现不平凡的地方。\u003c/p>\u003cp>【HOW】如何才能让我们拥有一双发现的眼睛去发现？如何累积故事的素材呢？……生活不缺少故事，缺少的是发现的眼睛。这里给大家提供三个渠道：经历、搜集、想象。\u003c/p>\u003cp>一是经历\u003c/p>\u003cp>影响至深、重要时刻：这些事情往往是大家令记忆深刻的，升学、恋爱、结婚、升职……这些美好的时刻，落榜、失恋、失业……这些失落的时刻，这都是你的重要时刻，也往往对你有很大的影响。无论事情是美好还是失落不分大小，只要能令你深思，能让你从中获得经验教训，就是影响至深，就是你的重要时刻。\u003c/p>\u003cp>反复出现：这往往是被忽略的事情，因为反复出现，习以为常，似乎没有好奇可言。但这反而是我们需要悉心研究的地方，何时会出现？为什么会反复？……比如，小朋友在超市里要求买饼干糖果时，当家长拒绝时，小朋友会哭，会闹。但是有些小朋友是基于伤心而哭，而有些小朋友是基于愤怒而哭，一样是哭却是基于完全不同的情绪，而结果也完全不同。伤心的小朋友容易安抚，而愤怒的小朋友则难以平复。所以反复出现的事情更值得深究。\u003c/p>\u003cp>暴露弱点：还记得你上次哭是什么时候？是因为什么事情？是高兴的哭还是伤心的哭？……回想下你有没有过想钻到桌子底下藏起来的时刻；回忆你人生中令人痛苦的危机；回想你曾犯过的最严重的错误……很多人不愿意去触碰这些，更不愿意去谈到这些。但弱点，往往是最能打动人心的时刻。\u003c/p>\u003cp>二是搜集\u003c/p>\u003cp>记住你听到过的貌似会有用的故事；记住改变你的那个故事；询问影响其他人的故事是什么……搜集的关键是用心，保留住他人的精彩故事。\u003c/p>\u003cp>三是想象\u003c/p>\u003cp>寻找未来的经验，将你每天幻想的“它会怎样”，加上现实生活中的人物拓展成一个完整的故事（人们喜欢身临其境，被代入故事中）；将你的担忧发展为成熟的故事，包含所有潜在负面结果（它们会如何结束、会影响到谁……）。想象的关键是寻找未来的各种可能。\u003c/p>","interaction":"\u003cp>A3 促动参与 \u003c/p>\u003cp>【提出问题】\u003c/p>\u003cp>问：刚才分享的是可以通过经历、收集、想象三种渠道，主动去收集素材。这样做能达到什么目的呢？\u003c/p>\u003cp>答：充实自己的素材库、丰富自己演讲的内容……\u003c/p>\u003cp>【明确问题】\u003c/p>\u003cp>问：收集了充足、全面的素材，是否就能达到目的——“引诱你的听众”？\u003c/p>\u003cp>答：不能、不一定……\u003c/p>\u003cp>问：为什么呢\u003c/p>\u003cp>答：有很多影响因素，还要能引起她的注意、能让对方感同身受……\u003c/p>\u003cp>总结：大家都很有兴趣来探讨这个问题，接下来就是讨论时间。继续按刚才的分组进行讨论，讨论时间是3分钟。\u003c/p>\u003cp>【引导分组讨论问题本质】\u003c/p>\u003cp>影响因素很多，接下来请大家讨论，记录下这些因素，并做排序。如果要达到“引诱听众”的目的，除了有充足、全面的素材，还需要做哪些准备呢？\u003c/p>\u003cp>3分钟讨论结束后，将请伙伴按顺序来分享，从影响最大到影响最小的依次分享。\u003c/p>\u003cp>【学员分享】\u003c/p>\u003cp>A组：\u003c/p>\u003cp>第一是共鸣：说的内容是对方所需要的，能引起他的共鸣。\u003c/p>\u003cp>第二是专业水准：讲的人必须是个专业人士，讲的内容必须要专业。\u003c/p>\u003cp>第三是气场：有些人（的气场）就可以镇住半场的人。\u003c/p>\u003cp>第四是声音：良好的视听感，可以吸引三分之一的人。\u003c/p>\u003cp>第五是环境：现场的环境，甚至是温度都很重要。\u003c/p>\u003cp>B组：\u003c/p>\u003cp>第一是排除对方禁忌：比如宗教信仰、地域性等。\u003c/p>\u003cp>第二是需求：了解对方的真实需求。\u003c/p>\u003cp>第三是合适的素材：针对对方的需求，选择合适的素材。\u003c/p>\u003cp>第四是表达：生动的、具象化的表达才能打动对方。\u003c/p>\u003cp>第五是时机：千万不要在对方愤怒或伤心的时候讲，她是听不下去的。\u003c/p>\u003cp>第六是环境：最好是在利于双方的环境中。\u003c/p>\u003cp>总结：谢谢两组伙伴的精彩分享，我做下总结。\u003c/p>\u003cp>刚才的分享中，大家均有提到作为主讲人，无论是做培训还是主持会议，都需要专业的水准和表达，并且需要选择适合的素材，营造良好的现场氛围。这就是我们今天的主题——好好讲故事，也就是要怎么把故事讲好。\u003c/p>\u003cp>同时，影响因素还有：选什么素材、学员的需求、环境……这就是我们今天的另一个主题——讲讲好故事，也就是要选个好故事。这就是我们今天的主题——用故事收服人心，但要做到收服人心就需要做到：讲讲好故事，好好讲故事。\u003c/p>\u003cp>刚才大家的分享中，A组的伙伴总结出的影响因素主要是现场氛围的营造等等，所以接下来A组伙伴讨论的主题是：好好讲故事，即如何将故事讲得吸引人。\u003c/p>\u003cp>B组的伙伴总结出的影响因素主要是如何选素材、学员的需求等，所以接下来B组伙伴讨论的主题是：讲讲好故事，即如何从素材库中选出适合的。\u003c/p>\u003cp>【引导分组讨论解决方案】\u003c/p>\u003cp>刚才大家分享了很多的影响因素，如何将这些影响因素的影响程度降到最低呢？有什么方法和建议吗？接下来是分组讨论的时间，讨论的时间是5分钟，最后我们将请伙伴上来分享他们的成果。\u003c/p>\u003cp>再重申下，我们要讨论的是使用故事思维来“引诱你的听众”，从而达到收服人心的目的。接下来，请两组的伙伴针对各自的主题进行讨论。时间关系，可以选择仅针对某一影响因素进行讨论并提供多种方法，也可以每个影响因素均提供一个方法。\u003c/p>\u003cp>【学员分享——讲解成果】\u003c/p>\u003cp>A组：\u003c/p>\u003cp>我们主要是针对共鸣和专业水准进行讨论，并给出一些方法和建议。\u003c/p>\u003cp>第一是共鸣\u003c/p>\u003cp>1、做调研表，前期准备好。\u003c/p>\u003cp>2、找同龄人了解他们的（需求），了解需求。\u003c/p>\u003cp>3、同理心，比如想想当年我是他们这个年纪的时候是怎么想的。\u003c/p>\u003cp>4、互动，抓住关键点进行互动，引发共鸣。\u003c/p>\u003cp>第二是专业水准： \u003c/p>\u003cp>1、熟练度\u003c/p>\u003cp>2、复盘，学完后使用，用后在总结。就是反复学以致用。\u003c/p>\u003cp>3、量的积累，将这个领域里的内容都收集完整，\u003c/p>\u003cp>4、需要跟这个领域的专业人士做朋友。\u003c/p>\u003cp>B组：\u003c/p>\u003cp>我们主要是针对需求这个影响因素做讨论，并总结出这几个方法。\u003c/p>\u003cp>1、问卷法：使用量表进行评估\u003c/p>\u003cp>2、现场的提问：设计一些问题现场提问\u003c/p>\u003cp>3、可以在同类型的人群中进行抽样调查\u003c/p>\u003cp>4、收集素材时，对素材进行分类并做好标签，就可以快速从素材库中选择所需要的材料，做到信手拈来。\u003c/p>\u003cp>【总结——拆书家反馈】\u003c/p>\u003cp>非常感谢大家的分享！\u003c/p>\u003cp>从讲讲好故事，也就是素材选择的角度上，不仅需要完整、充实的素材库，而且需要事前充分了解听众的需求、了解他们的状态……这些充分的准备，将会选出最适合他们的故事素材，也会让你的状态更自信，演绎也会更精彩。\u003c/p>\u003cp>从好好讲故事，也就是素材使用的角度上，最重要的是尊重。尊重你的听众，拥有专业的水准，才能引发听众的共鸣。\u003c/p>\u003cp>&nbsp;【A2 催化学习者应用：布置任务——事后复盘】\u003c/p>\u003cp>问：请问下大家，最近一次讲故事是什么时候？是否有引诱到你的听众？\u003c/p>\u003cp>答：有/没有\u003c/p>\u003cp>今天的课程结束后，希望大家能认真做个复盘，总结下成功的经验也分析下失败的原因。同时，规划下未来将如何使用故事思维。\u003c/p>\u003cp>【记录学员洪传霖的分享】\u003c/p>\u003cp>今晚参加定级分享回来，复盘的时候又思考了佳音提出的“把影响故事讲述的因素按影响力从大到小排”的问题。几个培训机构的老师倾向于从讲述的技巧（声音、气场……）来排序，几个拆书帮的小伙伴倾向于从对象的需求的角度来排序（可能跟拆书帮强调以学习者为中心有关）。作为讲故事的门外汉，我觉得，可能态度才是最重要的。很期待以后自己做分享的时候能有一种充满分享欲望、充分尊重听众、想尽一切办法为了真正了解、帮助或促进对方的心态。当然，练习具体的技巧可以提高信息传递的效率还是很有必要的。\u003c/p>\u003cp>洪传霖规划在未来如何寻找故事\u003c/p>\u003cp>【结尾】\u003c/p>\u003cp>今天分享了两个片段，第一个片段中分享的是当你的听众觉得无趣时，可以通过具体、停下、坦诚这三个方法，让听众愿意继续听你说。之后为了化被动为主动，我们一起学习了第二个片段：引诱你的听众。通过经历、收集、想象的方法，主动收集并充实素材库。同时，通过前期主动的素材选择、素材使用方法的选择，从而达到“引诱听众”的目的。\u003c/p>\u003cp>道理只能赢得辩论，故事可以收服人心。希望在今后的工作和生活中，大家能够使用今天所学到的方法，讲讲好故事，好好讲故事。\u003c/p>\u003cp>感谢大家今天的参与，我是拆书家佳音。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1544173241000,"updated_at":1544173310000,"ria":true},{"id":6680,"topic":"描述细节，述说动人故事","learn_goal":"学会用三步法讲故事","remark":"《故事思维》是将故事思维应用于商界的第一人 ——安妮特 ·西蒙斯的奠基之作，畅销全球十余年。她开创性地提出商界沟通中常用的六大类故事，并详细阐释了在何种情况下、如何讲述这些故事：从获取投资人信任到赢得商业合同，从团队建设到营销活动的开展，彻底讲透了用故事提升个人在商界影响力的方方面面。\r\n本书认为：说故事永远胜于讲道理。讲好一个故事，可以赋予冰冷的数据和残酷的事实以温情，可以触及最有心机、最强硬、最敌对的人内心深处的柔软所在。说故事并非与生俱来的天赋，是可以学习和逐步提高的思维模式，了解其中关窍所在，你便可以迅速掌控全局。\r\n本书作者曾培训过微软公司、美国国家航空航天局（NASA）等著名机构，以大","level":"TF1-1","duration":10,"status":30,"type":0,"chaishujia":{"username":"雷蕾","city":"上饶"},"club":{"name":"上饶光阴分舵","city":"上饶"},"prologue":"\u003cp>【自我介绍】\r\n大家好！我是预备拆书家雷蕾。\r\n &nbsp;\u003c/p>\u003cp>三个标签介绍我自己：\u003c/p>\u003cp>1.【职业】我是一名特殊教育老师。这是我的职业，我面对的是一群特殊的孩子，他们当中有智力障碍、有听力听障，甚至是多重障碍的孩子，所以，无论在教学还是在生活中，都要求我们对他们付出更多的耐心、细心及爱心。\u003c/p>\u003cp>2.【爱好】我是一名吃货，尤其是“肉类”，开心了要吃，不开心了更需要用食物来治愈自己受伤的心灵。\u003c/p>\u003cp>3.【学习】我是一名初级学习者，生活中过于懒散，想要改变现状，所以希望学习能充实自己，提升自己的能力。\u003c/p>\u003cp>【拆书帮介绍】\u003c/p>\u003cp>首先我们来了解一下“拆书”是什么？\u003c/p>\u003cp>“拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。\u003c/p>\u003cp>分为个人学习的拆书法和组织学习的拆书法：个人学习的应用是便签法，让人读一本书就能达到参加同主题培训的效果；组织学习的应用是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。\u003c/p>\u003cp>从学习者的学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训师。\u003c/p>\u003cp>再来说一说“拆书帮”又是什么呢？\u003c/p>\u003cp>“拆书帮”是一群爱好学习的人在一起释放自己的能量，表现为全国各地的拆书帮分舵（也叫拆书帮俱乐部）。拆书帮分舵是非盈利性“青年自组织”，其使命是“释放学习促进者的能量”，帮助更多学习爱好者成长为拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":10021,"quote":"\u003cp>今天我要拆解的书是《故事思维》里的一个片段，请大家花三分钟的时间阅读以下拆页内容，阅读完了可以举手示意一下。\u003c/p>\u003cp>【R—阅读原文片段】\u003c/p>\u003cp>记性不只是指一种好的或是差的记忆功能。一些记忆力差的人也能记住一个难忘的故事。我们能够记住那些一个个情节交织的，对我们有意义的、对我们的想法有着影响的事情，或是让我们感觉好或坏的事情。我们能够记住的，是那些能让我们情绪波动的故事。好的故事会被铭刻在听众的大脑中，字字句句被串成意义深远的整体，激发出生动而又强烈的情感。我们都记得，野狼&quot;呼時呼時吹气，直到把房子吹倒&quot;的《三只小猪》的故事。 然而大多数人却不记得数学课上的&quot;向量&quot;。你要是想让人们记住什么，你就要让你的故事在人们头脑里留下一个难忘的形象或者镜头。让它能像《辛德勒名单》中穿红衣服的小女孩儿、《发条检》里圆挣着的眼晴，试图打电话回家的外星人一样清晰地在人们的脑海里留下印记。细节越具体，越容易产生广泛的联系，这貌似不合常理，却是所有讲故事者共知的秘诀。如前文所述，一个成功的故事必然是触动了人类某种共性的故事。其实，要触动人类的共性，首先要描述个体的个性。例如，你若想通过自己的故事唤起听众对母亲的回忆，你首先要细致地描绘自己的母亲。你可以提到某个平凡的一天，母亲穿着朴素的衣服开着常见的车，送你去上学。这段叙述无需华丽的辞藻，也不必情节曲折，只要有清晰的细节，便能够让听众记起自己的母亲。\u003c/p>","explains":"\u003cp>我看到大部分小伙伴都已经阅读完了，如果有还没读完的小伙伴也不要紧，下面我会继续带领大家一起来解读这段文字。\u003c/p>\u003cp>【分享I便签】\u003c/p>\u003cp>What : 人们能否记住一件事情，并不完全取决于记忆力。要想让人们对某件事或者概念印象深刻，最简单的方法就是通过对具体细节的描述让成为一个难忘的故事。\u003c/p>\u003cp>Why :因为一个好的故事能够通过仅仅某一点的描写就引发大家的共鸣，有触动的东西必然会令我们难忘。\u003c/p>\u003cp>How :要想把事情变成一个容易给大众留下深刻印象的故事，我们可以这样做：\u003c/p>\u003cp>1.&nbsp;&nbsp;传递的意义和价值。（能够对我们的想法产生影响）\u003c/p>\u003cp>2.&nbsp;用“五感法”对事物进行描述。（五感指的是：听觉、视觉、嗅觉、触觉、味觉）\u003c/p>\u003cp>3.&nbsp;突出个体个性。（通过某些事物中的细微之处加深印象）\u003c/p>\u003cbr>","interaction":"\u003cp>【分享A1便签】\u003c/p>\u003cp>不知道大家看完原文后有没有联想起自己的相关经历呢！\u003c/p>\u003cp>下面我跟大家分享一个发生在我身上的案例：有一次和朋友聊天，聊到家人，他说他从小单亲，跟着爸爸长大，但是爸爸却没怎么管过他，他读书的学费是自己向亲戚借的，工作之后自己慢慢赚钱还，他特别想知道父亲对子女的爱是个怎样的表现形式？然后他问我，“你的爸爸对你是怎样的？”，我只是回答他：我的爸爸对我很好，特别爱我。然后我们就转到了另一个话题。\u003c/p>\u003cp>反思：\u003c/p>\u003cp>现在想来，我描述的特别空洞，我只是说爸爸对我好和爱我，这个很抽象，完全没有画面感，我应该把它细化到具体的事情上，我可以这样来描述：记得去年冬天，外面飘着大雪，大雪足足盖到了脚踝，由于我平时在外地工作，刚好那天回家，爸爸一大早就去菜市场买我爱吃的菜，回到家中发现鲫鱼忘记拿了，撑起伞就往外走，我拉着因为寒冷冻得满脸通红的爸爸说：别买了，其他的菜我也很喜欢，爸爸说：不行，那是你最爱吃的鲫鱼，你等着，爸爸马上就回来。看着在寒风中瑟瑟发抖的父亲，一股暖流在我内心流淌，这就是最爱我的爸爸。\u003c/p>\u003cp>所以，这个故事的意义是为了体现父亲对女儿的爱，天气寒冷是视觉描述，而父亲对我说的话是听觉描述，最后突出了父爱的伟大，因为父亲在默默的付出。\u003c/p>\u003cp>【分享A2便签】\u003c/p>\u003cp>我们说拆书法是以自我为中心的学习法，阅读、理解、反思过后，关键是要规划应用。我读完这个片段后给自己规划的目标是：\u003c/p>\u003cp>从今日起运用故事思维的方式与家人沟通，向家人表达爱与感谢。\u003c/p>\u003cp>具体步骤如下：\u003c/p>\u003cp>目标：11月29日是妈妈的生日，给妈妈写一封爱的感谢信。\u003c/p>\u003cp>行动：不再像以前一样，只是在微信上发一句生日快乐和微信红包，这次通过故事思维用有意义的，有具体细节的事件编辑出来，向妈妈表达感谢及爱意（记得读初中的时候，我摔断了腿，需要请假一个月，妈妈怕耽误我学习，每天都背我上下学，其中还包括课间上厠所，我们教室在三楼，她每天都要背我回来十几趟，妈妈瘦小的身材，佝偻着背，即使是春天汗水都把她得头发浸湿了，整整一个月，瘦了8斤，因为有妈妈的接送，我的学习成绩没有落下，这件事我深深的刻在我的脑海中，却从来没向妈妈表达我的感谢）。\u003c/p>\u003cp>为了完成这个目标，我要把故事详细的写在信签纸上。\u003c/p>\u003cp>妈妈生日那天，亲手交给她，并且让她好好休息，所有的家务我来做。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1543993566000,"updated_at":1543994122000,"ria":true},{"id":6198,"topic":"什么是故事","learn_goal":"在跟随我完成本次RIA现场学习后，学习者能够在无法通过讲道理","remark":"你遇到过这样的情况吗？当你的朋友又一次跑到你的床边，一边哭泣、一边絮絮叨叨地诉说着另一半的种种不是。你又一次想对TA讲道理、摆事实，但话到嘴边时，你想起了之前无数次类似的场景…… 你似乎又看到了，你苦口婆心的劝说，最后只得到了一句：“我还是离不开TA!”\r\n\r\n场景拉远——在世界上，似乎永远有一些人，他们仿佛拥有黑魔法一样：TA们能够仅仅通过说话、通过演讲，就让无数人像着了魔障一样，为TA笑、为TA哭，为TA的目标而献出金钱、努力，甚至生命。\r\n\r\n你想知道如何说服你的朋友吗？你想知道是什么让人们疯狂吗？——答案是故事！ \r\n「在会说故事的人面前，人们仿佛都是提线木偶」。我们每个人都自带一套木偶线，当线","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"罗靖臣","city":"长沙"},"club":{"name":"长沙橘洲分舵","city":"长沙"},"prologue":"\u003cp>事件：试图影响或者说服人们改变自己的观点、让他们相信之前并不相信的东西，非常困难。比如你想劝父母少买一些保健品，但是他们却对推销员的话深信不疑；又比如你想让你的朋友与TA的另一半好聚好散，又或者你希望你的孩子多读英语、少吃冰淇淋，但无论你怎么苦口婆心、耐心解释、威胁利诱，却发现没有任何效果、“然并卵”。\u003c/p>\u003cp>提问：大家有没有遇到这种情况？遇到时是怎么处理的呢？（请学习者回答）。回答：\u003cem>那就闭嘴；找其他人劝；有的时候会生气，但是不知道怎么办。\u003c/em>\u003c/p>\u003cp>影响：其实生活中有很多场合，我们摆事实、列数据、讲道理，却没有任何办法影响、改变对方，只是让对方更加不耐烦，甚至关上心扉，封闭了沟通的可能。\u003c/p>\u003cp>解决：在这个时候，故事往往比道理更有力量——故事能够将人们代入到它所创造的情景之中，让感性战胜理性、将猛虎变成小猫，于不动声色中达成目的，这就是《故事思维》这本书能够带给我们的力量。\r\n那么，在接下来的15分钟里，我将与大家一同体会故事的力量。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":9473,"quote":"\u003cp>□3-1要求：学习目标中包含了学习者要完成行为的具体内容和完成程度，现场学习设计清晰，体现了该学习目标。\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够在无法通过讲道理来说服时，使用「出人意料公式」设计一个故事来影响对方。\u003c/p>\u003cp>【分组】在开始前先给大家分一下组。按照每桌四个人一组，能够方便大家充分地在组内进行分享。\u003c/p>\u003cp>□3-1要求：原书拆页【R】为\u003cstrong>why\u003c/strong>或者what的内容，或原书一个完整的案例。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>什么是故事？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>故事比事实“更真实”，因为故事是多维度的。事实需要有时间、人物和地点为背景才能变成真理。故事囊括了时间和人物——短则几分钟，长则几代人，涉及一个事件或者一系列事件，事件中还有人物、行为和后果。\u003c/p>\u003cp>\u003cstrong>故事可以兼容复杂的冲突和矛盾。\u003c/strong>如果，你对一个经理说“不要训斥员工”，她可能会反问你：“那我要怎样才能让他们认识到错误呢？”可见，你直白的提醒，既浅显又没有实质性的依据。你这种就事论事的方式，显得不太尊重对方。\u003c/p>\u003cp>然而，如果你告诉她：“上周，在华盛顿哥伦比亚特区，我遇到一个海地出租车司机，他跟我分享了他祖父最喜欢的名言——‘虐待马儿的人终将自己走路’,这样一来，你就可以吸引她的注意力，然后给她讲一个只有一个句子，却有着有更大、更深内涵的故事。”\u003c/p>\u003cp>\u003cstrong>当直接的提醒毫无作用时，故事就起作用了。\u003c/strong>\u003c/p>","explains":"\u003cp>□3-1要求：⑴【I】讲解引导时，拆书家给出了具体行动建议或具体步骤；⑵【I】讲解引导时，拆书家举出了案例，并通过概念与匹配例子之间的对比，引出知识点的逻辑、步骤和明确边界等。\u003c/p>\u003cp>用说话赢得人心、用说话取得成功、用说话争取自己的权益、用说话传递自己的价值。而故事，是我们说服别人、影响别人最有力的武器之一。\u003c/p>\u003cp>【WHY】我想我们从小到大应该听过很多故事，也讲过很多故事给别人，甚至你本身就是一个有故事的人。在不知不觉中，我们被故事影响，也用故事影响着别人。但是大家有没有想过？故事为什么具有这么大的魔力呢？（请学习者回答）\u003c/p>\u003cp>【概念辩析】大家或许会问，什么才是故事呢？\u003c/p>\u003cp>“钻石是在地球深部高压、高温条件下形成的一种由\u003ca href=\"https://baike.baidu.com/item/%E7%A2%B3%E5%85%83%E7%B4%A0/1871970\">碳元素组成的单质晶体，在天然矿物中具有最高的硬度。”这个是故事吗？当然不是，这是单纯的事实，完全没有时间、地点、人物等关键要素。\u003c/p>\u003cp>“钻石恒久远，一颗永流传”。这个算是故事吗？也不完全算，因为它还缺少了人物、情节等关键要素。\u003c/p>\u003cp>那么，故事是什么呢？教堂中的正在举行婚礼，帅气的新郎单膝跪地、为美丽的新娘戴上璀璨夺目的钻戒、并牵手走向长久的幸福，耳边响起那句经典的“钻石恒久远，一颗永流传”。正是故事，叩开了情侣的心扉，让一颗高硬度的石头与爱情建立了联系、令人深信不疑，并让数不清的金钱飞向了钻石生产商们的荷包。\u003c/p>\u003cp>【逻辑阐述】怎样才能通过故事来讲好道理呢？方法有很多，而一般来说，在说服人时使用「出人意料」的魔法公式最为有效。所谓公式，实际上是回答四个问题，具体如下：\u003c/p>\u003cp>\u003cstrong>第一步，目标。\u003c/strong>主人公的目标是什么？\u003c/p>\u003cp>\u003cstrong>第二步、意外。\u003c/strong>而故事发生了什么意外？\u003c/p>\u003cp>\u003cstrong>第三步、转折。\u003c/strong>随着意外的发生，情节会如何“转弯”？\u003c/p>\u003cp>\u003cstrong>第四步、结果。\u003c/strong>最后的结果又是怎样的呢？\u003c/p>\u003cp>把这四个问题简化之后，就可以得到出人意料故事的公式：1、目标-&gt;2、意外-&gt;3、转弯-&gt;4、结局。\u003c/p>\u003cp>真有这么神奇？我们来看一个例子你就明白了：\u003c/p>\u003cp>现在的年轻人，男欢女爱、吵吵闹闹往往是常事，大家应该也经常遇到你最亲密的朋友向你哭诉TA的另一半的种种不好。但当你苦口婆心劝TA散了吧的时候，往往对方总是抚摸着胸口（\u003cem>单手扶胸、单手举天\u003c/em>），说“不~~~我放不下”。那是，你的内心是否奔涌着无数只槽泥马呢？\u003c/p>\u003cp>或许，下面的方法能够帮你解决这个难题——当我那已经年高35的兄弟再次向我诉苦时，我是这样说的： \u003c/p>\u003cp>\u003cstrong>1\u003c/strong>\u003cstrong>、目标：\u003c/strong>从前有个书生为情所困、不能自拔，就找得道高僧指点。\u003c/p>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>、意外：\u003c/strong>高僧让他双手握住一个玻璃杯，然后开始往里慢慢倒开水。\u003c/p>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>、转弯：\u003c/strong>可想而知，书生被烫得直叫唤，最终受不了把杯子扔在地上。\u003c/p>\u003cp>\u003cstrong>4\u003c/strong>\u003cstrong>、结局：\u003c/strong>这时，高僧淡淡地说（\u003cem>做念经状\u003c/em>）：“世间没有什么真放不下的东西、只是施主您还不够疼而已！”。朋友若有所思，之后便再没为女友的事反复纠缠我。\u003c/p>\u003cp>大家会发现，当我把讲道理变成讲故事后，既可以让对方回归到自我思考的空间，又能化解冲突和矛盾，让他感觉你言之有物、言之有理。\u003c/p>\u003cp>【明确边界】问题来了——是不是什么时候都要使用故事来说服他人吗？\u003c/p>\u003cp>当然不！当我们只需要对方去完成某项简单的工作时，简单的命令往往能够达到同样的效果——“请你为我的杯子中加满水”。在这种时候，明确而清晰的指令能够达到同样的效果。\u003c/p>","interaction":"\u003cp>□3-1要求：【A2】环节指令清晰，学习者可以根据指令，设计出一个包含人物角色、有起因经过结果、有对话的故事。 \u003c/p>\u003cp>现在，请各组小伙伴编一个小故事、一两分钟就可以，故事的背景和情节发展是大家可能会遇到的场景（比如说服同事、家人），请记得一定要包含必要的人物、情节（起因、经过、结果）和具体场景下双方的对话、甚至动作。\u003c/p>\u003cp>在这个环节中，一定要运用刚刚学到的【出人意料故事四个步骤】哦。\u003c/p>\u003cp>时间五分钟。五分钟后我们请一组小伙伴给大家展示一下\u003c/p>\u003cp>大家如果一下子想不起来，可以参考这在这样一些场景中使用：比如工作中你希望说服领导，生活中说服爱人与小孩。\u003c/p>\u003cp>【参与者故事】\u003c/p>\u003cp>主题：通过故事说服领导将自己的授课视频通过线上渠道销售\u003c/p>\u003cp>人物：我与领导\u003c/p>\u003cp>时间：某年某月某日\u003c/p>\u003cp>情节：我希望说服领导，将他过去五年线下授课的一些课程放到网络平台进行销售，但由于领导没有接触过线上销售，所以比较畏惧，害怕自己的版权被侵犯。\u003c/p>\u003cp>于是，我就努力利用出人意料的故事来说服领导：\u003c/p>\u003cp>我：我最近听说了这样一个故事，关于行业内的老前辈的。\u003c/p>\u003cp>领导：是什么事啊？\u003c/p>\u003cp>我：是这样的。\u003c/p>\u003col>\u003cli>\u003cp>目标：**（一位20年从业经验的老培训师）希望进一步扩大自己的影响。\u003c/p>\u003c/li>\u003cli>\u003cp>意外：虽然他不断努力讲课，但线下授课仍然有限。直到有一次他遇到了一位做线上培训课程销售的朋友。\u003c/p>\u003c/li>\u003cli>\u003cp>转折：通过线上授课销售，他一下子拥有了数百倍之多的客户。\u003c/p>\u003c/li>\u003cli>\u003cp>结局：他的总销售额反而增长了好多倍，于是他不断地在线上授课，一次讲课能够不断提成，有了更多的时间去打磨自己的课程与陪伴家人。\u003c/p>\u003c/li>\u003c/ol>\u003cp>领导：啊？那我一定要去尝试下。反正也花不了我多少时间。\u003c/p>\u003cp>【强有力结尾】\u003c/p>\u003cp>讲故事，它背后的本质是什么？是一种对世事的叙述、一种理解世界的视角、一种推动他们的力量。\u003c/p>\u003cp>每一个故事，都为听故事的人搭了一座桥，一座通往无尽未知世界的桥。而好的故事，能够帮助我们脱离迷惘状态、满足我们的好奇心、给我们一些生活的建议。\u003c/p>\u003cp>因为，这个时代、或者说跨越历史长河，永远是——“\u003cstrong>得故事者、得天下\u003c/strong>”。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1539272397000,"updated_at":1539272437000,"ria":true},{"id":5533,"topic":"成为一个有故事的人","learn_goal":"学会讲故事","remark":"part  01  拆书主题【告别无趣，让自己成为一个有故事的人】\r\n      如何让自己在面试官眼中与众不同？你需要一个故事。如何让心仪的姑娘对你念念不忘？你需要一个故事。如何在人潮中脱颖而出，告别千篇一律和无趣，成为人际关系中的纽带和独一无二的存在？你需要一个故事。但如何才能在必要时讲好这个故事？《故事思维》，让你成为一个有故事的人。\r\n拆解图书：《故事思维》\r\n拆书家：妙善\r\n拆书家介绍:一个奇妙而美善的女子，喜欢不断开发和挑战自己，热衷徒步，唱歌，播音，读书，写作。\r\n曾拆书籍：《关键对话》《拆掉思维里的墙》《非暴力沟通》《瞬变》\r\n拆书级别：2-4\r\n拆书时长：50-60","level":"TF2-4","duration":60,"status":0,"type":0,"chaishujia":{"username":"妙善","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"学习目标：当跟随我完成本次RIA现场学习后，学习者能够在需要陈述一个事实时，将事实转化成具备“时\r\n间、地点、人物、事件的故事，以此兼融复杂的冲突和矛盾，吸引对方注意力，给听者足够的回旋余地和思考空间。\r\n开场：大家好，我是妙善，一个奇妙而美善的女子，我的三个便签是唱歌，播音，预备情感主题拆书家。今天为大家拆解的图书叫“故事思维”\r\nF：“故事思维”是世界级故事大师安妮特·西蒙斯的经典之作，告诉我们如何用讲故事的方式收服人心。\r\nA：有关思维方式的书一般晦涩难懂，而“故事思维”从应用范围，如何讲好故事到案例学习，让你用读小说的方式，轻松领略故事思维的精髓，有趣而不枯燥。\r\nB：如果你在好看的皮囊下想拥有有趣的灵魂。如果你想在面试就职人眼里与众不同。如果你想成为人际的纽带，收服人心的高手，我推荐你好好精读一下故事思维。","ratings_count":0,"texts":[],"created_at":1531889389000,"updated_at":1531889389000},{"id":5382,"topic":"换位思考","learn_goal":"换位思考","remark":"","level":"TF2-3","duration":30,"status":30,"type":0,"chaishujia":{"username":"魏敏","city":"成都"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，我是魏小米。我的三个标签是：教育，阅读和旅行。教育，是我愿为之奋斗，发展为事业的职业。阅读，我是典型的视觉性学习者，相比听人说，我更喜欢用眼睛和大脑探索未知的世界。三毛和村上春树是我最喜欢的作家，我喜欢他们不羁的灵魂。也是对他们的欣赏，出现了我的第三个标签，旅行——希望有一天，能够像他们一样，通过旅行去发掘未知的美妙。\u003c/p>\u003cp>&nbsp;Feature：今天我们要拆解的书是《故事思维》，是世界级故事大师安妮特西蒙斯的奠基之作。它是商界推广故事技巧的“圣经”，是微软，美国国家航空航天局一致推崇的故事课程。&nbsp;\u003c/p>\u003cp>&nbsp;Advantage： 一般的故事类图书，就是给出故事案例，但是没有理论支撑和具体方法；一般的沟通类书籍，则是给出具体理论和方法，冷冰冰却缺乏感情。而这本《故事思维》，是以故事为核心，以思维为导向，不仅真实有温度，还能启迪思维。\u003c/p>\u003cp>&nbsp;Benefit： 如果你的展示有完美的逻辑体系，理论体系和数据支撑，却缺乏故事案例的支撑，难以打动人心，讲故事能够为你锦上添花；如果想要是说服对方，却不知从何说起，讲故事能为你雪中送炭。《故事思维》中的6大故事模块，9类讲述技巧，10个情景策略，全面升级你的故事思维。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;我们今天要学习的内容，就是《故事思维》中一种重要的方法——换位思考。我们的学习目标就是——本次RIA现场学习过程中，学习者能够在案例分享过程中，运用换位思考法，将一个故事加工为多个案例，阐释多重含义。\u003c/p>","ratings_count":1,"texts":[{"id":8537,"quote":"\u003cp>故事讲述了一个特定的观点，选取了一个独特的视角（有点时候是两个或者三个，我们只关注一个）。聆听一个故事，就是短暂地间接与描述者分享他的视角。同一个故事，如果视角不同，意思也会完全不同。\u003c/p>\u003cp>以《三只小猪》的故事为例，无论是让有稻草房子的猪，有木头房子的猪还是有石块房子的猪，又或者是狼来讲，都是一个不同的故事（道格李普曼）在他的书《增强你讲故事的能力》里指出了这一点。\u003c/p>\u003cp>理论上说，如果你从有稻草屋的猪的角度，给狼讲了一个足够好的故事，狼就会理解这只猪是怎么想的，知道从这间稻草盖得房子里能看到什么。如果这个故事并不比填饱肚子更有价值，无论如何，狼还是会“吹到它的房子”。如果故事比填饱肚子更有价值——比如说这只猪的妈妈和狼的妈妈是一起在博弈西长大的（我扯得有点远，是吧）——狼就可能会被影响到，让住在稻草屋里的小猪多活上一段时间。\u003c/p>\u003cp>叙述的过程，其实就是叙述者和倾听者选择并交流一个特定观点的过程。当你想让人们去“看”他们看不大的东西，一个故事就可以将他们从一个视角带到另一个视角。开阔听众的视野，给他们一个新的看问题的角度，就可以改变他们的想法。\u003c/p>","explains":"\u003cp>WHAT： 换位思考，从社会学来说，是人对人的一种心理体验过程，要求我们将自己的内心世界，如情感体验，思维方式等与对方联系起来，站在对方立场上体验和思考问题。\u003c/p>\u003cp>WHY：大多数人讲故事的时候，都会先假定一个主人公，再从这个他的角度阐述故事内容。但是，主人公不同，我们阐述的故事内容，价值取向也完全不同。换位思考，能够帮助我们从不同角度理解这个故事，将一个故事加工为N个案例。\u003c/p>\u003cp>如果不进行换位思考，一个故事就只能是一个故事，看待问题角度受限，思考方向受限，故事的使用情景也受限。\u003c/p>\u003cp>&nbsp;HOW（细化原文步骤）： 究竟如何进行换位思考呢？拆段中给出了使用理念，但是缺乏明确的使用步骤，我将其细化为以下步骤：\u003c/p>\u003cp>找出所有人物：整个故事中的人物有哪些，统统找出来\u003c/p>\u003cp>选择故事主角：不同的主角，就是不同的立场，你选择的主角是谁？\u003c/p>\u003cp>阐述正面价值：主角值得肯定的东西是什么？这就是你的正面价值\u003c/p>\u003cp>加工故事逻辑：从主角的角度重新阐述这个故事\u003c/p>\u003cp> EXAMPLE（意译原文案例）：灰姑娘的童话故事大家肯定都听过。\u003c/p>\u003cp>首先找到故事的所有人物：灰姑娘Cinderella，有她的父亲，有继母和继母的两个女儿，还有王子。\u003c/p>\u003cp>选择故事主角：通常这个故事的主角都是灰姑娘，传递的价值观则是勇敢和善良，故事逻辑则是灰姑娘以德报怨，温柔对待继母及其女儿，同时为了追求自己的幸福，勇敢前行。\u003c/p>\u003cp>如果换个角度，我们把主角定位继母呢？继母为了让两个女儿能够得到王子赏识，帮助他们制作美丽的服装，将他们细心打扮，让他们美丽出场。这是什么？这就是继母角度的正面价值——母爱。从继母角度出发，则是一个为了让自己和女儿得到幸福，用尽方法，排除异己的故事。\u003c/p>\u003cp>从这个案例可以看出，换位思考，能够帮助我们摆脱固有思维，从多个角度理解故事，从多个角度阐述不同观点\u003c/p>\u003cp>WHERE：换位思考的方式，在与人沟通，写作中，需要与人分享案例时，均可使用。\u003c/p>","interaction":"\u003cp>场景设计： 请大家先听这个故事：公司的优秀员工小A做了一份出彩的广告创意设计，但是被小B盗取，声称是他自己的设计。后来小A找到领导，反映相关问题，领导进行了彻底调查，查明真相，开除了小B，同时赞赏了小A的勇气。小B意识到了自己的问题所在，后来痛改前非。\u003c/p>\u003cp>小组讨论：现在每3-4人为一组，XX做小组长，带领大家讨论并做好记录。\u003c/p>\u003cp>请大家一起找出这个故事中的所有角色；\u003c/p>\u003cp>一人选择一个角色，有重合的，小组长进行分配；\u003c/p>\u003cp>找出你扮演角色立场的正面价值；\u003c/p>\u003cp>加工你的故事逻辑，站在你扮演的角色的角度，讲出这个故事。\u003c/p>\u003cp>给大家10分钟时间。\u003c/p>\u003cp>角色扮演：请一个小组与我们分享他们的角色扮演成果。\u003c/p>\u003cp>学习者分享：\u003c/p>\u003cp>小B：这个方案是小A的主创意，但我们是根据他的创意给出了一些建议，综合了大家的建议，并且猜测了领导的意图，对方案进行了优化，得到了最终版本的方案，后来领导采纳了这个方案，虽说主创意确实是他的，但是我也没有错，最终版本本来就是我的设计。\u003c/p>\u003cp>小A：我觉得应该还原事实真相，我主要来做的，就应该由我来呈现。\u003cbr>\u003c/p>\u003cp>领导：为什么最终要开除小B？最终方案的呈现确实是由小B做的，论功劳论苦劳的确是他的，但是从公司价值观的维护上来说，我们需要对原创者进行保护，这样才能鼓励我们公司的原创精神。\u003c/p>\u003cp>从这个案列也可以看到，当我们站在不同主人公角度看待同一个故事时，我们都能够看到不一样的东西。今天只有一个案列给大家练习，但是下来之后，大家可以运用这种换位思考的方法，将故事进行加工，将一个故事加工为多个案列，最终形成自己的案例库。\u003cbr>\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1529808501000,"updated_at":1529808609000,"ria":true},{"id":5293,"topic":"告别无趣，让自己成为一个有故事的人","learn_goal":"用五感讲故事","remark":"part  01  拆书主题【告别无趣，让自己成为一个有故事的人】\r\n      如何让自己在面试官眼中与众不同？你需要一个故事。如何让心仪的姑娘对你念念不忘？你需要一个故事。如何在人潮中脱颖而出，告别千篇一律和无趣，成为人际关系中的纽带和独一无二的存在？你需要一个故事。但如何才能在必要时讲好这个故事？《故事思维》，让你成为一个有故事的人。\r\n \r\n拆解图书：《故事思维》\r\n拆书家：妙善\r\n拆书家介绍:一个奇妙而美善的女子，喜欢不断开发和挑战自己，热衷徒步，唱歌，播音，读书，写作。\r\n曾拆书籍：《关键对话》《拆掉思维里的墙》《非暴力沟通》《瞬变》\r\n拆书级别：2-4\r\n拆书时长：50-60","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"妙善","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"\u003cp>\u003cstrong>分组\u003c/strong>：正式开始前我先为大家分组，每组4人，每组一个组长，负责带领大家讨论。\u003c/p>\u003cp>\u003cstrong>学习目标\u003c/strong>：当跟随我完成本次RIA现场学习后，学习者能够在需要陈述一个事实时，将事实转化成具备“时间、地点、人物、事件的故事，以此兼融复杂的冲突和矛盾，吸引对方注意力，给听者足够的回旋余地和思考空间。\u003c/p>\u003cp>\u003cstrong>开场\u003c/strong>： 大家好，我是妙善，一个奇妙而美善的女子。为什么说奇妙呢？因为我每隔几年就会在梦里见到一位姐姐，我们在梦里一起成长，而如今这个人已经来到现实，我曾经是一本书看完都难而上月看完了8本书，很奇妙对吧？美善的意思是，我会非常善良的对待每一个又好看又为我鼓掌的人。（掌声）谢谢大家。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;今天为大家拆解的图书叫《故事思维》\u003c/p>\u003cp>\u003cstrong>F\u003c/strong>：它是世界级故事大师安妮特·西蒙斯的经典之作，告诉我们如何用讲故事的方式收服人心。\u003c/p>\u003cp>\u003cstrong>A\u003c/strong>：其实有关思维方式的书一般晦涩难懂，而故事思维从应用范围，如何讲好故事到案例学习，让你用读小说的方式，轻松领略故事思维的精髓，有趣而不枯燥。\u003c/p>\u003cp>\u003cstrong>B\u003c/strong>：如果你和我一样，在好看的皮囊下想拥有有趣的灵魂。如果你想在面试就职人眼里与众不同。如果你想成为人际的纽带，收服人心的高手，我推荐你好好精读一下故事思维。\u003cstrong>B2\u003c/strong>：今天为我们带来的两个片段能告诉我们在什么样的情况下，我们比较适合去讲一个故事，而怎样才能讲一个生动，具有趣味和吸引力的故事。&nbsp;\u003c/p>\u003cp>接下来请大家阅读第一个片段“何谓故事”，让我们看一下讲故事的重要性和怎样表达才算讲故事。\r\n &nbsp;请大家阅读片段，读完后示意我。 &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":8420,"quote":"\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003c/strong>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;何谓“故事“\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 故事比事实“更真实”，因为故事是多维度的。事实需要有\u003cstrong>时间\u003c/strong>、\u003cstrong>人物\u003c/strong>和\u003cstrong>地点\u003c/strong>为背景才能变成真理。故事囊括了时间和人物——短则几分钟，长则几代人，涉及一个事件或者一系列事件，\u003cstrong>事件\u003c/strong>中还有\u003cstrong>人物\u003c/strong>、\u003cstrong>行为\u003c/strong>和\u003cstrong>后果\u003c/strong>。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>故事可以\u003cem>兼容复杂的冲突和矛盾\u003c/em>。如果，你对一个经理说“不要训斥员工”，她可能会反问你：“那我要怎样才能让他们认识到错误呢？”可见，你直白的提醒，既浅显又没有实质性的依据。你这种就事论事的方式，显得不太尊重对方。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 然而，如果你告诉她：“上周，在华盛顿哥伦比亚特区，我遇到一个海地出租车司机，他跟我分享了他祖父最喜欢的名言——‘虐待马儿的人终将自己走路’,这样一来，你就可以\u003cem>吸引她的注意力\u003c/em>，然后给她讲一个只有一个句子，却有着有更大、更深内涵的故事。“好的建议的人。不管别人的地位怎么样，你都会尊重他们。当直接的提醒毫无作用时，故事就起作用了。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 其他形式的影响，如奖励、优惠、贿赂、花言巧语、威压和耍花招都太功利，目的过于明显。而这些技巧实际上也招致了抵抗，因为它们没有\u003cem>给人们足够的回旋余地和思考空间。\u003c/em>\u003c/p>\u003cp>故事能在听众的思想中发展并成长。\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; 大家都听说过一句话：“我有酒，你有故事吗？”那怎样才算一个故事呢？\u003c/p>\u003cp>&nbsp; &nbsp; 片段指出讲故事的基本元素是：“\u003cstrong>时间，地点，人物，事件”，而事件里还要有行为和结果\u003c/strong>。我现在说句话大家分辨一下是不是故事：1，双11，最忙的是阿里人（不是）。2，双11，1万名阿里人喝红牛睡帐篷，彻夜不眠（只差结果就是一个完整的故事）。大家会发现，十点读书，喜马拉雅上的爆文名字是越来越长了，他们在标题中越来越多的应用故事思维来吸引注意力，也就是文章中提出的故事思维的第二个好处。除此之外，由故事代替陈述还可以兼容冲突和矛盾，并给对方足够的回旋余地和思考空间。\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp; \u003c/strong>例如我朋友非常喜欢一个姑娘都把她介绍给所有家人认识后才发现她满口谎言，劣迹斑斑。他知道不是对的人，却怎么也放不下来寻求我的意见。面对这种情况，我们的一般反应是要么劝分，要么劝和。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; 不这么做的坏处：\u003c/strong>而直接陈述思想是有弊端的。劝分的话，你列举了女孩对他对家人的百般不在意，但对方就是爱，你说一堆，他还是放不下，然后你不耐烦了说，“该放时自然就放下了，别急”，朋友又觉得你不上心，触发矛盾。如果劝和，他基本就会把你当救命稻草，不停倒苦水，耽误了你的时间，同时他还不能建立独立思考。那如果用拆页的故事思维，用一个完整的故事代替直接陈述会如何？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;其实当时我没有直接回答他，而是把自己意见转化为故事。说，我给你讲个故事吧。“从前有个书生为情所困不能自拔，就找到了寺庙的得道高僧求指点。结果高僧只是给了他一个玻璃杯让他握住，然后往里面慢慢倒开水，书生被烫的两个手倒着拿，但最终受不了烫把杯子扔在地上，高僧说“世间没有什么真放不下的东西，只是还不够疼而已”。朋友若有所思，之后便再没为女友的事反复问过我。大家会发现，当我把陈述变成故事后，既可以让他回归到自我思考的空间，又能化解冲突和矛盾，让他感觉你言之有物。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;再比如上次对象和老朋友聚会，我想劝他少喝点，觉得说了也白说，没力度，就讲了个故事，说“上月老家一家十年老店，餐馆老板娘不小心把医用酒精倒白酒罐里，当时聚会三人都死了，没赴约的人反而捡条小命。”结果他把这个故事讲给朋友听，大家当天都少喝了。\u003c/p>","interaction":"\u003cp>&nbsp; &nbsp; &nbsp;\u003cstrong>A1\u003c/strong>：接下来请大家回想一下，你以前和爱人，父母，同事，有没有那种，你想说明一个事实观点，但对方觉得你老生常谈，一点新意没有，甚至觉得你唠叨，完全不以为然，给你的感觉说了和没说一样的经历？是怎样的场景，怎样的陈述句？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; \u003cstrong>现场案例\u003c/strong>：父母呀，总会说，女孩子要早点回家呀\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;\u003cstrong>A1+：\u003c/strong>既然陈述事实影响力小，听起来也乏味，如果就用故事思维的方法，我们吸引他注意力的同时也让他自己思考，还是刚才我们说的场景，你会把你的观点转化成一个怎样完整的故事呢？当然这个故事可以是隔壁老王的，领导上司的，或者预言故事名人传记。大家分组讨论后找人分享。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;\u003cstrong>现场案例\u003c/strong>：我觉得故事思维太好了，可以用在孩子教育上，一通百通。以前陌生人（可能是快递）敲门，我家乐乐，5岁，她就跑过去开门。我会说不要过去开门。但没有任何作用，他也不爱听。但现在想想可以用故事思维给他讲个故事：“上周，楼上佳佳在家听到有人敲门，以为是快递，其实是别人家家长，就被带回家玩了，结果父母找不到，找了所有的地方，边找边哭，找了一晚上，我看了都跟着伤心，还好最后找到了。”\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":8421,"quote":"\u003cp>\u003cstrong>学习目标\u003c/strong>：当跟随我完成本次RIA现场学习后，学习者能够在以讲故事的方式代替陈述时，用以下方法使故事更打动人，吸引人，提升影响力：1投入自己的感情（积极/消极），2调动五感（视触嗅味听）\u003c/p>\u003cp>\u003cstrong>承上启下\u003c/strong>：既然我们了解了以故承事代替陈述的优势以及故事的基本元素。但刚才小组内同样是讲故事，我们发现有些人讲的就回味无穷，而一些人就很平淡，不太吸引人。那如何才能讲好一个故事？请大家阅读片段，读完后抬头示意我。\u003c/p>\u003cp>讲故事的目的，就是让听众\u003cstrong>看到、摸到、闻到、尝到故事\u003c/strong>，这样才能让他们身临其境。杰·奥卡汉是个中高手，最善于给故事添加声效。在他的故事里，如果需要刮风，他便鼓起腮帮，撅起嘴，模仿大风吹过的声音。有时候，你无法惟妙惟肖地模仿出某种声音，没关系，你可以想办法勾起听众对这种声音的回忆。譬如，一位洗衣机推销员这样讲述廉价洗衣机的故事：“一开始，那洗衣机是‘咯嘣咯嘣’地，一个星期后变成了‘咯咯吱吱’的了，凡是听过雾号的声音的人，脑海里自然会响起那熟悉的声响。\u003c/p>\u003cp>气味和滋味与声音一样重要，它们也能勾起人们的情感记忆，甚至会让人产生生理反应。例如，让你的听众们去想象巧克力饼干出炉时的场景，人们不自觉地张大鼻孔，脸上浮现出享受的神色。至于滋味，如果你能把咬一口刚切好的柠檬描述得足够好，听众的嘴里就会口水泛滥。用声音、气味和滋味，把听众引入你的故事，给他们身临其境的感觉，你就能全方位地调动听众的感官，让他们用全身体会故事。\u003c/p>\u003cp>\u003cstrong>投入感情才能获取影响力\u003c/strong>\u003cstrong>。\u003c/strong>讲故事的时候止步不前，主要基于两个原因：其一，他们担心自己看起来愚蠢、粗鄙、“不专业”；其二，担心述说故事会在某种程度上损害自己的可信度。我们使用有意义的论点，能能够在实际生活中被证明，并得到有逻辑性的结论。不幸的是，我们的故事风格变得拘谨、冷淡、情绪化，甚至无聊。你可以谨慎行事，但谨慎无法创造奇迹。如果你希望影响他人，必须敢于冒与人们在情感层面上打交道的风险。你需要唤醒自己的情感来感染他人的情感，就像戏剧里的主角，情感交流之前首先要感受情感。希望、爱、同情、勇气、尴尬、欢乐和鼓舞，这些情感是驱动力，推动人们做出你希望他们做的行为。有时候驱动源会是消极的情感，如生气、害怕、伤心——面对不公的悲愤，面对失败的恐惧和悲伤。\u003c/p>","explains":"\u003cp>片段指出，让听众看到、摸到、闻到、尝到你的故事，就会有身临其境的感觉。也就是调动五感（视触嗅味听）。\u003c/p>\u003cp>比如视觉化你的故事，有很多工具：思维导图（边画边讲），PPT，沙画，那如果我们没有这些工具的话，最基础的，就是用自己的肢体动作和表情来视觉化故事。像卓别林，小羊肖恩，没有语言，我们却知道它讲的什么。中国人一般比较内敛含蓄，很少开发肢体语言，但肢体语言可以让故事更生动，个性化，听众也更有代入感。还珠格格大家看过吧？我们都喜欢看小燕子讲萧剑的故事。下面请一位伙伴讲一下小燕子的话，（掌声）当时呀，萧剑就对我说“小燕子，我带你去讨回公道”伸手一拉，刷的，我就上了马了，我们一阵飞跑哇跑哇把马儿都累得一身大汗。现在我模仿小燕子讲一下，大家对比一下有何不同。当时呀（眼神），萧剑就对我说“小燕子（手势），我带你去讨回公道”伸手一拉，刷的（牵起旁边人手的动作），我就上了马了，我们一阵飞跑哇跑哇（手脚并用）把马儿都累得一身大汗。大家发现什么不同了？对，通过对比大家感受到了视觉化故事的渲染力。\u003c/p>\u003cp>听觉，是两方面，一是自己的声音，二是模拟故事里的声音，也就是配音。大家会发现，你在打电话，唱歌，说话的声音是不一样。请大家记录四个词汇（\u003cstrong>细化步骤\u003c/strong>）：语速，语调，语音，停顿。这第四点针对声音的表达方法，对讲述的内容影响力有多大？请大家闭上眼，听一段音乐，告诉我感觉（快乐，美好）。再听听这个呢？（趣味，舒缓）。实际这两首歌，歌词完全一致，只因为语调语速等的不同，就造成我们截然不同的感受和理解。所以当我们和孩子说：我这不是为你好吗？（语速快声音高而尖）给对方的感觉只能是不真诚。而当你说：我这不是为了你好吗？（语速缓慢，在你字上停顿）感觉就会不一样。\u003c/p>\u003cp>触觉，如果你不能现场让对方摸到你故事里的东西，就形象的描绘一下。例如：宝宝不要玩火哈，上周妈妈去看望烧伤病人，他的皮肤就像杨树皮一样，疙疙瘩瘩一条一条的，烧到就没你现在这么嫩了。\u003c/p>\u003cp>\u003cstrong>异议预防\u003c/strong>：或许你会有这样的疑问，我要讲个故事，受时间场地影响，很难做到五感都触发，那怎么办？给大家一个提示，人的深层记忆中，视觉占55%，听觉38%，言语7%。在时间紧张时，我们可以抓重点，也就是重视视觉。\u003c/p>\u003cp>五感调动让听众有身临其境的感觉，但要想增加影响力，还要加入感情。分积极感情和消极感情。大家说情感有哪些？积极（勇敢，希望，爱）消极（生气，伤心，愤怒）当我们的故事有感，有情我们的故事就声情并茂了。举个例子：自我介绍时我说自己想成为情感类拆书家，接下来我用一段故事代替这段陈述，大家听一听我调动了哪些感觉和情感：\u003c/p>\u003cp>我和初恋是大二认识，刚来北京我们两人挤一个没窗的单人床，只为省钱。结果来北京第三天我就受伤了，膝盖位置刮伤，直接看到了雪白雪白的骨头（视觉），缝了11针不能走路，大夏天的，没空调，他怕我热坏了，天天给我擦身上（触觉），当时就想着一定要一辈子，结果相恋6年分手（忧伤），现在回想是当初的我们不懂爱，所以今天我想成为一个专拆情感的拆书家，用情绪管理心理学，沟通技巧。让我们遇到心动的人追的到，更守得住（勇敢）。请大家告诉我，刚才我用了哪些方式让我的故事更具吸引力？是的，有视觉化故事，有积极的情感。\u003c/p>","interaction":"\u003cp>A3：现在我给大家一个接地气的场景：最近高考话题很火，你朋友家孩子高二，不爱学习，觉得学习没用。王宝强学习不好也能当名人。你的观点是你今天做的一切努力都是值得的，不白学，坚持就是胜利。但这个话既没力度又吸引力。所以请将你的观点加工成一个故事（你的，别人的，名人的），并用“五感+情感”的方式去表达。两人一组进行演练和角色扮演，一人扮演高中生，一人本色出演。讨论后请一组上台演示。\u003c/p>\u003cp>现场案例：我是成人她是学生，高二孩子很叛逆，讲别人的故事，他容易反感，我想让她用自己的故事影响自己。\u003c/p>\u003cp>学生：我就觉得学习没什么用嘛！\u003c/p>\u003cp>就业者：那我现在想请你感受一个故事,请闭上眼睛，音乐起，现象一下你现在是25岁的你自己，某天你起床了，你看一下周围房间，是怎样的？\u003c/p>\u003cp>学生：周围阳光温暖，音乐特别美，我很喜欢这个环境。\u003c/p>\u003cp>就业者：25岁你已经上班了，现在是工作日，你想像一下你现在穿什么衣服上班，去哪里上班？\u003c/p>\u003cp>学生：我穿着高跟鞋，职业装，去写字楼做白领。：\u003c/p>\u003cp>就业者：你喜欢这个工作吗？这是你想要的生活吗？\u003c/p>\u003cp>学生：是的，我喜欢这个工作，喜欢这样的生活。\u003c/p>\u003cp>就业者：现在音乐停止，我想请你问自己一个问题，16岁的你如何做才能让25岁的你过上你想要的生活？\u003c/p>\u003cp>学生：我需要学习，努力，上进，让自己在人群中突出，学习办公软件......\u003c/p>\u003cp>\u003cstrong>摘要点评，真诚赞美，号召鼓掌\u003c/strong>：我们伙伴的故事四要素齐备，并引发了视觉和听觉，带动了积极美好的情感，非常生动又有影响力。重点是他们是用听众的故事影响听众，非常有创意值得我们大家学习，请大家把热烈的掌声送给他们。这个案例太棒了。\u003c/p>\u003cp>\u003cstrong>A2\u003c/strong>：\u003cstrong>分步催化1\u003c/strong>：故事思维中最常用的就是讲自己的故事，你曾经爱过什么人，遇到哪些坑，对吗？刚才我就讲了我想成为情感拆书家的故事。所以下次拆书介绍3个便签时，我就可以用这个故事，代替我的便签，这样更容易吸引大家，增加我的影响力。现在请大家思考一下。将来，你在什么什么时候，可以用自己的故事代替陈述而让自己的表达更有吸引力呢？是应聘的时候用你开发新客户的故事，代替说自己很有能力？或者像今天，认识陌生人时，用一个你徒步冒险的故事，代替说我喜欢户外？将来什么场景，我们可以把陈述变成故事？\u003c/p>\u003cp>\u003cstrong>分步催化2\u003c/strong>：在你刚才的场景中，用五感加感情的方式，讲一个怎样的故事才能达到你想要的目的呢？讨论后分享\u003c/p>\u003cp>\u003cstrong>现场案例\u003c/strong>：我可以用故事思维说服我的合伙人。他有点犹豫要不要和我一起创业，如果我说自己是过来人，懂他的不容易。这样的陈述没有力度。我可以讲个我自己的故事：“我理解你现在的处境，我刚回北京，为了给孩子更好的生活，我自己创业，一天工作十几个小时（伤感），也没人帮我。直到27岁，我看一下账本（视觉），发现自己可以达到一月3万收入，我就带着孩子，直接买个一件2000元的衣服。你现在也是我当初的年龄，和我一样的境遇，我非常希望你能加入我，然后让我来帮助你成为现在的我（积极肯定）。好吗？”\u003c/p>\u003cp>\u003cstrong>摘要点评，真诚赞美，号召鼓掌：\u003c/strong>感谢小伙伴的分享，有视觉冲击，有情感的由伤感到积极，非常有影响力，相信你这样的表达方式一定可以打动合伙人，大家把掌声送给她，非常棒。\u003c/p>\u003cp>\u003cstrong>强有力的总结\u003c/strong>：大家已经意识到，用故事代替陈述，会让我们的语言更吸引人，而要讲好一个故事，就要运用五感和感情，希望下次我们再相聚，我说到“我有酒，你们有故事吗？”你们会义正言辞的回答我，“我，是那个有故事的人。”谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1528512825000,"updated_at":1533287248000,"ria":true},{"id":3950,"topic":"故事思维","learn_goal":"让大家认识到故事思维的重要性以及学会如何讲一个有感染力的故事","remark":"讲故事不仅是一种技巧，而且是一种思维方式，借助故事可以更有效地激励、说服与影响他人。说故事永远胜于讲道理。讲好一个故事，可以赋予冰冷的数据和残酷的事实以温情，可以触及最有心机、最强硬、最敌对的人内心深处的柔软所在。说故事并非与生俱来的天赋，是可以学习和逐步提高的思维模式，了解其中关窍所在，你便可以迅速掌控全局。今天就让我们一起学会讲故事！","level":"TF3-3","duration":60,"status":0,"type":0,"chaishujia":{"username":"norman","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"【自我介绍】大家好，我叫王冠华，是今天的拆书家。首先我用三个标签来介绍一下自己。第一个标签是跨界，因为我从事过销售、商务、运营等多个岗位，也曾经在五六个城市学习工作过；第二个标签是成长，我的信条是人生时候都不能停止成长；第三个标签是拆书爱好者，并在成为拆书家的路上努力着。","ratings_count":0,"texts":[{"id":6893,"quote":"\u003cp>【\u003cstrong>图书介绍\u003c/strong>】\u003c/p>\u003cp>\u003cstrong>事件场景：\u003c/strong>一般来说，试图影响或者说服人们改变自己的观点，让他们相信之前并不相信的东西，非常困难。比如你想劝服父母要服用一些保健品，但是一贯节俭的他们，一是觉得这些玩意没有用，二是觉得太贵，所以并没有按时服用，无论你怎么苦口婆心，耐心嘱咐，威胁利诱都没有用。\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>大家有没有遇到这种情况？遇到时是怎么处理的呢？（请学习者回答）。回答：那就闭嘴；找其他人劝；有的时候会生气，但是不知道怎么办。\u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>\u003cstrong> \u003c/strong>看来大家都很有生活。其实生活中有很多场合，我们摆事实，讲道理是没有办法奏效的，这样只能让对方更加不耐烦，甚至听不进去，最后关闭了沟通的大门，或者让问题搁置了。\u003cstrong> \u003c/strong>\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>那么，遇到这样的情况该怎么办呢？安妮特.西蒙斯《故事思维》就给出了一个新的做法。作者认为，有的时候说故事永远胜过讲道理，讲好一个故事可以赋予冰冷的数据和残酷的事实以温情，可以触及最强硬、最敌对的人的内心深处，并且能通过故事，让人们感受到和看到他们原来没想到的东西，打开一扇新的窗户。\u003c/p>\u003cp>【R阅读原文】\u003c/p>\u003cp>【学习目标一】\u003cstrong>让学习者找出一些需要用故事沟通的场合，然后通过讲故事的方式来进行沟通和解决问题\u003c/strong>\u003c/p>\u003cp>那么故事思维怎么样在沟通中发挥作用呢，下面请大家阅读片段1，时间两分钟。\u003c/p>\u003cp>片段一： \u003c/p>\u003cp>想一想你自己是否有过这样的经历：如果你跟你的同事、领导，或者你的爱人直接讲述某些真相，他们会很难接受。一般来说，直白地讲述真相会让你处处碰壁。如果你径直对老板说：”你这么做是行不通的！” 老板通常会这样回应你：“管好你自己，少管闲事！” 这时候，你就知道讲故事的重要性了。故事不那么直接，它更亲切，不易招来抵触。 \u003c/p>\u003cp>假如，一群固执的领导同处一室，讨论陷入僵局，这对于一个喜欢讲真相的人来说是很危险的一一除非你知道怎样讲一个好故事。\u003c/p>\u003cp>在这样的状况下，我会讲一个关于拉里的故事。 \u003c/p>\u003cp>拉里是我养的一条狗。我牵着拉里出去散步，途中有一根电线杆，拉里从电线杆的一侧走过，而我从另一侧走过，于是身子便被电线杆挡住了。这时拉里就会扭过头来看着我，想知道为什么我们走不动了。我就算用一整天的时间告诉它往后退，它却只有在我往后退的时候才会跟着往后退。而且，只有这样我们才能解决问题，然后继续往前走。 \u003c/p>\u003cp>当我对一屋子的领导讲这个小故事时，他们知道我并不是真的在讲我的狗。醉翁之意不在酒，我的意思是显而易见的。真相就在其中，而且因为真相被包含在故事里，他们便接受了真相。他们没有当着我的面拒绝，他们会听我的故事，也常常会在他们的位置上做出让步，而这也让他们从僵局中走出来，继续向前走。\u003c/p>\u003cp>这就是故事的力量。当你想影响别人时，故事便是最有力的工具。\u003c/p>","explains":"\u003cp>【对比说明】首先，我要说一下，今天这本书所说的故事，不是那些道听途说的逸闻，不是无聊消遣的八卦，不是猎奇的隐私。它和普通的寓言啦，童话了等等故事的相同之处，他们同样具备故事的要素，包括起因、经过、结果、时间、地点和人物。但在这里不同之处是，作者把故事看做影响他人、解决问提的一项技能，所以它还可以是你的个人经历，是你听到的看到的他人生活，更重要的是这个故事是你真正相信的，可以影响他人，解决问题。所以，重要的是在一些无法用数据、说服来沟通的场合，用讲故事的方式来说明问题、化解矛盾、授人以鱼，用旁敲侧击的方式给人启发。\u003c/p>\u003cp>【why】我想我们从小到大应该听过很多故事，也讲过很多故事给别人，甚至你本身就是一个有故事的人。在不知不觉中，我们被故事影响，也用故事影响着别人。但是大家有没有想过？故事为什么具有这么大的魔力呢？（请学习者回答）\u003c/p>\u003cp>学习者1：借用故事来表达；\u003c/p>\u003cp>学习者2：缓和情绪；\u003c/p>\u003cp>学习者3：打破僵局；\u003c/p>\u003cp>学习者4：拉近距离。\u003c/p>\u003cp>【回应】：是的，大家的回答都很好。一个好的故事，能够让这个世界简单易懂，把复杂的事情传达清楚；好的故事，把难以直说的事情让人心领神会；好的故事可以带给人意义，赋予事实以生命；好的故事，开拓人的思路，在面对冲突的时候，不伤害感情；好的故事，不是说教，让人更加轻松的接受事实背后的道理；好的故事，充满情感，打动人心的柔软。所以，这些故事不知不觉的印在了人们的心底。\u003c/p>\u003cp>【例子】不知道多少人曾经看过柴静当年的《穹顶之下》？柴静是一个讲故事的高手，她用娓娓道来的方式把一个非常专业而且有难度的问题展示给普通的大众，下面我们再来看一下这个演讲的一个片段。（放视频http://video.sina.com.cn/view/249334232.html）\u003c/p>\u003cp>大家看到了，在这个视频中，柴静用亲身经历和历史事件强有力的佐证了她的每一个观点，给人脑海里留下了深刻的印象，影响了几亿的中国人民，她面对雾霾这样的一个问题，不是直接用晦涩的的专业词汇来向公众讲述，而是通过讲故事的方式来更好的传播给大众。这就是故事的力量！\u003c/p>\u003cp>【例子】好多人问我为什么参加拆书帮，为什么对拆书这么有热情。我很多\u003c/p>\u003cp>时候讲不出来拆书到底好在哪里。但是我通常会讲一个故事给对方。在参加拆书帮之前，我是一个内向羞涩的读书爱好者。说内向羞涩，是因为我每一次当众说话的时候都会特别紧张，通常会手心出汗，声音干涩，脑子一片空白，不知道自己在说些什么；说读书爱好者，是因为我自己很喜欢读书，买了很多书，可是却不求甚解，有一段时间我甚至怀疑读书到底让我得到了什么。但是在我遇到拆书帮后，这一切都发生了改变。首先，我得到了最大的一个观念是学以致用，你不需要把书读完，只需要对症下药；第二，拆书家可以成为身边人学习的促动者，促进别人提升的同时让自己提升，这里有的是支持和陪伴；第三，大家可以看到我现在上台不紧张了，还可以说这么久。是不是很神奇呢。而这呢也就是我讲给身边人关于拆书帮的故事。这就是我的故事，可能没有那么精彩，但是我希望用我自己亲身的经历和真诚来影响周围的人来参加拆书帮。\u003c/p>\u003cp>&nbsp; &nbsp;【how】那么我们怎么来通过一个故事影响他人，沟通和解决问题呢？首先，我们要认识到这些场合用理性说服或者其他沟通方式已经没有办法解决问题了，或者是通过讲故事的方式更容易让人接受，这个时候可以尝试用讲故事的方式来进行沟通；第二，你的故事要和你传达的信息有关联性，可以通过故事来达到影响沟通的目的；第三，要符合故事的要素，有时间、地点、人物、起因、经过、结果等。\u003c/p>","interaction":"\u003cp>我想大家在工作或者生活中肯定也有许多类似的情形。你需要用故事去说服别人，你需要用故事来达成一致，你需要用故事展示成果，你需要用故事化解冲突。下面大家就仔细想一下，你在什么情况下需要用讲故事的方法来影响他人，解决问题呢?请大家花一分钟时间分想一下，然后把这个场景告诉大家。\u003c/p>\u003cp>那么就假设大家处于其中的某一个情景中，你决定用一个故事和对方沟通，下面就请大家就把你这个故事和对话写下来。五分钟后我们请人来分享你的故事。\u003c/p>\u003cp>学习者代恩强的剧本：\u003c/p>\u003cp>起因：（为什么讲这个故事）\u003c/p>\u003cp>我父亲来深圳帮我们照顾孩子，他平时没那有什么社交，我就想让他出去走走，多认识一些人，也顺便锻炼一下身体。但是我说了几次，他都不愿意行动。后来，我想到父亲很爱吃鱼，就想讲一个邻居钓鱼的故事，让他愿意出去运动一下。\u003c/p>\u003cp>人物：（我对谁讲这个故事）\u003c/p>\u003cp>我和父亲\u003c/p>\u003cp>经过：（我是怎么开始讲故事的）\u003c/p>\u003cp>我：爸，我给你买了一副鱼竿，有时间出去玩玩吧。\u003c/p>\u003cp>父亲：买这个干嘛，我没时间去。\u003c/p>\u003cp>我：你不是爱吃鱼吗，你知道吗，前几天咱们家的鱼就是邻居张叔送的。你知道他的鱼从哪里来的吗?都是从海里钓上来的，你不知道啊，他有的时候能钓上十条八条的来呢。自己家吃不完，还送人。\u003c/p>\u003cp>父亲；是吗？那还挺不错的。\u003c/p>\u003cp>我：是啊，要不你明天就联系他一块去看看。\u003c/p>\u003cp>父亲：也行，我到时候问问。\u003c/p>\u003cp>结果：希望能成功劝服父亲出去运动和社交。而不是直接告诉他去，引起他反感。\u003c/p>\u003cp>【回应】这位小伙伴给出了一个很好的示例，化解了和长辈沟通时，因为理念不同而造成的冲突。非常棒。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":6894,"quote":"\u003cp>【目标二】让学习者进行本次学习后，能够通过细节描述、触动人类共性方式来讲故事，给别人留下深刻的印象。\u003c/p>\u003cp>通过上一个片段大家知道了有些场合讲故事会更加能影响他人，那么我们自己的讲故事的能力如何呢？下面我们做一个简单的练习，看看自己的讲故事的能力。\u003c/p>\u003cp>\u003cstrong>自我测评：你的讲故事的能力\u003c/strong>\u003c/p>\u003cp>根据你自己的表现，给下面提到的情况打分。1代表完全不符合，5代表非常符合。请根据自己的真实情况进行打分。\u003c/p>\u003cp>【I】自测题讲解\u003c/p>\u003cp>&nbsp;大家的得分情况怎样？在20-25分的多少人？15-20分呢？10-15分的？5-10分的呢？如果在20-25分之间，说明大家很会讲故事，如果在15-20分之间，说明大家比较会讲故事，10-15大家讲故事的技能一般，如果在5-10分可能大家可能不太注重讲故事。可能大家已经很会讲故事了，但是你的故事是不是真的就能让人印象深刻呢？还有什么其他我们不知道和不了解的吗?下面我们来进行第二个片段的学习。\u003c/p>\u003cp>【R】 阅读原文\u003c/p>\u003cp>记性不只是指一种好的或是差的记忆功能。一些记忆力差的人也能记住一个难忘的故事。 \u003c/p>\u003cp>我们能够记住那些一个个情节交织的，对我们有意义的、对我们的想法有着影响的事情，或是让我们感觉好或坏的事情。我们能够记住的，是那些能让我们情绪波动的故事。好的故事会被铭刻在听众的大脑中，字字句句被串成意义深远的整体，激发出生动而又强烈的情感。我们都记得，野狼&quot;呼時呼時吹气，直到把房子吹倒&quot;的《三只小猪》的故事。 然而大多数人却不记得数学课上的&quot;向量&quot;。你要是想让人们记住什么，你就要让你的故事在人们头脑里留下一个难忘的形象或者镜头。让它能像《辛德勒名单》中穿红衣服的小女孩儿、《发条检》里圆挣着的眼晴，试图打电话回家的外星人一样清晰地在人们的脑海里留下印记。 \u003c/p>\u003cp>细节越具体，越容易产生广泛的联系，这貌似不合常理，却是所有讲故事者共知的秘決。如前文所述，一个成功的故事必然是触动了人类某种共性的故事。其实，要触动人类的共性，首先要描述个体的个性。\u003c/p>\u003cp>例如，你若想通过自己的故事唤起听众对母亲的回忆，你首先要细致地描绘自己的母亲。你可以提到某个平凡的一天，母亲穿着朴素的衣服开着常见的车，送你去上学。这段叙述无需华丽的辞藻，也不必情节曲折，只要有清晰的细节，便能够让听众记起自己的母亲。\u003c/p>","explains":"\u003cp>看完这个片段，大家觉得对于故事有什么新的认知？捕捉到了哪些关键词呢？（学习者回答：细节、感同身受、人性、情感）【回应】对，作者认为一个让人印象深刻的故事，是能打动我们的，让我们感同身受的；是有细节的；有激发了我们的情感的。大家说的都很好，我脑海中想到的是我研究生时候的一位导师讲的一句话，她说，多年之后，你们上课的内容可能都记不得了，但是你会记得课堂上的感觉，那些争论、欢笑以及竭尽全力思考的氛围。【对比说明】是的，如果仅仅简单的是我们常规所理解的故事，把背景、起因、意外、选择、高潮、逆转、解决等一些要素都具备俱全，并不一定能保证这个故事是一个好故事。那么这里的故事是不是我们常说的那种寓言，神话故事呢？不一定对吧，如果这个故事能用来沟通，解决问题，可以是这些故事。那么这里故事的魅力和力量在哪里呢?在于能激发听众，让他们得出和你一样的结论，相信你说的话，做你想让他们想做的事。那么要做到这样深刻的影响别人，该怎么做呢？\u003c/p>\u003cp>首先，我想问一下大家，一般情况下，什么样的人会比较容易接受你的意见？关系比较亲密对吧?那么为什么关系亲密的人会接受你的意见呢，因为他们对你信任，所以要想一个故事有影响力，必须保证让别人信任你讲的故事。要做到信任，那么这个故事起码是真实的，这种真实不一定是你亲眼看到过，而是你从内心认可这个故事。 那么怎么做到真实呢？大家可以想一想，笼统的描述和细节的描述哪一个更加真实。（回答：有细节的）为什么细节让人真实？因为它让人感同身受对吧？另外，想影响别人，故事的力量其实不在于道理，而在于情感。好的故事要触动人类的共性。其实也就是引起共鸣。你想说服别人，先需要和对方站在同一个频道上。\u003c/p>\u003cp>这样总结下来，【how】讲好故事一个是要描绘细节，一个是引起共鸣。\u003c/p>","interaction":"\u003cp>【微行动】\u003c/p>\u003cp>【明确问题】在上一个片段中，我们大家都写了一个故事，大家回过头去看看，自己讲的那个故事怎么样？是干巴巴的叙述了一件事还是有很多细节？有没有打动别人的力量？\u003c/p>\u003cp>第一个小组分享：我们小组的故事，只是符合了一些故事的要素，并没有做到打动人心。\u003c/p>\u003cp>第二个小组分享：我们小组里的故事比较完整，也有一些细节的描述，但也不够触动人心。\u003c/p>\u003cp>【问题本质】\u003c/p>\u003cp>那么大家觉得没有做到感同身受，打动人心是什么原因造成的？\u003c/p>\u003cp>第一个小组分享：我们没有细节的描述，所以不够生动。\u003c/p>\u003cp>第二个小分享：只是自顾自话，虽然有了细节的描述，但是没想对方要的是什么。\u003c/p>\u003cp>【明确问题本质】回应：好的，大家都已经反思了自己的故事。也找出了故事存在的问题。我们无论是描述细节，还是找到对方的需求点，都是为了让故事打动对方，影响对方对吗？回答：是的。\u003c/p>\u003cp>【引导分组讨论】那么接下我们来继续讨论下，如何描绘细节，以及如何找到对方的痛点？时间五分钟。\u003cbr>\u003c/p>\u003cp>第一个小组：我们讨论的结论是，觉得细节非常重要，另外也需要进行一些节奏的设计，让故事更加吸引人。比如通过数据、还有一些当时的感受等。第二，应该客观，不要很主观。这样就比较容易知道对方在想什么。容易感同身受。\u003c/p>\u003cp>回应：好的，我总结一下就是描绘细节可以通过数据、感受等的描述来增加真实感，而引起共鸣要站在对方的角度去考虑问题。非常好，那还有其他组的小伙伴有补充吗？\u003c/p>\u003cp>第二个小组：我们想要补充的是，讲故事其实要讲究设计，比如你一开始的时候可以先提问，用提问的方式引起别人的好奇心。或者是描绘一种场景，让别人又代入感。别人的痛点和痒点，其实就对方的需求，否则你的故事再精彩，如果和我无关，所以也没办法感同身受。\u003c/p>\u003cp>回应：是的，就像前面恩强讲的那个故事，就抓住了老爸的需求，那就是节俭但是爱吃鱼，所以通过别人钓鱼带来这两方面好处的故事，让老爸出去运动。对吗？\u003c/p>\u003cp>学习者：是的。\u003c/p>\u003cp>总结：好的，我们通过讨论，可以看出对于细节的描述和找到对方需求更深入的了解。细节的描述我们可以通过具体的人事物、时间地点、数据、感受等来突出；而找到对方需求，站在对方的角度考虑问题，并且设计好故事的脉络，那样容易让对方感同身受。非常感谢各位小伙伴，大家的智慧让我们对于如何讲好一个故事有了更深的认识。\u003c/p>\u003cp>【A2】好的，我们大家讨论了如何讲一个让人印象深刻的故事，接下来给大家留一个任务，请大家运用这样的方法，回去找一个讲故事的对象，用这样的方法给他讲一个故事，看看对方的反应。为了回去讲的顺畅，大家可以花三分钟时间先写下来你的计划，不一定是把故事的全貌写下来，可以写一下你准备什么时候对谁讲这个故事，大概内容以及你想用的方法。\u003c/p>\u003cp>学习者：我今天晚上打算回去用今天的方法来对我的闺蜜讲一下我在拆书帮的故事，因为在厦门也有拆书帮。描述一下在拆书帮拆书的细节，因为她最近也很苦恼成长的问题，所以打算从这个角度入手，让她感同身受。参加当地拆书帮。\u003c/p>\u003cp>回应：好的谢谢妮娜，希望你能把这个故事讲好。\u003c/p>\u003cp>结尾：非常开心，今天和各位小伙伴一起分享了这么多美好的故事，在拥有理性思维的同时不要忘记了故事的力量，希望大家能利用故事思维去影响他人，解决问题，愿你讲出好故事，也愿你有好故事可讲！谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1509613670000,"updated_at":1509613794000,"ria":true},{"id":3576,"topic":"讲好“我是谁”的故事 ","learn_goal":"清楚讲好“我是谁”故事的三步骤 ","remark":"为什么你“你懂得一堆大道理，还是过不好一生”？因为你不会“讲故事”。有哲人说，谁会讲故事，谁就能赢得观众，谁就会拥有话语权。讲故事并非与生俱来的天赋，是可以学习和逐步提高的思维模式，今天和我一起通过《故事思维》掌握其中诀窍所在，学习迅速掌握全局的关键技能。","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"quest396","city":"长沙"},"club":{"name":"长沙橘洲分舵","city":"长沙"},"prologue":"各位伙伴，晚上好！我是邹小军。6月8日，一向睡眠不错的我失眠了。为什么呢？因为这天我第一次参加了拆书帮橘洲分舵的活动，第一次感受到这种有爱有趣有料的学习形式太兴奋，结果就失眠。我非常想成为一名拆书家。7月份，我参加了四省分舵联合组织的便签训练营，有幸在春哥的指导下，用四周的时间完成了20拆，得益于春哥的有力指导，还获得了精进奖。\r\n 其实，说起来惭愧，第一次接触到“拆书”这个概念的时候，我曾很傻很天真地以为真是把书拆散了读，就是有一点想不通，撕个书为什么还要分个等级呢？对拆书和拆书帮一直都很好奇。我第一次参加拆书帮的活动以后，就根本停不下来。我很喜欢拆书这种强调结合以往经历，突出学以致用的成人学习理念，我也很喜欢在拆书帮这个学习社群里一群爱智求真的小伙伴一起学习，进行思想碰撞的学习氛围。拆书分为适合个人的便签学习法和适合组织学习RIA现场学习法。其实，在RIA现场学习法中，拆书家也像一个厨师，只是他不作美食，他传授鲜活实用的知识，他做的事色香味俱全的知识盛宴。从现在开始我要开始我做知识厨师的升级打怪之旅。","ratings_count":0,"texts":[{"id":6469,"quote":"\u003cp>&nbsp; &nbsp; 亲身经历比起其他形式的交流更能让别人了解你是“谁”。客观数据不足以产生信任。人们最终根据主观证据相信你的意见和你的话。\u003c/p>\u003cp>&nbsp; &nbsp; 你可以用亲身经历来说明你不为人知的一面。除此之外，你还可以用许多其他方式来告诉人们，你是谁。\u003c/p>\u003cp>&nbsp; &nbsp;你不一定要讲亲身经历。本书中不乏神话、历史故事，经由朋友复述的故事，热门时事和寓言。如果你讲故事的方式确实能够从个人的角度揭示一部分“你是谁”，那么任何形式的故事都能变成“我是谁”的故事。\u003c/p>\u003cp>&nbsp; &nbsp; 当一个人讲了有关特蕾莎修女的故事，那就表明他懂得感恩和虚心向他人学习。我们可以下结论他并没有囿于小我，值得信任，我们可以和他分享我们的故事。如果他选择讲的故事表明他懂得自我牺牲，我们便相信，他在谋求私利的同时也会考虑别人的利益。当我们看穿故事，知道讲故事的人已经意识到自己的缺点，没有否认事实、隐藏真相，我们确实可以相信他，与他共同面对棘手的问题，而不是假装一切“都非常不错”。\u003c/p>","explains":"\u003cp>感谢肖肖的精彩朗读，请大家掌声鼓励。这段文字告诉我们用一个关于“你是谁”的故事介绍自己，能更好地与听众建立联接，产生共情，达到更好的交流效果。不知道大家注意到没有，刚才在自我介绍环节，我没有像往常一样用标签来介绍自己，而是用了一个我加入拆书帮的故事来介绍自己。听我的自我介绍，大家有没有对我的拆书有点期待呢？\u003c/p>\u003cp>其实，这就是今天我想跟大家分享的一个技能的一个实际操练。这个技能就是根据不同演讲场景构思一个有针对性的“我是谁”的故事，让听众看到你想让他们看到的那个你。虽然这个故事还不够精彩，但是它肯定比我直接告诉大家“我是一个拆书爱好者”的表达效果要好的多。用故事潜移默化润物无声地在受众心中塑造出“你是谁”，这样更可信，而不是直接告诉我“你是谁”。\u003c/p>\u003cp>如何讲好“我是谁”的故事呢？只需三步：\u003c/p>\u003cp>\u003cstrong>1.分析场景，设定主题\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2.依据主题，选择素材\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3.编排素材，讲述故事\u003c/strong>\u003c/p>\u003cp>生活是丰富多彩的，生命也是色彩斑斓的。不同的场景需要呈现不同侧面的自己。俗话说，“在哪座山唱哪座山的山歌”。要根据场景设定主题，讲述故事，让受众看你想让他们看到的那个你。\u003c/p>\u003cp>在主题确定以后，就是要选择素材，自己的亲身经历当然最能说明“你是谁”。如果没有亲身经历也不要紧，正如片段中所讲，他人的故事，甚至神话、历史故事都是可以的。素材选取最核心的一点就是无论是谁的故事，一定要与“你是谁”产生关联，让受众从中读懂“你是谁”。\u003c/p>\u003cp>最后，根据主题和素材，把关于“你是谁”的故事讲述出来。如何呈现故事没有固定的套路，因人而异，而且可以通过刻意练习，让你的讲述技能不断娴熟。\u003c/p>\u003cp>讲好“我是谁”的故事是一个会讲故事人的基本功。这个技能主要适合于演讲的场景，而不是说任何时候自我介绍都要用一个故事。关键是要根据场景设定合适的故事。如果，时间比较紧张，就讲一个短小的故事，如果时间充足，就讲一个丰满的故事。\u003c/p>","interaction":"\u003cp>A1: 讲好“我是谁”的故事真的很重要。在这里我想跟大家分享一些我自己的经历。2013年9月份，我开始走上讲台上课。我上了一学期的课，一般没有几个学生能记住我的名字。\u003c/p>\u003cp>就是在这样“恶劣”的环境中，开始了我的第一次授课。第一次上课，我的自我介绍完全是按照操作规程，在PPT上打了自己的名字，留下了电话和邮箱。一学期下来，估计也没有跟学生留下太多印象。结果学生评教的分数就不是很好。当然，影响评教结果的因素是多方面的，但是我自己分析，很重要的一个原因是一开始没有在学生那里留下“我是谁”的很深刻的印象。\u003c/p>\u003cp>第二学期，我就认真准备了两个个故事来向学生说明“我是谁？”。无论哪一类学生，我首先就告诉他们，我是他们的学长。接下来，对于第一类学生，我就给他们讲我的“周日恐惧症”的故事，对于第二类的学生，我就给他们讲“考研的故事”。以这样讲故事的方式开场，确实效果真的不一样，明显感受学生都在竖着耳朵听，很多学生脸上挂着“我懂你”的会心笑容，还有很多的同学眼中迸射中“他乡遇故知”的惊喜。\u003c/p>\u003cp>通过这样的开场，我都能与学生建立起很好的互动。很多学生主动要我的联系方式，经常与我交流，我的学生评教也一直比较好了。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 最后，总结一下并给出我们今后如何使用的建议。今天我给大家分享的一项技能。构建一个切合场景的“我是谁”的故事的三个步骤：\u003c/p>\u003cp>1.分析场景，设定主题\u003c/p>\u003cp>2.依据主题，选择素材\u003c/p>\u003cp>3.编排素材，讲述故事\u003c/p>\u003cp>A2:&nbsp;&nbsp; 9月份，我又将面对新一届学生，在第一次上课的时候。我将运用今天所拆解的如何讲述“我是谁”的方法，向学生进行自我介绍，拉近与学生的距离，产生有效的信任。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1504436232000,"updated_at":1504436641000,"ria":true},{"id":3277,"topic":"教学故事，让大家学习到：如何教授别人","learn_goal":"通过本次拆书学习者会学到如何讲好教学故事","remark":"《故事思维》是将故事思维应用于商界的第一人 ——安妮特 •西蒙斯的奠基之作。\r\n你应该有过列出大量数据事实理论，可是就是说服不了别人的经历，本书告诉你：说故事永远胜于讲道理。讲好一个故事，可以赋予冰冷的数据和残酷的事实以温情，可以触及“强敌”内心深处的柔软所在。\r\n说故事并非与生俱来的天赋，是可以学习和逐步提高的思维模式。翻开本书，马上成为三分钟就能讲好一个故事的沟通高手！","level":"TF2-3","duration":25,"status":0,"type":0,"chaishujia":{"username":"俊领","city":"佛山"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我叫俊领，来着狮山，第一次参加桂城练武场，很高兴认识大家。今天过的级别是2-3，希望得到大家的支持和反馈。首先我介绍一下今天要拆解的图书《故事思维》是将故事思维应用于商界的第一人 ——安妮特 •西蒙斯的奠基之作。\r\n你应该有过列出大量数据事实理论，可是就是说服不了别人的经历，本书告诉你：说故事永远胜于讲道理。讲好一个故事，可以赋予冰冷的数据和残酷的事实以温情，可以触及“强敌”内心深处的柔软所在。\r\n说故事并非与生俱来的天赋，是可以学习和逐步提高的思维模式。翻开本书，马上成为三分钟就能讲好一个故事的沟通高手！今天带给大家的是教学故事，所以先成为一个讲教学故事的高手吧","ratings_count":0,"texts":[{"id":6118,"quote":"\u003cp>【原文阅读】\u003c/p>\u003cp>授人以渔的故事\u003c/p>\u003cp>不管你是干什么的，你肯定有某些希望能传授给别人的本领。你要传授的技能可能是教人如何写信、设计一款软件、接电话、推销产品，或者怎样管理一群志愿者，无论是哪种，学会用故事启发他们，会让你事半功倍。\u003c/p>\u003cp>许多“老师”会被他们的“学生”气得抓狂，因为“他们就是学不会”。与其干生气，拿头撞墙，为何不讲个故事，让他们明白你希望他们学会的东西。大多数时候，你希望他们不仅学会某些东西，更希望他们掌握学习的本领。讲这类故事的时候，最好把“授人以鱼” 和“授人以渔”结合起来。\u003c/p>\u003cp>我们知道，柏拉图很会说教。他经常利用讲故事来启发人们思考（这种技能仍有进步的空间）。其中有个故事是告诉人们民主制度是有其局限性的。\u003c/p>\u003cp>故事发生在一艘在海洋中行驶的船上，船长和船员都遵循少数服从多数的原则。\u003c/p>\u003cp>船上有个非常熟悉航海技术的导航员，他懂得怎么用星象术指引航向。但这个导航员和其他人相处得不怎么好，而且性格很内向，不善交际。当他们在海上迷失了方向，众人陷入惶恐时，船长和其他船员决定采纳他们当中最受欢迎、最会说话且最让人信服的那人的意见，而那个导航员的意见则被大家嘲笑和挖苦。最终，一船人都饿死在了海上。\u003c/p>\u003cp>柏拉图爱讲那些能引导人们思考的故事，我喜欢这种方式，故事应该含有某种深刻的道理。我们在教育方面有一种倾向，就是喜欢简单明了，可这种所谓的简单明了会导致意想不到的后果——把事情看得过于简单化。\u003c/p>\u003cp>如果有人只明白你让他们做的是什么，而不了解你为什么要让他们那样做，他的表现是永远不会让你满意的。在教育方面，追求简洁的原则有时被滥用了。\u003c/p>\u003cp>柏拉图讲的故事把“你该如何思考这个问题”和“你该从这个问题中得到什么样的启发”两方面结合起来，既授人以鱼，又授人以渔。“鱼”和“渔”之间没有绝对的界限。我们讲的故事应该不仅使人获得技能，还能让他们懂得如何学习其他技能。\u003c/p>","explains":"\u003cp>学习目标：通过本次拆书学习者会学到如何讲好教学故事\u003c/p>\u003cp>【R】\u003c/p>\u003cp>发给大家的拆页讲述的是：教学故事，让大家学习到：当需要你教别人一项技能或教别人做什么事情时，如何能让大家快速掌握你的教授内容呢，请大家阅读。拆页举了个例子来说明怎么教，才更好。\u003c/p>\u003cp>P25-26 \u003c/p>\u003cp>请大家花3分钟的时间来阅读拆页，阅读完成后请举手示意\u003c/p>\u003cp>【I】\u003c/p>\u003cp>拆书家拆解引导\u003c/p>\u003cp>1拆页内容着重指出，当你想教授别人知识的时候，不要单纯的讲知识本身，这样的效果并不好，作者讲到要用故事来启发听众思考，将什么样的故事呢？讲让听众感同身受，自己从故事中得出你要教授的内容的核心或好处或坏处。当你激起学生的感受，学生就自己总结出学习该内容的重要性，然后你的培训目标就达成了。\u003c/p>\u003cp>2【我的例子】\u003c/p>\u003cp>我们对新入职的员工要进行培训，每位老员工都有一些讲述的内容，我讲Excel的使用，当讲到VBA使用的时候，很多同事一看需要编写程序，都有点望而却步的感觉，一个是觉得难用，另外也觉得用不上，于是我就讲了我在工作中，未来装样车筹备零件，从一个包含9000多个零件的清单里，怎么通过程序和其它5个表格怎么对比筛选，选出外购总成件清单，进一步和通用件清单对比照出通用件，和国产化件清单对比找出国产化件，按照国产化订购方式订购，和进口件清单比较核对出进口件清单，按进口件订货。编程序用了2天，运算用了十几分钟，如果是人工一条一条的比较多话估计几个星期都完成不了。所以学习VBA对于我们的工作是有必要的。其实听完我的工作经历，大家已经得出这个结论，接下来将如何编程，大家就更容易接受了。\u003c/p>\u003cp>具体步骤及要点是\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003cstrong>构思\u003c/strong>一个自己不实用该技术或方法工作的故事或者应用的特别成功的故事；\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003cstrong>细化\u003c/strong>故事，讲一个“\u003cstrong>真实\u003c/strong>的故事”，什么样的故事是真实的？有时间，地点，人物，事情的起因，经过，结果。有这六要素的故事，就是真实的，听众能看得见摸得着的。就会引发听众的联想和思考；\u003c/p>\u003cp>\u003cstrong>切入\u003c/strong>到你要教授的内容，阐明你的授课内容；\u003c/p>","interaction":"\u003cp>请在场各位，分成2组；进行构思，和小范围内的讨论。\u003c/p>\u003cp>【A3】促动参与\u003c/p>\u003cp>提问设计\u003c/p>\u003cp>方法已经学习过了，现在请大家练习一下。请大家利用刚才学习到的教学故事，解决一个生活中遇到的教学问题：我的二伯母不会使用微信，据自己说是学不会，那么现在给大家的任务是如何去说服她学微信\u003c/p>\u003cp>第一步，2分钟思考进行构思；\u003c/p>\u003cp>第二步，请分组扮演，侄子（侄女）说服二伯母学微信；\u003c/p>\u003cp>第三步，讲具体功能。\u003c/p>\u003cp>学习者案例\u003c/p>\u003cp>参与者1：zero，扮演侄女；RWX，扮演二伯母\u003c/p>\u003cp>Zero故事的主线就是通过朋友圈可以买到折扣相当大的项链，主讲微信的分享功能；\u003c/p>\u003cp>Zero讲的故事是邻居阿姨用朋友圈买到了一个1折的漂亮项链，说到了二伯母的心里，原来朋友圈可以买到物美价廉的东西。在激起好奇心后zero讲了微信的朋友圈的分享功能。成功将书中拆段知识进行了应用；\u003c/p>\u003cp>参与者2：Annie，扮演侄女；RWX，扮演二伯母\u003c/p>\u003cp>Annie构思的故事是自己亲身经历的自己的另一叔叔去国外了，如何和国内亲人交流，借这个故事说服二伯母，因为二伯母的孙子与她不住在一起，通过微信可以拉近二伯母与孙子的距离。同样非常成功的将微信的语音视频功能讲给了二伯母，二伯母从中看到了好处，激起了学习欲望，是成功的教学故事。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1500865171000,"updated_at":1500865171000,"ria":true}]};